import { createAdminClient, createServerSupabaseClient } from '@/lib/db'
import { redirect } from 'next/navigation'

export default async function AnalyticsRedirect() {
  const db = await createServerSupabaseClient()
  const { data: { user } } = await db.auth.getUser()

  if (!user) {
    redirect('/login')
  }

  const { data: profile } = await db
    .from('profiles')
    .select('group_id')
    .eq('id', user.id)
    .single()

  if (profile?.group_id) {
    redirect(`/analytics/${profile.group_id}`)
  } else {
    // If no group, send to network to find one
    redirect('/network')
  }
}

import { NextResponse } from 'next/server'
import { getAdminAuth, getAdminDb, getRequestUser } from '@/lib/supabase/admin'
export const dynamic = 'force-dynamic'


// Mock checkBotId as it's legacy and caused build failures
const checkBotId = async () => ({ isBot: false })

export async function GET(req: Request) {
  try {
    const user = await getRequestUser(req)
    if (!user) {
      return new NextResponse('Unauthorized Pipeline', { status: 401 })
    }
    const adminDb = getAdminDb()
    const uid = user.id

    const [profileResult, tasksResult, artifactsResult] = await Promise.all([
      adminDb.from('profiles').select('*').eq('id', uid).single(),
      adminDb.from('tasks').select('*').contains('assignees', [uid]),
      adminDb.from('artifacts').select('*').eq('uploaded_by', uid),
    ])

    if (profileResult.error) {
      return new NextResponse(`Server Fault: ${profileResult.error.message}`, { status: 500 })
    }
    if (!profileResult.data) {
      return new NextResponse('Profile Not Found', { status: 404 })
    }

    if (tasksResult.error || artifactsResult.error) {
      return new NextResponse(
        `Server Fault: ${tasksResult.error?.message ?? artifactsResult.error?.message}`,
        { status: 500 }
      )
    }

    const profileData = profileResult.data
    const tasksData = tasksResult.data ?? []
    const artifactsData = artifactsResult.data ?? []

    // Assemble "Takeout" Package
    const exportData = {
      version: '1.0.0',
      exported_at: new Date().toISOString(),
      identity: profileData,
      execution_log: tasksData,
      evidence_ledger: artifactsData
    }

    return new NextResponse(JSON.stringify(exportData, null, 2), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Content-Disposition': `attachment; filename="Espeezy-archive-${uid}.json"`
      }
    })

  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error'
    console.error("Export Engine Failure:", msg)
    return new NextResponse(`Server Fault: ${msg}`, { status: 500 })
  }
}

export async function DELETE(req: Request) {
  try {
    const user = await getRequestUser(req)
    if (!user) {
      return new NextResponse('Unauthorized Pipeline', { status: 401 })
    }
    const adminAuth = getAdminAuth()
    const adminDb = getAdminDb()
    const uid = user.id

    const { error: deleteAuthError } = await adminAuth.admin.deleteUser(uid)
    if (deleteAuthError) {
      return new NextResponse(`Server Fault: ${deleteAuthError.message}`, { status: 500 })
    }
    
    const { error: deleteProfileError } = await adminDb.from('profiles').delete().eq('id', uid)
    if (deleteProfileError) {
      return new NextResponse(`Server Fault: ${deleteProfileError.message}`, { status: 500 })
    }

    return new NextResponse('Account successfully terminated.', { status: 200 })

  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error'
    console.error("Termination Engine Failure:", msg)
    return new NextResponse(`Server Fault: ${msg}`, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getAdminDb } from '@/lib/supabase/admin'
import { getAuthUser, getUserProfile } from '@/utils/auth-server'
import { Profile } from '@/types/auth'

export const dynamic = 'force-dynamic'

async function requireAdmin() {
  const user = await getAuthUser()
  if (!user) return null
  const profile = await getUserProfile(user.uid)
  if (!profile || (profile as Profile).role !== 'admin') return null
  
  const db = getAdminDb()
  if (!db) return null
  
  return { user, db }
}

export async function GET() {
  const auth = await requireAdmin()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { db } = auth

  try {
    const { data: agentsList, error: agentsError } = await db
      .from('agents')
      .select('*')
      .order('specialisation', { ascending: true })
    if (agentsError) {
      throw agentsError
    }
    
    // Resolve "pair" information manually
    const agents = (agentsList ?? []).map((agent: any) => {
      if (agent.pair_id) {
        const pair = (agentsList ?? []).find((a: any) => a.id === agent.pair_id)
        if (pair) {
          return { ...agent, pair: { id: (pair as any).id, name: (pair as any).name } }
        }
      }
      return { ...agent, pair: null }
    })

    const { data: tasks, error: tasksError } = await db
      .from('agent_tasks')
      .select('*')
      .neq('status', 'done')
      .order('status', { ascending: true })
      .order('created_at', { ascending: false })

    if (tasksError) {
      throw tasksError
    }

    return NextResponse.json({ agents, tasks: tasks ?? [] })
  } catch (error) {
    console.error('[admin-agents] GET error:', error)
    return NextResponse.json({ error: 'Failed to fetch agents and tasks' }, { status: 500 })
  }
}

export async function POST(req: Request) {
  const auth = await requireAdmin()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { db } = auth
  const body = await req.json()
  const { name, specialisation, role, status, system_prompt, capabilities } = body

  if (!name || !specialisation || !role) {
    return NextResponse.json({ error: 'name, specialisation, and role are required' }, { status: 400 })
  }

  try {
    const agentData = {
      name,
      specialisation,
      role,
      status: status ?? 'active',
      system_prompt: system_prompt ?? '',
      capabilities: capabilities ?? [],
    }

    const { data: saved, error } = await db
      .from('agents')
      .insert(agentData)
      .select('*')
      .single()

    if (error || !saved) {
      throw error ?? new Error('Failed to create agent')
    }

    return NextResponse.json({ agent: saved }, { status: 201 })
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getAdminDb } from '@/lib/supabase/admin'
import { getAuthUser, getUserProfile } from '@/utils/auth-server'
import { Profile } from '@/types/auth'

export const dynamic = 'force-dynamic'

export async function GET() {
  const db = getAdminDb()

  const keys = ['launch_date', 'launch_message', 'preregister_goal', 'preregister_open', 'brand_name']
  const config: Record<string, any> = {}

  try {
    const { data, error } = await db
      .from('app_config')
      .select('key, value')
      .in('key', keys)

    if (error) {
      throw error
    }

    for (const row of data ?? []) {
      config[row.key] = row.value
    }

    return NextResponse.json({ config })
  } catch (error) {
    console.error('[launch-config] GET error:', error)
    return NextResponse.json({ error: 'Failed to fetch configuration' }, { status: 500 })
  }
}

export async function PUT(req: Request) {
  const user = await getAuthUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const profile = await getUserProfile(user.uid)
  if (!profile || (profile as Profile).role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const db = getAdminDb()

  const updates: Array<{ key: string; value: string }> = await req.json()
  if (!Array.isArray(updates)) {
    return NextResponse.json({ error: 'Expected array of {key, value} pairs.' }, { status: 400 })
  }

  const ALLOWED_KEYS = ['launch_date', 'launch_message', 'preregister_goal', 'preregister_open', 'brand_name', 'platform_version']
  const filtered = updates.filter(u => ALLOWED_KEYS.includes(u.key) && typeof u.value === 'string')

  try {
    const now = new Date().toISOString()

    const payload = filtered.map((u) => ({
      key: u.key,
      value: u.value,
      updated_at: now,
      updated_by: user.uid,
    }))

    const { error } = await db
      .from('app_config')
      .upsert(payload, { onConflict: 'key' })

    if (error) {
      throw error
    }

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('[admin-config] batch update error:', error)
    return NextResponse.json({ error: 'Failed to save configuration.' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { requireAdmin, isAuthError, writeAuditLog } from '@/utils/admin-auth'

export const dynamic = 'force-dynamic'

const querySchema = z.object({
  page:   z.string().optional().default('1'),
  limit:  z.string().optional().default('20'),
  search: z.string().optional().default(''),
  role:   z.string().optional().default(''),
  plan:   z.string().optional().default(''),
  status: z.string().optional().default(''),
  sort:   z.string().optional().default('created_at'),
  order:  z.enum(['asc', 'desc']).optional().default('desc'),
})

export async function GET(req: Request) {
  const ctx = await requireAdmin()
  if (isAuthError(ctx)) return ctx

  const { searchParams } = new URL(req.url)
  const parsed = querySchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: 'Invalid query parameters' }, { status: 422 })
  }

  const { page, limit, search, role, plan, status, sort, order } = parsed.data
  const pageNum  = Math.max(1, parseInt(page, 10))
  const pageSize = Math.min(100, Math.max(1, parseInt(limit, 10)))
  const offset   = (pageNum - 1) * pageSize

  let query = ctx.svc
    .from('profiles')
    .select('id, full_name, email, role, subscription_plan, account_status, is_banned, created_at, last_seen, avatar_url, tagline', { count: 'exact' })

  if (search) {
    query = query.or(`full_name.ilike.%${search}%,email.ilike.%${search}%`)
  }
  if (role)   query = query.eq('role', role)
  if (plan)   query = query.eq('subscription_plan', plan)
  if (status) query = query.eq('account_status', status)

  const validSortCols = ['created_at', 'full_name', 'email', 'last_seen', 'subscription_plan']
  const sortCol = validSortCols.includes(sort) ? sort : 'created_at'

  const { data, count, error } = await query
    .order(sortCol, { ascending: order === 'asc' })
    .range(offset, offset + pageSize - 1)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  return NextResponse.json({
    users: data ?? [],
    total: count ?? 0,
    page: pageNum,
    pageSize,
    totalPages: Math.ceil((count ?? 0) / pageSize),
  })
}

import { NextResponse } from 'next/server'
import { createAdminClient, createServerSupabaseClient } from '@/lib/db'
export const dynamic = 'force-dynamic'


const OPENAI_API_URL = process.env.OPENAI_API_BASE || 'https://api.openai.com/v1'
const OPENAI_API_KEY = process.env.OPENAI_API_KEY || process.env.AI_API_KEY || process.env.AI_GATEWAY_KEY

export async function POST(req: Request) {
  if (!OPENAI_API_KEY) {
    return new NextResponse(JSON.stringify({ error: 'AI API key is not configured.' }), { status: 500 })
  }

  const db = await createServerSupabaseClient()
  const { data: { user }, error: authError } = await db.auth.getUser()

  if (authError || !user) {
    return new NextResponse(JSON.stringify({ error: 'Authentication required.' }), { status: 401 })
  }

  try {
    const { title, category, dueDate, existingDescription } = await req.json()
    if (!title) {
      return new NextResponse(JSON.stringify({ error: 'Task title is required.' }), { status: 400 })
    }

    const windowStart = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
    const { count, error: countError } = await db
      .from('ai_usage')
      .select('id', { count: 'exact' })
      .eq('profile_id', user.id)
      .gte('created_at', windowStart)

    if (countError) {
      return new NextResponse(JSON.stringify({ error: 'Unable to verify AI usage limit.' }), { status: 500 })
    }

    if ((count ?? 0) >= 5) {
      return new NextResponse(JSON.stringify({ error: 'AI usage limit reached. Please try again after 24 hours.' }), { status: 429 })
    }

    const prompt = `Create a polished task description for a collaborative work tracker. Title: ${title.trim()}. Category: ${category}. Due date: ${dueDate ?? 'none'}. ${existingDescription ? 'Use the existing description as a starting point: ' + existingDescription : ''} Respond with a concise, clear task description only.`

    const response = await fetch(`${OPENAI_API_URL}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${OPENAI_API_KEY}`
      },
      body: JSON.stringify({
        model: 'gpt-3.5-turbo',
        messages: [
          { role: 'system', content: 'You are a helpful AI assistant for generating clear task descriptions in a team productivity app.' },
          { role: 'user', content: prompt }
        ],
        temperature: 0.7,
        max_tokens: 220
      })
    })

    if (!response.ok) {
      const errorText = await response.text()
      return new NextResponse(JSON.stringify({ error: `AI request failed: ${errorText}` }), { status: response.status })
    }

    const data = await response.json()
    const text = data?.choices?.[0]?.message?.content?.trim()

    if (!text) {
      return new NextResponse(JSON.stringify({ error: 'AI did not return a valid description.' }), { status: 502 })
    }

    await db.from('ai_usage').insert([{ profile_id: user.id, action: 'task_description' }])

    return new NextResponse(JSON.stringify({ description: text }), { status: 200 })
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'AI generation failed.'
    return new NextResponse(JSON.stringify({ error: msg }), { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { createAdminClient, createServerSupabaseClient } from '@/lib/db'
export const dynamic = 'force-dynamic'


const OPENAI_API_URL = process.env.OPENAI_API_BASE || 'https://api.openai.com/v1'
const OPENAI_API_KEY = process.env.AI_GATEWAY_API_KEY || process.env.OPENAI_API_KEY

export async function POST(req: Request) {
  if (!OPENAI_API_KEY) {
    return new NextResponse(JSON.stringify({ error: 'AI Gateway is not configured.' }), { status: 500 })
  }

  const db = await createServerSupabaseClient()
  const { data: { user }, error: authError } = await db.auth.getUser()

  if (authError || !user) {
    return new NextResponse(JSON.stringify({ error: 'Authentication required.' }), { status: 401 })
  }

  try {
    const { topic, difficulty, mode, count = 5 } = await req.json()
    
    // Usage Check
    const windowStart = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
    const { count: usageCount } = await db
      .from('ai_usage')
      .select('id', { count: 'exact' })
      .eq('profile_id', user.id)
      .gte('created_at', windowStart)

    if ((usageCount ?? 0) >= 20) { // Higher limit for gaming
      return new NextResponse(JSON.stringify({ error: 'Daily skirmish limit reached.' }), { status: 429 })
    }

    const prompt = `Generate ${count} high-quality academic skirmish questions about the topic: "${topic}".
Difficulty: ${difficulty.toUpperCase()}.
Mode Preference: ${mode === 'Evaluated' ? 'Prioritize Explanation questions' : 'Prioritize Multiple Choice questions'}.

Respond ONLY with a raw JSON array of objects. Do not include markdown formatting or backticks.
Schema:
{
  "id": string (unique),
  "question": string,
  "options": string[] (provide 4 options for multiple_choice, null for explanation),
  "correctAnswer": number (index for options) or string (comprehensive answer for explanation),
  "explanation": string (why it is correct),
  "type": "multiple_choice" | "explanation",
  "difficulty_multiplier": number (1 to 3 based on complexity)
}`

    const response = await fetch(`${OPENAI_API_URL}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${OPENAI_API_KEY}`
      },
      body: JSON.stringify({
        model: 'gpt-4o', // Preferred for logic/academic quality
        messages: [
          { role: 'system', content: 'You are a high-level academic skirmish engine for Espeezy. You generate rigorous, challenging questions that test deep understanding. Return results in pure JSON.' },
          { role: 'user', content: prompt }
        ],
        temperature: 0.8,
        response_format: { type: "json_object" }
      })
    })

    if (!response.ok) {
        const err = await response.text()
        throw new Error(err)
    }

    const data = await response.json()
    const content = data?.choices?.[0]?.message?.content
    
    // Parse result (GPT might wrap in an object even if asked for array)
    let questions = JSON.parse(content)
    if (questions.questions) questions = questions.questions // handle common wrapper

    await db.from('ai_usage').insert([{ profile_id: user.id, action: 'skirmish_generation' }])

    return new NextResponse(JSON.stringify({ questions }), { status: 200 })
  } catch (err: unknown) {
    console.error('Quiz Gen Error:', err instanceof Error ? err.message : err)
    return new NextResponse(JSON.stringify({ error: 'Failed to synthesize skirmish data.' }), { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getAdminDb, getRequestUser } from '@/lib/supabase/admin'

export const dynamic = 'force-dynamic'

const QUOTAS = {
  free: 1024 * 1024 * 1024, // 1GB
  pro: 5 * 1024 * 1024 * 1024, // 5GB
  premium: 20 * 1024 * 1024 * 1024, // 20GB
  admin: 100 * 1024 * 1024 * 1024, // 100GB
}

// GET /api/assets - List user assets with pagination and search
export async function GET(req: NextRequest) {
  try {
    const user = await getRequestUser(req)
    if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const { searchParams } = new URL(req.url)
    const queryStr = searchParams.get('q')
    const cursor = searchParams.get('cursor')
    const limit = Math.min(parseInt(searchParams.get('limit') ?? '20', 10), 50)

    const adminDb = getAdminDb()
    let query = adminDb
      .from('personal_assets')
      .select('*')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })
      .limit(limit + 1)

    if (queryStr) {
      query = query.ilike('title', `%${queryStr}%`)
    }
    if (cursor) {
      query = query.lt('created_at', cursor)
    }

    const { data: rows, error } = await query

    if (error) throw error

    const hasMore = (rows?.length ?? 0) > limit
    const assets = hasMore ? rows?.slice(0, limit) : rows
    const nextCursor = hasMore ? assets?.[assets.length - 1].created_at : null

    return NextResponse.json({ assets, nextCursor })
  } catch (err: unknown) {
    return NextResponse.json({ error: err instanceof Error ? err.message : 'Unknown error' }, { status: 500 })
  }
}

// POST /api/assets - Create/Upload asset
export async function POST(req: NextRequest) {
  try {
    const user = await getRequestUser(req)
    if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const contentType = req.headers.get('content-type') || ''
    const adminDb = getAdminDb()
    
    let title: string
    let description: string | null = null
    let asset_type: 'file' | 'link' | 'marketplace_ref' = 'file'
    let asset_url: string
    let size_bytes: number = 0
    let category: string | null = null
    let folder: string = '/'

    if (contentType.includes('multipart/form-data')) {
      const formData = await req.formData()
      const file = formData.get('file') as File | null
      title = formData.get('title') as string || file?.name || 'Untitled Asset'
      description = formData.get('description') as string
      category = formData.get('category') as string
      folder = formData.get('folder') as string || '/'
      
      if (!file) return NextResponse.json({ error: 'No file provided' }, { status: 400 })
      
      size_bytes = file.size
      asset_type = 'file'

      // Upload to Storage
      const path = `${user.id}/${folder.replace(/^\/+|\/+$/g, '')}/${file.name}`.replace(/\/+/g, '/')
      const { data: storageData, error: storageError } = await adminDb.storage
        .from('user-assets')
        .upload(path, file, { upsert: true, contentType: file.type })

      if (storageError) throw storageError

      // Get public URL
      const { data: { publicUrl } } = adminDb.storage
        .from('user-assets')
        .getPublicUrl(path)
      
      asset_url = publicUrl
    } else {
      const body = await req.json()
      title = body.title
      description = body.description
      asset_type = body.asset_type || 'link'
      asset_url = body.asset_url
      size_bytes = body.size_bytes || 0
      category = body.category
      folder = body.folder || '/'
    }

    if (!title || !asset_url) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 })
    }

    // 1. Check Quota
    const { data: profile, error: profileError } = await adminDb
      .from('profiles')
      .select('tier, storage_used')
      .eq('id', user.id)
      .single()

    if (profileError) throw profileError

    const tier = (profile.tier as keyof typeof QUOTAS) || 'free'
    const quota = QUOTAS[tier]
    
    if (profile.storage_used + size_bytes > quota) {
      return NextResponse.json({ 
        error: 'Quota Exceeded', 
        message: `Your current tier (${tier}) is limited to ${quota / (1024*1024*1024)}GB.` 
      }, { status: 403 })
    }

    // 2. Insert Asset Metadata
    const { data: asset, error: insertError } = await adminDb
      .from('personal_assets')
      .insert({
        user_id: user.id,
        title,
        description,
        asset_type,
        asset_url,
        size_bytes,
        category,
        folder
      })
      .select()
      .single()

    if (insertError) throw insertError

    // 3. Update profile storage_used
    await adminDb.rpc('increment_storage_used', { 
      user_id: user.id, 
      amount: size_bytes 
    })

    // 4. Seed README if it's the first asset
    const { count } = await adminDb
      .from('personal_assets')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', user.id)

    if (count === 1) {
      // Seed README.txt
      const readmeContent = `Welcome to your Espeezy Storage!\n\nThis is your private node for academic assets.\nHappy building!`
      const readmePath = `${user.id}/README.txt`
      await adminDb.storage.from('user-assets').upload(readmePath, readmeContent, { contentType: 'text/plain' })
      
      // Also insert into table
      await adminDb.from('personal_assets').insert({
        user_id: user.id,
        title: 'README.txt',
        description: 'Storage instructions',
        asset_type: 'file',
        asset_url: adminDb.storage.from('user-assets').getPublicUrl(readmePath).data.publicUrl,
        size_bytes: readmeContent.length,
        folder: '/'
      })
    }

    return NextResponse.json({ asset }, { status: 201 })
  } catch (err: unknown) {
    return NextResponse.json({ error: err instanceof Error ? err.message : 'Unknown error' }, { status: 500 })
  }
}

// DELETE /api/assets - Delete asset
export async function DELETE(req: NextRequest) {
  try {
    const user = await getRequestUser(req)
    if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const { searchParams } = new URL(req.url)
    const id = searchParams.get('id')
    if (!id) return NextResponse.json({ error: 'Missing asset ID' }, { status: 400 })

    const adminDb = getAdminDb()

    // 1. Get asset to know its size and URL/path
    const { data: asset, error: fetchError } = await adminDb
      .from('personal_assets')
      .select('size_bytes, asset_url, asset_type, folder, title')
      .eq('id', id)
      .eq('user_id', user.id)
      .single()

    if (fetchError) throw fetchError

    // 2. Delete from Storage if it's a file
    if (asset.asset_type === 'file') {
      // Extract path from URL or reconstruct it
      // Standard path: user_id/folder/title
      const cleanFolder = asset.folder.replace(/^\/+|\/+$/g, '')
      const storagePath = `${user.id}/${cleanFolder ? cleanFolder + '/' : ''}${asset.title}`.replace(/\/+/g, '/')
      
      const { error: storageDeleteError } = await adminDb.storage
        .from('user-assets')
        .remove([storagePath])
      
      // We don't strictly throw here if file is missing (maybe already gone)
      if (storageDeleteError) console.error('Storage delete error:', storageDeleteError)
    }

    // 3. Delete from DB
    const { error: deleteError } = await adminDb
      .from('personal_assets')
      .delete()
      .eq('id', id)
      .eq('user_id', user.id)

    if (deleteError) throw deleteError

    // 4. Update profile storage_used (negative amount)
    await adminDb.rpc('increment_storage_used', { 
      user_id: user.id, 
      amount: -asset.size_bytes 
    })

    return NextResponse.json({ success: true })
  } catch (err: unknown) {
    return NextResponse.json({ error: err instanceof Error ? err.message : 'Unknown error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { canAccessFeature, FEATURE_TIERS } from '@/lib/tier-utils'

export const dynamic = 'force-dynamic'

function decodeJwt(token: string): Record<string, any> | null {
  try {
    const parts = token.split('.')
    if (parts.length !== 3) return null
    const payload = Buffer.from(parts[1], 'base64url').toString('utf8')
    return JSON.parse(payload)
  } catch {
    return null
  }
}

export async function GET(req: Request) {
  const { searchParams } = new URL(req.url)
  const feature = searchParams.get('feature') as keyof typeof FEATURE_TIERS | null

  // Get auth token from Authorization header
  const authHeader = req.headers.get('Authorization')
  if (!authHeader?.startsWith('Bearer ')) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const token = authHeader.slice(7)
  const payload = decodeJwt(token)

  if (!payload || !payload.sub) {
    return NextResponse.json({ error: 'Invalid token' }, { status: 401 })
  }

  const userId = payload.sub
  const userEmail = payload.email

  // Get Supabase config
  const supabaseUrl = (process.env.NEXT_PUBLIC_SUPABASE_URL ?? process.env.PROJECT_URL ?? '').trim()
  const supabaseKey = (process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.SECRET_KEY ?? '').trim()

  if (!supabaseUrl || !supabaseKey) {
    return NextResponse.json({ error: 'Service misconfigured' }, { status: 500 })
  }

  // Get user's tier from profiles table
  const profileRes = await fetch(`${supabaseUrl}/rest/v1/profiles?id=eq.${encodeURIComponent(userId)}&select=tier`, {
    headers: {
      apikey: supabaseKey,
      Authorization: `Bearer ${supabaseKey}`,
    },
  }).catch(() => null)

  let tier = 'free'
  if (profileRes?.ok) {
    const profiles = await profileRes.json().catch(() => [])
    if (Array.isArray(profiles) && profiles.length > 0) {
      tier = profiles[0].tier ?? 'free'
    }
  }

  // If no feature requested, return tier info
  if (!feature) {
    return NextResponse.json({
      user_id: userId,
      email: userEmail,
      tier,
    })
  }

  // Check if feature exists
  if (!(feature in FEATURE_TIERS)) {
    return NextResponse.json(
      { error: `Unknown feature: ${feature}` },
      { status: 400 }
    )
  }

  const requiredTier = FEATURE_TIERS[feature]
  const hasAccess = canAccessFeature(tier, requiredTier)

  return NextResponse.json({
    user_id: userId,
    email: userEmail,
    tier,
    feature,
    required_tier: requiredTier,
    has_access: hasAccess,
    ...(hasAccess ? {} : { error: `Requires ${requiredTier} subscription` }),
  }, { status: hasAccess ? 200 : 403 })
}

/**
 * GET /api/cron/expire-verifications
 * Marks student_verifications as 'expired' when expires_at has passed.
 *
 * Configured in vercel.json as a Vercel Cron Job running daily at 03:00 UTC.
 * Protected by CRON_SECRET header.
 */
import { NextRequest, NextResponse } from 'next/server'
import { createAdminClient, createServerSupabaseClient } from '@/lib/db'

export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest) {
  const secret = process.env.CRON_SECRET
  if (secret && req.headers.get('authorization') !== `Bearer ${secret}`) {
    return new NextResponse('Unauthorized', { status: 401 })
  }

  const svc = await createAdminClient()
  const { data, error } = await svc
    .from('student_verifications')
    .update({ status: 'expired' })
    .eq('status', 'approved')
    .lt('expires_at', new Date().toISOString())
    .select('id')

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  return NextResponse.json({ expired: data?.length ?? 0 })
}

