}

async function insertDonationInitiated(params: {
  stripeSessionId: string
  amountCents: number
  donorEmail?: string
  donorName?: string
  message?: string
  featureTag?: string
  isAnonymous: boolean
}) {
  const cfg = getSupabaseConfig()
  if (!cfg) return

  const payload = {
    stripe_session_id: params.stripeSessionId,
    amount_cents: params.amountCents,
    currency: 'gbp',
    donor_email: params.isAnonymous ? null : (params.donorEmail || null),
    donor_name: params.isAnonymous ? null : (params.donorName || null),
    message: params.message || null,
    feature_tag: params.featureTag || 'general',
    is_anonymous: params.isAnonymous,
    status: 'pending',
    metadata: {
      source: 'checkout_session_created',
    },
  }

  await fetch(`${cfg.url}/rest/v1/donations`, {
    method: 'POST',
    headers: {
      apikey: cfg.key,
      Authorization: `Bearer ${cfg.key}`,
      'Content-Type': 'application/json',
      Prefer: 'resolution=merge-duplicates,return=minimal',
    },
    body: JSON.stringify(payload),
  }).catch(() => {
    // Donation checkout should continue even if tracking insert fails.
  })
}

export async function POST(req: Request) {
  if (!process.env.STRIPE_SECRET_KEY) {
    return NextResponse.json(
      { error: 'Donation service is not available right now. Please try again later.' },
      { status: 503 }
    )
  }
  try {
    const stripe = getStripeClient()
    const body = await req.json().catch(() => null)
    const parsedBody = donationSchema.safeParse(body)
    if (!parsedBody.success) {
      return NextResponse.json(
        { error: 'Donation amount must be between £1.00 and £10,000.' },
        { status: 422 }
      )
    }

    const { amountCents, donorEmail, donorName, message, featureTag, isAnonymous = false } = parsedBody.data

    const origin = req.headers.get('x-app-origin') ?? req.headers.get('origin') ?? getAppUrl()

    // Use a canonical Stripe price ID for known GBP amounts; fall back to price_data for custom amounts
    const knownPriceId = GBP_PRICE_MAP[amountCents]
    const stripeProductId = getStripeFundProductId(featureTag || 'general')

    const lineItem = knownPriceId
      ? { price: knownPriceId, quantity: 1 }
      : {
          price_data: stripeProductId
            ? {
                currency: 'gbp',
                unit_amount: amountCents,
                product: stripeProductId,
              }
            : {
                currency: 'gbp',
                unit_amount: amountCents,
                product_data: {
                  name: featureTag
                    ? `Espeezy  -  ${featureTag}`
                    : 'Espeezy  -  Mission Support Donation',
                  description:
                    'Your contribution funds free, equitable education tools for students worldwide.',
                  images: [`${origin}/assets/og-image.png`],
                },
              },
          quantity: 1,
        }

    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      payment_method_types: ['card'],
      line_items: [lineItem],
      customer_email: isAnonymous ? undefined : (donorEmail || undefined),
      success_url: `${origin}/donation/success?session_id={CHECKOUT_SESSION_ID}&amount=${(amountCents / 100).toFixed(2)}`,
      cancel_url: `${origin}/fund`,
      billing_address_collection: 'auto',
      submit_type: 'donate',
      metadata: {
        type: 'donation',
        donor_name: isAnonymous ? 'Anonymous' : (donorName || ''),
        donor_email: isAnonymous ? '' : (donorEmail || ''),
        message: message || '',
        feature_tag: featureTag || 'general',
        is_anonymous: String(isAnonymous),
        stripe_product_id: stripeProductId || '',
      },
    })

    if (!session.url) {
      throw new Error('No Stripe session URL returned.')
    }

    await insertDonationInitiated({
      stripeSessionId: session.id,
      amountCents,
      donorEmail,
      donorName,
      message,
      featureTag,
      isAnonymous,
    })

    return NextResponse.json({ url: session.url })
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : 'Unknown Stripe error'
    console.error('[donate] Stripe error:', message)
    return NextResponse.json(
      { error: 'Could not initialize donation. Please try again.' },
      { status: 500 }
    )
  }
}

import { NextResponse } from 'next/server'
import { createAdminClient, createServerSupabaseClient } from '@/lib/db'
import { getAppUrl, getStripeClient, getStripePortalConfigurationId } from '@/utils/stripe'

export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'

export async function POST() {
  let stripe: import('stripe').default
  try {
    stripe = getStripeClient()
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Stripe is not configured'
    return NextResponse.json({ error: msg }, { status: 500 })
  }

  const db = await createServerSupabaseClient()
  const { data: { user } } = await db.auth.getUser()
    .catch(() => ({ data: { user: null } }))

  if (!user) {
    return NextResponse.json({ error: 'Authentication required.' }, { status: 401 })
  }

  // Get the stripe customer id from the profile
  const { data: profile } = await db
    .from('profiles')
    .select('stripe_customer_id')
    .eq('id', user.id)
    .single()

  if (!profile?.stripe_customer_id) {
    return NextResponse.json({ error: 'No active subscription found. Please upgrade first.' }, { status: 404 })
  }

  try {
    const configuration = getStripePortalConfigurationId()
    const session = await stripe.billingPortal.sessions.create({
      customer: profile.stripe_customer_id,
      ...(configuration ? { configuration } : {}),
      return_url: `${getAppUrl()}/settings`,
    })

    return NextResponse.json({ url: session.url })
  } catch (error: unknown) {
    console.error('Stripe Portal Error:', error)
    const message = error instanceof Error ? error.message : 'Stripe portal creation failed.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { taskWorkflow } from '@/workflows/taskWorkflow'
import { createAdminClient, createServerSupabaseClient } from '@/lib/db'
import { start } from '@/utils/workflow'
export const dynamic = 'force-dynamic'


export async function POST(req: Request) {
  const db = await createServerSupabaseClient()
  const { data: { user }, error: userError } = await db.auth.getUser()

  if (userError || !user) {
    return new NextResponse(JSON.stringify({ error: 'Authentication required.' }), { status: 401 })
  }

  const payload = await req.json()
  const workflowPayload = { ...payload, userId: user.id }

  try {
    const run = await start(taskWorkflow, [workflowPayload])
    return NextResponse.json({ runId: run.runId, status: await run.status }, { status: 202 })
  } catch (err: unknown) {
    return new NextResponse(JSON.stringify({ error: (err instanceof Error ? err.message : null) || 'Workflow startup failed.' }), { status: 500 })
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { 
  File, 
  Link as LinkIcon, 
  ShoppingBag, 
  Plus, 
  Trash2, 
  ExternalLink,
  Loader2,
  HardDrive,
  Filter,
  MoreVertical
} from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import { useProfile } from '@/context/ProfileContext'
import { useNotifications } from '@/components/NotificationProvider'
import ModalOverlay from '@/components/ModalOverlay'

interface Asset {
  id: string
  title: string
  description?: string
  asset_type: 'file' | 'link' | 'marketplace_ref'
  asset_url: string
  preview_url?: string
  category?: string
  size_bytes: number
  created_at: string
  folder?: string
}

const QUOTAS = {
  free: 1024 * 1024 * 1024, // 1GB
  pro: 5 * 1024 * 1024 * 1024, // 5GB
  premium: 20 * 1024 * 1024 * 1024, // 20GB
  admin: 100 * 1024 * 1024 * 1024, // 100GB
}

export default function PersonalAssetsPage() {
  const { profile } = useProfile()
  const { addToast } = useNotifications()
  const [assets, setAssets] = useState<Asset[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<'all' | 'file' | 'link' | 'marketplace_ref'>('all')
  const [currentFolder, setCurrentFolder] = useState('/')
  const [showUploadModal, setShowUploadModal] = useState(false)
  
  const fetchAssets = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/assets')
      if (res.ok) {
        const data = await res.json()
        setAssets(data.assets || [])
      }
    } catch (err) {
      addToast('Error', 'Failed to load assets', 'error')
    } finally {
      setLoading(false)
    }
  }, [addToast])

  useEffect(() => {
    fetchAssets()
  }, [fetchAssets])

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to remove this asset?')) return
    
    try {
      const res = await fetch(`/api/assets?id=${id}`, { method: 'DELETE' })
      if (res.ok) {
        setAssets(prev => prev.filter(a => a.id !== id))
        addToast('Deleted', 'Asset removed successfully', 'success')
      }
    } catch (err) {
      addToast('Error', 'Failed to delete asset', 'error')
    }
  }

  const filteredAssets = assets.filter(a => {
    const matchesFilter = filter === 'all' || a.asset_type === filter
    const matchesFolder = a.folder === currentFolder
    return matchesFilter && matchesFolder
  })
  
  const tier = (profile?.subscription_plan?.toLowerCase() as keyof typeof QUOTAS) || 'free'
  const quota = QUOTAS[tier]
  const storageUsed = assets.reduce((acc, a) => acc + (a.size_bytes || 0), 0)
  const percentUsed = Math.min(100, (storageUsed / quota) * 100)

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B'
    const k = 1024
    const sizes = ['B', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '2rem 1rem' }}>
      
      {/* Header & Quota */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '3rem', flexWrap: 'wrap', gap: '2rem' }}>
        <div>
          <h1 style={{ fontSize: '2.5rem', fontWeight: 950, letterSpacing: '-0.05em', color: 'white', margin: 0 }}>
            Personal <span style={{ color: 'var(--brand)' }}>Inventory</span>
          </h1>
          <p style={{ color: 'var(--text-sub)', marginTop: '0.5rem', fontWeight: 600 }}>Your secure node for academic assets and marketplace refs.</p>
        </div>

        <div style={{ width: '320px', background: 'var(--bg-sub)', padding: '1.5rem', borderRadius: '24px', border: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--text-main)', fontWeight: 800, fontSize: '0.85rem' }}>
              <HardDrive size={16} color="var(--brand)" />
              Storage Used
            </div>
            <span style={{ fontSize: '0.75rem', fontWeight: 900, color: 'var(--brand)' }}>{formatSize(storageUsed)} / {formatSize(quota)}</span>
          </div>
          <div style={{ height: '8px', background: 'rgba(255,255,255,0.05)', borderRadius: '100px', overflow: 'hidden' }}>
            <motion.div 
              initial={{ width: 0 }}
              animate={{ width: `${percentUsed}%` }}
              style={{ height: '100%', background: 'var(--brand)', borderRadius: '100px' }} 
            />
          </div>
          <div style={{ marginTop: '0.75rem', fontSize: '0.65rem', color: 'var(--text-sub)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            Current Tier: <span style={{ color: 'white' }}>{tier.toUpperCase()}</span>
          </div>
        </div>
      </div>

      {/* Breadcrumbs */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1.5rem', fontSize: '0.85rem', fontWeight: 700 }}>
        <button onClick={() => setCurrentFolder('/')} style={{ background: 'none', border: 'none', color: currentFolder === '/' ? 'white' : 'var(--text-sub)', cursor: 'pointer' }}>Root</button>
        {currentFolder !== '/' && currentFolder.split('/').filter(Boolean).map((f, i, arr) => (
          <div key={f} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span style={{ opacity: 0.3 }}>/</span>
            <button 
              onClick={() => setCurrentFolder('/' + arr.slice(0, i + 1).join('/'))} 
              style={{ background: 'none', border: 'none', color: i === arr.length - 1 ? 'white' : 'var(--text-sub)', cursor: 'pointer' }}
            >
              {f}
            </button>
          </div>
        ))}
      </div>

      {/* Controls */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div style={{ display: 'flex', background: 'var(--bg-sub)', padding: '4px', borderRadius: '14px', border: '1px solid var(--border)' }}>
          {(['all', 'file', 'link', 'marketplace_ref'] as const).map(f => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              style={{
                padding: '0.5rem 1.25rem',
                borderRadius: '10px',
                border: 'none',
                background: filter === f ? 'var(--brand)' : 'transparent',
                color: filter === f ? 'black' : 'var(--text-sub)',
                fontWeight: 800,
                fontSize: '0.8rem',
                cursor: 'pointer',
                transition: '0.2s',
                textTransform: 'capitalize'
              }}
            >
              {f === 'marketplace_ref' ? 'Inventory' : f}
            </button>
          ))}
        </div>

        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button 
            onClick={() => {
              const name = prompt('Folder name:')
              if (name) {
                // In a real app we'd create a dummy entry or just let users upload to new paths
                setCurrentFolder(currentFolder === '/' ? `/${name}` : `${currentFolder}/${name}`)
              }
            }}
            style={{
              display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.75rem 1.25rem',
              background: 'var(--bg-sub)', color: 'white', borderRadius: '16px', border: '1px solid var(--border)',
              fontWeight: 800, fontSize: '0.85rem', cursor: 'pointer'
            }}
          >
            New Folder
          </button>
          <button 
            onClick={() => setShowUploadModal(true)}
            style={{
              display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.75rem 1.5rem',
              background: 'var(--brand)', color: 'black', borderRadius: '16px', border: 'none',
              fontWeight: 950, fontSize: '0.9rem', cursor: 'pointer'
            }}
          >
            <Plus size={18} /> Add Asset
          </button>
        </div>
      </div>

      {/* Grid */}
      {loading ? (
        <div style={{ textAlign: 'center', padding: '5rem' }}>
          <Loader2 size={40} className="animate-spin" style={{ color: 'var(--brand)', margin: '0 auto' }} />
        </div>
      ) : filteredAssets.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '8rem 2rem', background: 'var(--bg-sub)', borderRadius: '32px', border: '2px dashed var(--border)' }}>
          <File size={48} style={{ margin: '0 auto', opacity: 0.1, marginBottom: '1.5rem' }} />
          <h3 style={{ color: 'var(--text-sub)', fontWeight: 800 }}>No assets found in this sector.</h3>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '1.5rem' }}>
          <AnimatePresence>
            {filteredAssets.map((asset, idx) => (
              <AssetCard key={asset.id} asset={asset} onDelete={() => handleDelete(asset.id)} />
            ))}
          </AnimatePresence>
        </div>
      )}

      {/* Upload Modal */}
      {showUploadModal && (
        <UploadModal 
          currentFolder={currentFolder}
          onClose={() => setShowUploadModal(false)} 
          onSuccess={() => { setShowUploadModal(false); fetchAssets(); }} 
        />
      )}

    </div>
  )
}

