function UploadModal({ currentFolder, onClose, onSuccess }: { currentFolder: string, onClose: () => void, onSuccess: () => void }) {
  const [form, setForm] = useState({ title: '', description: '', asset_type: 'file' as Asset['asset_type'], asset_url: '', category: '' })
  const [file, setFile] = useState<File | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const handleSumbit = async () => {
    if (!form.title && !file) return setError('Title or file is required')
    if (form.asset_type === 'link' && !form.asset_url) return setError('URL is required for links')
    
    setLoading(true)
    setError('')
    
    try {
      let res: Response

      if (form.asset_type === 'file' && file) {
        const formData = new FormData()
        formData.append('file', file)
        formData.append('title', form.title || file.name)
        formData.append('description', form.description)
        formData.append('category', form.category)
        formData.append('folder', currentFolder)

        res = await fetch('/api/assets', {
          method: 'POST',
          body: formData
        })
      } else {
        res = await fetch('/api/assets', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...form, folder: currentFolder, size_bytes: 0 })
        })
      }

      if (res.ok) onSuccess()
      else {
        const d = await res.json()
        setError(d.error || 'Failed to save asset')
      }
    } catch (e) {
      setError('Network error')
    } finally {
      setLoading(false)
    }
  }

  return (
    <ModalOverlay maxWidth="500px" onClickOutside={onClose}>
      <div style={{ padding: '2rem' }}>
        <h2 style={{ margin: '0 0 1.5rem', fontWeight: 950 }}>Add New Asset</h2>
        
        {error && <div style={{ background: 'rgba(239, 68, 68, 0.1)', color: '#EF4444', padding: '0.75rem', borderRadius: '12px', marginBottom: '1.5rem', fontSize: '0.85rem', fontWeight: 700 }}>{error}</div>}
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          <div>
            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, color: 'var(--text-sub)', marginBottom: '0.5rem', textTransform: 'uppercase' }}>Asset Type</label>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
              <button 
                onClick={() => setForm(f => ({ ...f, asset_type: 'file' }))}
                style={{ padding: '0.75rem', borderRadius: '12px', border: '1px solid var(--border)', background: form.asset_type === 'file' ? 'var(--brand)' : 'var(--bg-sub)', color: form.asset_type === 'file' ? 'black' : 'white', fontWeight: 800, cursor: 'pointer' }}
              >File</button>
              <button 
                onClick={() => setForm(f => ({ ...f, asset_type: 'link' }))}
                style={{ padding: '0.75rem', borderRadius: '12px', border: '1px solid var(--border)', background: form.asset_type === 'link' ? 'var(--brand)' : 'var(--bg-sub)', color: form.asset_type === 'link' ? 'black' : 'white', fontWeight: 800, cursor: 'pointer' }}
              >Link</button>
            </div>
          </div>

          {form.asset_type === 'file' ? (
            <div>
              <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, color: 'var(--text-sub)', marginBottom: '0.5rem', textTransform: 'uppercase' }}>Upload File</label>
              <input 
                type="file" 
                onChange={e => {
                  const f = e.target.files?.[0]
                  if (f) {
                    setFile(f)
                    if (!form.title) setForm(prev => ({ ...prev, title: f.name }))
                  }
                }}
                style={{ width: '100%', padding: '0.75rem', background: 'var(--bg-sub)', border: '1px dashed var(--border)', borderRadius: '12px', color: 'white' }}
              />
            </div>
          ) : (
            <div>
              <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, color: 'var(--text-sub)', marginBottom: '0.5rem', textTransform: 'uppercase' }}>Link URL</label>
              <input 
                type="url" 
                className="form-input" 
                value={form.asset_url} 
                onChange={e => setForm(f => ({ ...f, asset_url: e.target.value }))}
                placeholder="https://..."
                style={{ background: 'var(--bg-sub)', border: '1px solid var(--border)' }}
              />
            </div>
          )}

          <div>
            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, color: 'var(--text-sub)', marginBottom: '0.5rem', textTransform: 'uppercase' }}>Title</label>
            <input 
              type="text" 
              className="form-input" 
              value={form.title} 
              onChange={e => setForm(f => ({ ...f, title: e.target.value }))}
              placeholder="e.g. Design System V1"
              style={{ background: 'var(--bg-sub)', border: '1px solid var(--border)' }}
            />
          </div>

          <div>
            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, color: 'var(--text-sub)', marginBottom: '0.5rem', textTransform: 'uppercase' }}>Description (Optional)</label>
            <textarea 
              className="form-input" 
              value={form.description} 
              onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
              placeholder="A brief summary of this asset..."
              style={{ background: 'var(--bg-sub)', border: '1px solid var(--border)', minHeight: '80px', resize: 'none' }}
            />
          </div>
        </div>

        <div style={{ marginTop: '2.5rem', display: 'flex', gap: '1rem' }}>
          <button onClick={onClose} className="btn btn-secondary" style={{ flex: 1 }}>Cancel</button>
          <button 
            onClick={handleSumbit} 
            disabled={loading}
            className="btn btn-primary" 
            style={{ flex: 2, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}
          >
            {loading && <Loader2 size={16} className="animate-spin" />}
            {form.asset_type === 'file' ? 'Upload & Save' : 'Save Link'}
          </button>
        </div>
      </div>
    </ModalOverlay>
  )
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import Image from 'next/image'
import { createBrowserSupabaseClient } from '@/lib/db-client'
import { useRouter } from 'next/navigation'
import { ShieldCheck, Lock, Activity } from 'lucide-react'
import TransientError from '@/components/TransientError'

export default function ResetPasswordPage() {
  const router = useRouter()
  const supabase = useMemo(() => createBrowserSupabaseClient(), [])
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)
  const [loading, setLoading] = useState(false)
  const [sessionReady, setSessionReady] = useState(false)

  useEffect(() => {
    let mounted = true
    const checkSession = async () => {
      const result = await supabase.auth.getSession()
      if (!mounted) return
      if (!result?.data?.session) {
        setError('Recovery session not found. Please request a new password reset link.')
        return
      }
      setSessionReady(true)
    }
    checkSession()

    return () => {
      mounted = false
    }
  }, [supabase])

  const getErrorMessage = (err: unknown) => {
    if (err instanceof Error) return err.message
    return 'An unexpected error occurred.'
  }

  const handleReset = async (e: React.FormEvent) => {
    e.preventDefault()
    if (password !== confirmPassword) {
      setError('Passwords do not match.')
      return
    }
    if (password.length < 8) {
      setError('Password must be at least 8 characters.')
      return
    }

    setLoading(true)
    setError(null)

    try {
      const { error: updateError } = await supabase.auth.updateUser({ password })
      if (updateError) {
        throw updateError
      }
      setSuccess(true)
      setTimeout(() => router.push('/login'), 3000)
    } catch (err: unknown) {
      setError(getErrorMessage(err))
    } finally {
      setLoading(false)
    }
  }

  return (
    <div style={{
      minHeight: '100vh',
      width: '100%',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      position: 'relative',
      padding: '1.5rem',
      overflow: 'hidden',
      background: '#000'
    }}>
      {/* Background Image */}
      <div style={{ position: 'absolute', inset: 0, zIndex: 0 }}>
        <Image
          src="/auth_bg.png"
          alt="Auth Background"
          fill
          priority
          quality={80}
          style={{ objectFit: 'cover', opacity: 0.4 }}
        />
        {/* Dark overlay for text legibility */}
        <div style={{ position: 'absolute', inset: 0, background: 'radial-gradient(circle at center, transparent 0%, rgba(0,0,0,0.4) 100%)' }} />
      </div>

      <div
        style={{
          width: '100%',
          maxWidth: '480px',
          background: 'rgba(10, 10, 10, 0.4)',
          backdropFilter: 'blur(40px)',
          borderRadius: '40px',
          border: '1px solid rgba(255,255,255,0.1)',
          padding: '3.5rem',
          position: 'relative',
          zIndex: 1,
          boxShadow: '0 40px 100px rgba(0,0,0,0.6)',
          animation: 'fadeIn 0.8s cubic-bezier(0.16, 1, 0.3, 1)'
        }}
      >
        <div style={{ textAlign: 'center', marginBottom: '2.5rem' }}>
          <div style={{ width: '60px', height: '60px', background: 'var(--brand, #10b981)', borderRadius: '18px', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem', boxShadow: '0 12px 24px rgba(16,185,129,0.25)' }}>
            <Lock color="white" size={30} />
          </div>
          <h1 style={{ fontSize: '2rem', fontWeight: 900, color: 'white', letterSpacing: '-0.03em', margin: 0 }}>Secure Account Recovery</h1>
          <p style={{ color: 'rgba(255,255,255,0.5)', marginTop: '0.6rem', fontWeight: 600 }}>Update your password to regain access.</p>
        </div>

        {error && <TransientError message={error} />}
        
        {success ? (
          <div style={{ textAlign: 'center', padding: '1rem' }}>
            <div style={{ color: 'var(--success)', marginBottom: '1.5rem' }}>
              <ShieldCheck size={48} style={{ margin: '0 auto' }} />
            </div>
            <h3 style={{ fontWeight: 900, marginBottom: '0.5rem' }}>Password Updated</h3>
            <p style={{ color: 'var(--text-sub)', fontWeight: 600 }}>Your password has been successfully reset. Redirecting to login...</p>
          </div>
        ) : (
          <form onSubmit={handleReset} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
            <div className="form-group">
              <label className="form-label">New Password</label>
              <input 
                type="password" 
                className="form-input" 
                required 
                value={password} 
                onChange={e => setPassword(e.target.value)}
                placeholder="••••••••"
                style={{ borderRadius: '14px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', color: 'white' }}
                disabled={loading}
              />
            </div>
            <div className="form-group">
              <label className="form-label">Confirm Password</label>
              <input 
                type="password" 
                className="form-input" 
                required 
                value={confirmPassword} 
                onChange={e => setConfirmPassword(e.target.value)}
                placeholder="••••••••"
                style={{ borderRadius: '14px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', color: 'white' }}
                disabled={loading}
              />
            </div>
            <button className="btn btn-primary" type="submit" disabled={loading || !sessionReady} style={{ height: '3.5rem', borderRadius: '18px', fontWeight: 900, fontSize: '1.1rem' }}>
              {loading ? 'Updating Credentials...' : 'Update Password'}
            </button>
          </form>
        )}
      </div>
    </div>
  )
}

'use client'

import { motion } from 'framer-motion'
import { ShieldCheck, Download, CheckCircle2, AlertTriangle, Sparkles, ExternalLink } from 'lucide-react'
import Link from 'next/link'
import Image from 'next/image'

interface CertData {
  id: string
  programName: string
  issueDate: string
  graduationYear: number | null
  gpa: number | null
  achievements: string[]
  blockchainHash: string | null
  revoked: boolean
}

interface Props {
  cert: CertData
  displayName: string
  avatarUrl: string | null
  downloadUrl: string
}

export default function CertificateViewer({ cert, displayName, avatarUrl, downloadUrl }: Props) {
  const issueDate = new Date(cert.issueDate).toLocaleDateString('en-US', {
    year: 'numeric', month: 'long', day: 'numeric',
  })

  const isValid = !cert.revoked

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(180deg, #06100d 0%, #0a0a0a 70%)',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
