      padding: '4rem 1.5rem',
    }}>
      {/* Nav */}
      <Link href="/" style={{ position: 'fixed', top: '1.25rem', left: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', textDecoration: 'none', zIndex: 100 }}>
        <div style={{ width: '28px', height: '28px', background: 'linear-gradient(135deg,#10b981,#059669)', borderRadius: '7px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <Sparkles size={14} color="white" />
        </div>
        <span style={{ color: 'white', fontWeight: 950, fontSize: '0.9rem', letterSpacing: '-0.03em' }}>Espeezy</span>
      </Link>

      <div style={{ width: '100%', maxWidth: '680px', marginTop: '2rem' }}>
        {/* Status banner */}
        <motion.div
          initial={{ opacity: 0, y: -12 }}
          animate={{ opacity: 1, y: 0 }}
          style={{
            display: 'flex', alignItems: 'center', gap: '0.75rem',
            padding: '0.875rem 1.25rem', borderRadius: '14px', marginBottom: '1.5rem',
            background: isValid ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)',
            border: `1px solid ${isValid ? 'rgba(16,185,129,0.25)' : 'rgba(239,68,68,0.25)'}`,
          }}
        >
          {isValid
            ? <ShieldCheck size={20} color="#10b981" />
            : <AlertTriangle size={20} color="#ef4444" />}
          <div>
            <p style={{ margin: 0, fontWeight: 800, fontSize: '0.9rem', color: isValid ? '#10b981' : '#ef4444' }}>
              {isValid ? 'Certificate Verified  -  Authentic' : 'Certificate Revoked'}
            </p>
            <p style={{ margin: 0, fontSize: '0.75rem', color: 'rgba(255,255,255,0.4)', marginTop: '1px' }}>
              {isValid
                ? `Issued by Espeezy · ID ${cert.id}`
                : 'This certificate is no longer valid'}
            </p>
          </div>
        </motion.div>

        {/* Certificate card */}
        <motion.div
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1, duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
          style={{
            background: 'rgba(255,255,255,0.025)',
            backdropFilter: 'blur(40px)',
            border: '1px solid rgba(255,255,255,0.08)',
            borderRadius: '32px',
            overflow: 'hidden',
            boxShadow: '0 32px 80px rgba(0,0,0,0.6)',
          }}
        >
          {/* Header strip */}
          <div style={{ background: 'linear-gradient(135deg, rgba(16,185,129,0.15) 0%, rgba(16,185,129,0.04) 100%)', padding: '2.5rem 2.5rem 2rem', textAlign: 'center', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
            {avatarUrl
              ? <Image src={avatarUrl} alt={displayName} width={72} height={72} style={{ borderRadius: '50%', objectFit: 'cover', border: '3px solid rgba(16,185,129,0.4)', marginBottom: '1rem' }} />
              : (
                <div style={{ width: '72px', height: '72px', background: 'rgba(16,185,129,0.15)', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem', border: '3px solid rgba(16,185,129,0.3)', fontSize: '28px' }}>
                  🎓
                </div>
              )}
            <p style={{ margin: '0 0 0.25rem', fontSize: '0.75rem', fontWeight: 800, color: 'rgba(16,185,129,0.8)', textTransform: 'uppercase', letterSpacing: '0.14em' }}>Certificate of Completion</p>
            <h1 style={{ margin: '0 0 0.5rem', fontSize: '1.8rem', fontWeight: 950, color: 'white', letterSpacing: '-0.04em' }}>{displayName}</h1>
            <h2 style={{ margin: 0, fontSize: '1.05rem', fontWeight: 700, color: '#10b981', letterSpacing: '-0.02em' }}>{cert.programName}</h2>
          </div>

          {/* Details */}
          <div style={{ padding: '1.75rem 2.5rem' }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1.5rem' }}>
              <div>
                <p style={{ margin: '0 0 0.2rem', fontSize: '0.68rem', fontWeight: 800, color: 'rgba(255,255,255,0.3)', textTransform: 'uppercase', letterSpacing: '0.12em' }}>Issue Date</p>
                <p style={{ margin: 0, fontSize: '0.9rem', fontWeight: 700, color: 'white' }}>{issueDate}</p>
              </div>
              {cert.graduationYear && (
                <div>
                  <p style={{ margin: '0 0 0.2rem', fontSize: '0.68rem', fontWeight: 800, color: 'rgba(255,255,255,0.3)', textTransform: 'uppercase', letterSpacing: '0.12em' }}>Graduation Year</p>
                  <p style={{ margin: 0, fontSize: '0.9rem', fontWeight: 700, color: 'white' }}>{cert.graduationYear}</p>
                </div>
              )}
              {cert.gpa && (
                <div>
                  <p style={{ margin: '0 0 0.2rem', fontSize: '0.68rem', fontWeight: 800, color: 'rgba(255,255,255,0.3)', textTransform: 'uppercase', letterSpacing: '0.12em' }}>GPA</p>
                  <p style={{ margin: 0, fontSize: '0.9rem', fontWeight: 700, color: 'white' }}>{cert.gpa.toFixed(2)}</p>
                </div>
              )}
            </div>

            {cert.achievements.length > 0 && (
              <div style={{ marginBottom: '1.5rem' }}>
                <p style={{ margin: '0 0 0.75rem', fontSize: '0.68rem', fontWeight: 800, color: 'rgba(255,255,255,0.3)', textTransform: 'uppercase', letterSpacing: '0.12em' }}>Achievements</p>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                  {cert.achievements.map((a, i) => (
                    <span key={i} style={{ padding: '4px 12px', background: 'rgba(16,185,129,0.1)', border: '1px solid rgba(16,185,129,0.2)', borderRadius: '100px', fontSize: '0.75rem', fontWeight: 700, color: '#10b981' }}>
                      {a}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {/* Hash */}
            {cert.blockchainHash && (
              <div style={{ background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '12px', padding: '0.875rem 1rem', marginBottom: '1.5rem' }}>
                <p style={{ margin: '0 0 0.3rem', fontSize: '0.68rem', fontWeight: 800, color: 'rgba(255,255,255,0.3)', textTransform: 'uppercase', letterSpacing: '0.12em' }}>Integrity Hash (SHA-256)</p>
                <code style={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.4)', wordBreak: 'break-all' }}>{cert.blockchainHash}</code>
              </div>
            )}

            {/* Actions */}
            {isValid && (
              <a
                href={downloadUrl}
                download
                style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.6rem',
                  background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)',
                  color: '#0a0a0a', textDecoration: 'none', padding: '1rem',
                  borderRadius: '14px', fontWeight: 950, fontSize: '0.9rem',
                  boxShadow: '0 8px 24px rgba(16,185,129,0.3)',
                }}
              >
                <Download size={18} /> Download PDF Certificate
              </a>
            )}
          </div>
        </motion.div>

        {/* Footer note */}
        <p style={{ textAlign: 'center', marginTop: '1.5rem', fontSize: '0.75rem', color: 'rgba(255,255,255,0.2)' }}>
          This certificate was issued by <a href="https://espeezy.com" style={{ color: 'rgba(16,185,129,0.6)', textDecoration: 'none' }}>espeezy.com</a> and is tamper-evident.
        </p>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { 
  Sparkles, 
  Gamepad2, 
  Users, 
  BrainCircuit, 
  ShieldCheck, 
  Terminal, 
  Zap,
  CheckCircle2,
  Play,
  Loader2,
  Dna,
  Cpu,
  RefreshCw
} from 'lucide-react'
import { useProfile } from '@/context/ProfileContext'
import { Profile } from '@/types/database'
import { usePresence } from '@/components/PresenceProvider'
import { useNotifications } from '@/components/NotificationProvider'
import { useSmartLoading } from '@/components/GlobalLoadingProvider'
import {
  createGameSession,
  createNotification,
  fetchProfilesByIds,
  fetchUserGameStats,
  upsertUserGameStats,
} from '@/services/dashboard'

import { motion, AnimatePresence } from 'framer-motion'

const TOPICS = [
  { 
    id: 'cyber_ethics', 
    name: 'Cyber Ethics & Law', 
    icon: ShieldCheck, 
    color: 'var(--error)',
    description: 'Master the legal landscape of the digital academic frontier.'
  },
  { 
    id: 'logic_puzzles', 
    name: 'Algorithmic Riddles', 
    icon: BrainCircuit, 
    color: 'var(--brand)',
    description: 'Test your raw logic with complex computing patterns.'
  },
  { 
    id: 'pop_culture', 
    name: 'Digital History', 
    icon: Gamepad2, 
    color: 'var(--success)',
    description: 'From Turing to Jobs: The history of the digital era.'
  },
  { 
    id: 'institutional', 
    name: 'Espeezy Protocols', 
    icon: Terminal, 
    color: 'var(--accent)',
    description: "Deep dive into the app's advanced governance."
  }
]

export default function ChillOutHub() {
  const router = useRouter()
  const { profile } = useProfile()
  const { onlineUsers } = usePresence()
  const { addToast } = useNotifications()
  const { withLoading } = useSmartLoading()

  const [step, setStep] = useState(1) // 1: Topic, 2: Config, 3: Preview, 4: Players
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null)
  
  // Config State
  const [difficulty, setDifficulty] = useState<'Easy' | 'Medium' | 'Hard'>('Medium')
  const [gameMode, setGameMode] = useState<'Speed Recall' | 'AI Evaluated'>('Speed Recall')
  const [roundCount, setRoundCount] = useState<number>(5)
  
  const [isGenerating, setIsGenerating] = useState(false)
  const [questions, setQuestions] = useState<{ question: string; type: string; difficulty_multiplier: number }[]>([])
  const [selectedPlayers, setSelectedPlayers] = useState<string[]>([])
  const [onlineProfiles, setOnlineProfiles] = useState<Profile[]>([])
  const [userStats, setUserStats] = useState<{ level: number; total_xp: number; wins: number; games_played: number; rank_title?: string } | null>(null)

  // 1. Fetch Stats & Profiles
  useEffect(() => {
    async function fetchData() {
      if (!profile?.id) return

      try {
        const stats = await fetchUserGameStats(profile.id)

        if (!stats) {
          const newStats = {
            user_id: profile.id,
            total_xp: 0,
            level: 1,
            wins: 0,
            games_played: 0,
            rank_title: 'Novice Scholar',
          }
          await upsertUserGameStats(profile.id, newStats)
          setUserStats({
            level: 1,
            total_xp: 0,
            wins: 0,
            games_played: 0,
            rank_title: 'Novice Scholar',
          })
        } else {
          setUserStats({
            level: 1, // You can adjust this if you have a level calculation
            total_xp: stats.total_points ?? 0,
            wins: stats.wins ?? 0,
            games_played: stats.total_games ?? 0,
            rank_title: 'Novice Scholar', // Or derive from stats if you have logic
          })
        }

        if (onlineUsers.size > 0) {
          const ids = Array.from(onlineUsers)
          const profilesData = await fetchProfilesByIds(ids.slice(0, 10))
          setOnlineProfiles(profilesData.filter((p) => p.id !== profile?.id))
        }
      } catch (err: unknown) {
        console.error('Fetch data error:', err instanceof Error ? err.message : 'unknown error')
      }
    }
    fetchData()
  }, [onlineUsers, profile?.id])

  // 2. AI Synthesis
  const handleTopicSelect = (topic: typeof TOPICS[0]) => {
    setSelectedTopic(topic)
    setStep(2)
  }

  const handleInitializeQuestions = async () => {
    setIsGenerating(true)
    try {
      const res = await fetch('/api/ai/quiz', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          topic: selectedTopic?.name,
          difficulty,
          mode: gameMode,
          count: roundCount
        })
      })
      const data = await res.json()
      if (data.questions) {
        setQuestions(data.questions)
        setStep(3)
      } else {
        throw new Error(data.error || 'Synthesis error')
      }
    } catch (err: unknown) {
      addToast('Sync Failure', (err instanceof Error ? err.message : 'Unknown error'), 'error')
    } finally {
      setIsGenerating(false)
    }
  }

  const togglePlayer = (id: string) => {
    setSelectedPlayers(prev => 
      prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]
    )
  }

  const handleStartGame = async () => {
    if (selectedPlayers.length === 0) {
      addToast('No Players', 'You must invite at least one online peer.', 'warning')
      return
    }

    const roomId = `skirmish_${Date.now()}`
    
    await withLoading(async () => {
      await createGameSession({
        room_id: roomId,
        creator_id: profile?.id,
        topic_id: selectedTopic?.id,
        difficulty,
        mode: gameMode,
        created_at: new Date().toISOString()
      })

      for (const playerId of selectedPlayers) {
        await createNotification({
          user_id: playerId,
          type: 'skirmish_invite',
          title: 'SKIRMISH DETECTED',
          message: `${profile?.full_name || 'A Peer'} challenged you to ${difficulty} ${selectedTopic?.name}.`,
          metadata: { room_id: roomId, topic_id: selectedTopic?.id, mode: gameMode, questions },
        })
      }
      
      // 3. SECURE HAND-OFF: Save questions for the room to pick up
      if (typeof window !== 'undefined') {
        sessionStorage.setItem(`skirmish_setup_${roomId}`, JSON.stringify({ questions, config: { difficulty, mode: gameMode } }))
      }
      
      router.push(`/chillout/room/${roomId}?id=${roomId}`)
    }, 'Initializing Competitive Flux...')
  }

  return (
    <div className="page-fade" style={{ display: 'flex', flexDirection: 'column', gap: '2rem', paddingBottom: '4rem' }}>
      
      {/* ── STATS HUD ─────────────────────────────────────────── */}
      <AnimatePresence>
        <motion.div 
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'var(--surface)', padding: '1.25rem 2rem', borderRadius: '24px', border: '1px solid var(--border)', boxShadow: 'var(--shadow-sm)' }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
             <div style={{ position: 'relative' }}>
                <div style={{ width: '60px', height: '60px', borderRadius: '18px', background: 'linear-gradient(135deg, var(--brand), #8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 950, fontSize: '1.5rem', boxShadow: '0 8px 16px rgba(var(--brand-rgb), 0.3)' }}>
                  {userStats?.level || 1}
                </div>
                <div style={{ position: 'absolute', bottom: -5, left: '50%', transform: 'translateX(-50%)', background: 'var(--brand)', color: 'white', padding: '2px 8px', borderRadius: '6px', fontSize: '0.6rem', fontWeight: 900, whiteSpace: 'nowrap' }}>LVL</div>
             </div>
             <div>
                <h4 style={{ margin: 0, fontSize: '1.1rem', fontWeight: 950, letterSpacing: '-0.02em' }}>{userStats?.rank_title || 'Novice Scholar'}</h4>
                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginTop: '0.4rem' }}>
                   <div style={{ width: '200px', height: '6px', background: 'var(--bg-main)', borderRadius: '10px', overflow: 'hidden' }}>
                      <motion.div 
                        initial={{ width: 0 }} 
                        animate={{ width: `${(userStats?.total_xp ?? 0) % 100}%` }}
                        style={{ height: '100%', background: 'var(--brand)' }} 
                      />
                   </div>
                   <span style={{ fontSize: '0.7rem', fontWeight: 800, color: 'var(--text-sub)' }}>{userStats?.total_xp || 0} XP Total</span>
                </div>
             </div>
          </div>
          <div style={{ display: 'flex', gap: '2rem' }}>
             <div style={{ textAlign: 'center' }}>
                <div style={{ fontSize: '1.25rem', fontWeight: 950 }}>{userStats?.wins || 0}</div>
                <div style={{ fontSize: '0.65rem', fontWeight: 700, color: 'var(--text-sub)', textTransform: 'uppercase' }}>Wins</div>
             </div>
             <div style={{ textAlign: 'center' }}>
                <div style={{ fontSize: '1.25rem', fontWeight: 950 }}>{userStats?.games_played || 0}</div>
                <div style={{ fontSize: '0.65rem', fontWeight: 700, color: 'var(--text-sub)', textTransform: 'uppercase' }}>Battles</div>
             </div>
          </div>
        </motion.div>
      </AnimatePresence>

      {/* ── HEADER ────────────────────────────────────────────── */}
      <header>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '0.5rem' }}>
          <div style={{ padding: '0.75rem', borderRadius: '14px', background: 'rgba(var(--brand-rgb), 0.1)', color: 'var(--brand)' }}>
             <Sparkles size={32} />
          </div>
          <div>
            <h1 style={{ fontSize: '2.25rem', fontWeight: 950, letterSpacing: '-0.04em', margin: 0 }}>
              Chill Out <span style={{ color: 'var(--brand)' }}>Zone</span>
            </h1>
            <p style={{ color: 'var(--text-sub)', fontWeight: 600, fontSize: '0.9rem' }}>Decompress and dominate with real-time academic skirmishes.</p>
          </div>
        </div>
      </header>

      {/* ── CONTENT RENDERING ────────────────────────────────────── */}
      {isGenerating ? (
        <div style={{ height: '400px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center' }}>
          <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 4, ease: "linear" }}>
             <Dna size={80} style={{ color: 'var(--brand)' }} />
          </motion.div>
          <h2 style={{ fontSize: '1.5rem', fontWeight: 950, letterSpacing: '-0.03em', marginBottom: '0.5rem', marginTop: '2rem' }}>Synthesizing Shards</h2>
          <p style={{ color: 'var(--text-sub)', fontWeight: 700, fontSize: '0.85rem' }}>Constructing {difficulty} logic for {selectedTopic?.name}...</p>
        </div>
      ) : (
        <AnimatePresence mode="wait">
          {step === 1 && (
            <motion.div 
              key="step1" 
              initial={{ opacity: 0, x: 20 }} 
              animate={{ opacity: 1, x: 0 }} 
              exit={{ opacity: 0, x: -20 }}
              style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '1.5rem' }}
            >
              {TOPICS.map(topic => (
                <button 
                  key={topic.id}
                  onClick={() => handleTopicSelect(topic)}
                  className="glass hover-card"
                  aria-label={`Select topic: ${topic.name}. ${topic.description}`}
                  style={{ padding: '2rem', borderRadius: '24px', border: '1px solid var(--border)', textAlign: 'left', background: 'var(--surface)', cursor: 'pointer', display: 'flex', flexDirection: 'column', gap: '1rem' }}
                >
                  <div style={{ width: '56px', height: '56px', borderRadius: '16px', background: `rgba(${topic.id === 'cyber_ethics' ? '239, 68, 68' : 'var(--brand-rgb)'}, 0.1)`, color: topic.color, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                     <topic.icon size={28} aria-hidden="true" />
                  </div>
                  <div>
                    <h3 style={{ margin: 0, fontSize: '1.25rem', fontWeight: 900, letterSpacing: '-0.02em', color: 'var(--text-main)' }}>{topic.name}</h3>
                    <p style={{ margin: '0.5rem 0 0', fontSize: '0.85rem', color: 'var(--text-sub)', lineHeight: 1.5, fontWeight: 500 }}>{topic.description}</p>
                  </div>
                </button>
              ))}
            </motion.div>
          )}

          {step === 2 && (
            <motion.div 
              key="step2" 
              initial={{ opacity: 0, x: 20 }} 
              animate={{ opacity: 1, x: 0 }} 
              exit={{ opacity: 0, x: -20 }}
              style={{ background: 'var(--surface)', borderRadius: '32px', border: '1px solid var(--border)', padding: '2.5rem', maxWidth: '800px', margin: '0 auto', width: '100%' }}
            >
               <h2 style={{ fontSize: '1.75rem', fontWeight: 950, marginBottom: '2rem' }}>Configure Skirmish</h2>
               
               <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
                  {/* Difficulty */}
                  <div>
                    <label style={{ fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', display: 'block', marginBottom: '1rem' }}>Challenge Level</label>
                     <div style={{ display: 'flex', gap: '0.75rem' }}>
                        {['Easy', 'Medium', 'Hard'].map(d => (
                          <button 
                            key={d} 
                            onClick={() => setDifficulty(d as 'Easy' | 'Medium' | 'Hard')} 
                            aria-pressed={difficulty === d}
                            style={{ flex: 1, padding: '1rem', borderRadius: '14px', border: '2px solid', borderColor: difficulty === d ? 'var(--brand)' : 'var(--border)', background: difficulty === d ? 'rgba(var(--brand-rgb), 0.05)' : 'var(--bg-sub)', color: difficulty === d ? 'var(--text-main)' : 'var(--text-sub)', fontWeight: 900, cursor: 'pointer', transition: '0.2s' }}
                          >
                            {d}
                          </button>
                        ))}
                     </div>
                  </div>

                  {/* Mode */}
                  <div>
                    <label style={{ fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', display: 'block', marginBottom: '1rem' }}>Grading Protocol</label>
                     <div style={{ display: 'flex', gap: '0.75rem' }}>
                        {['Speed Recall', 'AI Evaluated'].map(m => (
                          <button 
                            key={m} 
                            onClick={() => setGameMode(m as 'Speed Recall' | 'AI Evaluated')} 
                            aria-pressed={gameMode === m}
                            style={{ flex: 1, padding: '1rem', borderRadius: '14px', border: '2px solid', borderColor: gameMode === m ? 'var(--brand)' : 'var(--border)', background: gameMode === m ? 'rgba(var(--brand-rgb), 0.05)' : 'var(--bg-sub)', color: gameMode === m ? 'var(--text-main)' : 'var(--text-sub)', fontWeight: 900, cursor: 'pointer', transition: '0.2s', textAlign: 'left' }}
                          >
                             <div style={{ fontWeight: 950 }}>{m}</div>
                             <div style={{ fontSize: '0.65rem', opacity: 0.6, marginTop: '2px' }}>{m === 'Speed Recall' ? 'Reveal & choices' : 'Text input + AI Grade'}</div>
                          </button>
                        ))}
                     </div>
                  </div>

                  {/* Rounds */}
                  <div>
                    <label style={{ fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', display: 'block', marginBottom: '1rem' }}>Skirmish Depth</label>
                     <div style={{ display: 'flex', gap: '0.75rem' }}>
                        {[3, 5, 10].map(r => (
                          <button 
                            key={r} 
                            onClick={() => setRoundCount(r)} 
                            aria-pressed={roundCount === r}
                            style={{ flex: 1, padding: '1rem', borderRadius: '14px', border: '2px solid', borderColor: roundCount === r ? 'var(--brand)' : 'var(--border)', background: roundCount === r ? 'rgba(var(--brand-rgb), 0.05)' : 'var(--bg-sub)', color: roundCount === r ? 'var(--text-main)' : 'var(--text-sub)', fontWeight: 900, cursor: 'pointer', transition: '0.2s' }}
                          >
                            {r} Rounds
                          </button>
                        ))}
                     </div>
                  </div>
               </div>

               <div style={{ display: 'flex', gap: '1rem', marginTop: '3rem' }}>
                  <button onClick={() => setStep(1)} className="btn btn-secondary" style={{ flex: 1 }}>Back</button>
                  <button onClick={handleInitializeQuestions} className="btn btn-primary" style={{ flex: 2, fontWeight: 950 }}>INITIALIZE AI ENGINE</button>
               </div>
            </motion.div>
          )}

          {step === 3 && (
            <motion.div 
              key="step3" 
              initial={{ opacity: 0, x: 20 }} 
              animate={{ opacity: 1, x: 0 }} 
              exit={{ opacity: 0, x: -20 }}
              style={{ background: 'var(--surface)', borderRadius: '24px', border: '1px solid var(--border)', padding: '2rem' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
                 <h2 style={{ fontSize: '1.5rem', fontWeight: 950, margin: 0 }}>Battle Log Configuration</h2>
                 <div style={{ display: 'flex', gap: '1rem' }}>
                    <button onClick={() => setStep(2)} className="btn btn-secondary" style={{ fontSize: '0.8rem' }}>Re-Sync AI</button>
                    <button onClick={() => setStep(4)} className="btn btn-primary" style={{ fontSize: '0.8rem', fontWeight: 950 }}>PROCEED TO INVITES</button>
                 </div>
              </div>
              
              <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                {questions.map((q, i) => (
                  <div key={i} style={{ padding: '1.25rem', borderRadius: '16px', border: '1px solid var(--border)', background: 'var(--bg-sub)', display: 'flex', gap: '1rem' }}>
                    <div style={{ width: '24px', height: '24px', borderRadius: '50%', background: 'var(--brand)', color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.75rem', fontWeight: 900, flexShrink: 0 }}>{i + 1}</div>
                    <div style={{ flex: 1 }}>
                      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.4rem' }}>
                         <span style={{ fontSize: '0.6rem', padding: '2px 6px', borderRadius: '4px', background: 'rgba(var(--brand-rgb), 0.1)', color: 'var(--brand)', fontWeight: 900, textTransform: 'uppercase' }}>{q.type}</span>
                         <span style={{ fontSize: '0.6rem', padding: '2px 6px', borderRadius: '4px', background: 'var(--bg-main)', color: 'var(--text-sub)', fontWeight: 900 }}>D-IDX: {q.difficulty_multiplier || 1}</span>
                      </div>
                      <div style={{ fontWeight: 800, fontSize: '0.95rem', color: 'var(--text-main)' }}>{q.question}</div>
                    </div>
                  </div>
                ))}
              </div>
            </motion.div>
          )}

          {step === 4 && (
            <motion.div 
              key="step4" 
              initial={{ opacity: 0, x: 20 }} 
              animate={{ opacity: 1, x: 0 }} 
              style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}
            >
              <div style={{ background: 'var(--surface)', borderRadius: '24px', border: '1px solid var(--border)', padding: '2.5rem' }}>
                <h2 style={{ fontSize: '1.5rem', fontWeight: 950, marginBottom: '0.5rem' }}>Deploy Challenge Signals</h2>
                <p style={{ color: 'var(--text-sub)', fontSize: '0.9rem', marginBottom: '2rem' }}>Only online scholars can receive real-time game signals.</p>
                
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '1.25rem' }}>
                  {onlineProfiles.length === 0 ? (
                    <div style={{ gridColumn: '1/-1', textAlign: 'center', padding: '4rem', color: 'var(--text-sub)' }}>
                      <Users size={48} style={{ opacity: 0.1, marginBottom: '1rem' }} />
                      <p style={{ fontWeight: 700 }}>No other scholars are currently online.</p>
                    </div>
                  ) : (
                    onlineProfiles.map(p => (
                      <button 
                        key={p.id}
                        onClick={() => togglePlayer(p.id)}
                        className="glass"
                        style={{ 
                          padding: '1.25rem', 
                          borderRadius: '18px', 
                          border: '2px solid', 
                          background: selectedPlayers.includes(p.id) ? 'rgba(var(--brand-rgb), 0.05)' : 'var(--surface)',
                          borderColor: selectedPlayers.includes(p.id) ? 'var(--brand)' : 'var(--border)',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '1rem',
                          cursor: 'pointer',
                          transition: 'all 0.2s',
                          textAlign: 'left'
                        }}
                      >
                         <div style={{ width: '36px', height: '36px', borderRadius: '12px', overflow: 'hidden', background: 'var(--bg-main)', border: '1px solid var(--border)' }}>
                          {p.avatar_url ? <img src={p.avatar_url} alt={p.full_name || 'Peer'} style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }} aria-label={p.full_name || 'Peer'}><Users size={16} /></div>}
                        </div>
                        <span style={{ fontSize: '0.9rem', fontWeight: 900, flex: 1, color: 'var(--text-main)' }}>{p.full_name}</span>
                        {selectedPlayers.includes(p.id) && <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }}><CheckCircle2 size={18} color="var(--brand)" aria-label="Selected" /></motion.div>}
                      </button>
                    ))
                  )}
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'center', gap: '1rem' }}>
                 <button onClick={() => setStep(3)} className="btn btn-secondary" style={{ padding: '1rem 2.5rem' }}>Back</button>
                 <button 
                   onClick={handleStartGame} 
                   className="btn btn-primary" 
                   style={{ padding: '1rem 4rem', borderRadius: '20px', display: 'flex', alignItems: 'center', gap: '1rem', fontWeight: 950, fontSize: '1.1rem' }}
                   disabled={selectedPlayers.length === 0}
                 >
                   <Play size={22} fill="currentColor" />
                   INITIATE SKIRMISH
                 </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      )}

      <style jsx>{`
        .hover-card:hover {
          transform: translateY(-8px);
          border-color: var(--brand) !important;
          box-shadow: 0 20px 40px rgba(var(--brand-rgb), 0.2);
        }
        .page-fade { animation: fadeIn 0.4s ease-out; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-pulse { animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .5; } }
        
        .neural-bg {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: radial-gradient(circle at 50% 50%, rgba(var(--brand-rgb), 0.03) 0%, transparent 70%);
          z-index: -1;
          pointer-events: none;
        }

        .neural-bg::after {
          content: '';
          position: absolute;
          inset: 0;
          background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%239C92AC' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
        }
      `}</style>
      <div className="neural-bg" />
    </div>
  )
}

'use client'

import React, { useState, useEffect, useCallback } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { usePresence, useSyncedList, useSyncedObject } from '@/lib/realtime-provider'
import { 
  Trophy, 
  Crown, 
  Zap,
  Loader2
} from 'lucide-react'
import { useProfile } from '@/context/ProfileContext'
import { useNotifications } from '@/components/NotificationProvider'
import confetti from 'canvas-confetti'
import { motion, AnimatePresence } from 'framer-motion'
import { jsPDF } from 'jspdf'
import { updateUserGameStats } from '@/app/actions'
import { SkirmishTimer } from '@/components/skirmish/SkirmishTimer'

export default function QuizRoomPage() {
  const params = useParams()
  const roomId = params?.id as string
  
  if (!roomId) return <div style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Loader2 className="animate-spin" /></div>

  return (
    <QuizGameContainer roomId={roomId} />
  )
}

function QuizGameContainer({ roomId }: { roomId: string }) {
  const { profile } = useProfile()
  const { addToast } = useNotifications()
  const router = useRouter()
  
  const { others, me, updateMyState } = usePresence(roomId);
  
  interface SkirmishState {
    quizStatus: 'setup' | 'playing' | 'results'
    quizQuestions: any[]
    currentQuestionIndex: number
    quizScores: { userId: string; userName: string; points: number }[]
    roundStartTime: number
    timerDuration: number
    config: { difficulty: string; mode: string }
    activeTurnUserId?: string | null
  }
  
  const [storage, updateStorage] = useSyncedObject<SkirmishState>(`rooms/${roomId}/state`, {
    quizStatus: 'setup',
    quizQuestions: [],
    currentQuestionIndex: 0,
    quizScores: [],
    roundStartTime: 0,
    timerDuration: 20,
    config: { difficulty: 'Medium', mode: 'Speed Recall' }
  });
  
  const quizStatus = storage?.quizStatus || 'setup'
  const questions = storage?.quizQuestions || []
  const currentIdx = storage?.currentQuestionIndex ?? 0
  const scores = storage?.quizScores || []
  const activeTurnId = storage?.activeTurnUserId
  const roundStartTime = storage?.roundStartTime
  const timerDuration = storage?.timerDuration ?? 20
  const config = storage?.config || { difficulty: 'Medium', mode: 'Speed Recall' }
  
  const [showIntro, setShowIntro] = useState(true)
  const [selectedOption, setSelectedOption] = useState<number | null>(null)
  const [hasAnswered, setHasAnswered] = useState(false)
  const [textAnswer, setTextAnswer] = useState('')
  const [isRevealed, setIsRevealed] = useState(false)
  const [isGrading, setIsGrading] = useState(false)
  const [aiCritique, setAiCritique] = useState('')
  const [hasSetupData] = useState(() => {
    if (typeof window === 'undefined') return false
    return !!sessionStorage.getItem(`skirmish_setup_${roomId}`)
  })

   
  const handleStartSkirmish = useCallback(async () => {
    const setupRaw = sessionStorage.getItem(`skirmish_setup_${roomId}`)
    if (!setupRaw) return

    try {
        const { questions: newQs, config: setupConfig } = JSON.parse(setupRaw)
        
        await updateStorage({
          quizQuestions: newQs,
          quizStatus: 'playing',
          currentQuestionIndex: 0,
          roundStartTime: Date.now(),
          activeTurnUserId: profile?.id ?? null,
          timerDuration: (newQs[0]?.difficulty_multiplier || 2) * 10,
          config: {
            difficulty: setupConfig.difficulty,
            mode: setupConfig.mode
          }
        })

        addToast('Skirmish Injected', 'AI shards synchronized. Battle started!', 'success')
        sessionStorage.removeItem(`skirmish_setup_${roomId}`)
    } catch (err) {
        addToast('Critical Failure', 'Mental sync aborted.', 'error')
    }
  }, [roomId, profile, updateStorage, addToast])

  // ── RESET UI ON QUESTION CHANGE ──────────────────────────────────
  useEffect(() => {
    queueMicrotask(() => {
      setSelectedOption(null)
      setHasAnswered(false)
      setTextAnswer('')
      setIsRevealed(false)
      setAiCritique('')
    })
  }, [currentIdx, timerDuration])

  const handleFinalizeStats = useCallback(async () => {
    if (!profile?.id || !scores) return
    const myScore = scores.find((s) => s.userId === profile.id)?.points || 0
    const isWinner = scores.length > 1 && myScore >= Math.max(...scores.map((s) => s.points))

    await updateUserGameStats(profile.id, Math.floor(myScore / 4), isWinner)
  }, [profile, scores])


  const submitActionResult = useCallback(async (isCorrect: boolean, bonusXp = 0) => {
    const userId = profile?.id
    if (!userId || !storage) return

    // Update Scores
    const currentScores = [...(storage.quizScores || [])]
    let found = false
    const pointsToAdd = isCorrect ? (100 + bonusXp) : -50

    for (let i = 0; i < currentScores.length; i++) {
        const item = currentScores[i]
        if (item && item.userId === userId) {
            currentScores[i] = { ...item, points: Math.max(0, item.points + pointsToAdd) }
            found = true
            break
        }
    }
    if (!found) {
        currentScores.push({ userId, userName: profile?.full_name || 'Anonymous', points: Math.max(0, pointsToAdd) })
    }

    // Next Round Setup
    const currentQList = storage.quizQuestions || []
    const nextIdx = (storage.currentQuestionIndex || 0) + 1
    
    if (nextIdx < currentQList.length) {
      const nextQ = currentQList[nextIdx]
      const nextDuration = (nextQ?.difficulty_multiplier || 2) * 10
      const players = [userId, ...others.map((o) => o.userId)].filter(Boolean)
      
      await updateStorage({
        quizScores: currentScores,
        currentQuestionIndex: nextIdx,
        roundStartTime: Date.now(),
        timerDuration: nextDuration,
        activeTurnUserId: players[nextIdx % players.length]
      })
    } else {
      await updateStorage({
        quizScores: currentScores,
        quizStatus: 'results'
      })
      handleFinalizeStats()
    }
  }, [profile, others, storage, updateStorage, handleFinalizeStats])

  const handleSkipRound = useCallback(() => {
    submitActionResult(false)
    addToast('Time Out!', 'The round was skipped due to temporal flux.', 'warning')
  }, [submitActionResult, addToast])

  const handleResetSkirmish = useCallback(async () => {
    await updateStorage({
      quizStatus: 'setup',
      currentQuestionIndex: 0,
      quizQuestions: [],
      activeTurnUserId: null
    })
    addToast('Archives Reset', 'Neural buffer cleared. Ready for a new iteration.', 'info')
  }, [updateStorage, addToast])

  // ── COLLECTIVE CELEBRATION ────────────────────────────────────
   
  useEffect(() => {
    if (quizStatus === 'results') {
        confetti({ 
          particleCount: 150, 
          spread: 80, 
          origin: { y: 0.6 },
          colors: ['#0ea5e9', '#38bdf8', '#fbbf24']
        })
        addToast('Ascension Validated', 'The collective knowledge has been successfully assimilated.', 'success')
    }
  }, [quizStatus])

  // ── INTERACTION HANDLERS ───────────────────────────────────────
  const currentQ = questions && questions.length > currentIdx ? questions[currentIdx] : null
  const isMyTurn = activeTurnId === profile?.id

  const handleMCSelect = (idx: number) => {
    if (!isMyTurn || hasAnswered || !currentQ) return
    setSelectedOption(idx)
    setHasAnswered(true)
    
    const correct = idx === currentQ.correctAnswer
    if (correct) {
      confetti({ particleCount: 40, scalar: 0.7 })
      addToast('Correct!', 'Neural pathways aligned.', 'success')
    } else {
      addToast('Incorrect', 'Divergent thought detected.', 'error')
    }
    
    // Performance: Reduced delay for snappier feel
    setTimeout(() => submitActionResult(correct), 600)
  }

  const handleAIEvaluation = async () => {
    if (!textAnswer.trim() || !currentQ) return
    setIsGrading(true)
    try {
        const res = await fetch('/api/ai/grade', {
           method: 'POST',
           headers: { 'Content-Type': 'application/json' },
           body: JSON.stringify({
              question: currentQ.question,
              correctAnswer: currentQ.correctAnswer,
              userResponse: textAnswer
           })
        })
        const data = await res.json()
        setAiCritique(data.critique)
        setHasAnswered(true)
        
        if (data.isCorrect) {
          confetti({ particleCount: 50 })
          addToast('Synthesis Validated', 'AI score: ' + data.score, 'success')
        }
        
        // Performance: Reduced delay
        setTimeout(() => submitActionResult(data.isCorrect, data.score), 1000)
    } catch (err) {
        addToast('Evaluation Failed', 'Judge is offline.', 'error')
    } finally {
        setIsGrading(false)
    }
  }

  const downloadTrophy = () => {
    if (!scores || scores.length === 0) return
    const doc = new jsPDF()
    const sortedScores = [...scores].sort((a,b) => b.points - a.points)
    const winner = sortedScores[0]
    
    doc.setFillColor(15, 23, 42)
    doc.rect(0, 0, 210, 297, 'F')
    
    doc.setTextColor(59, 130, 246)
    doc.setFontSize(35)
    doc.text('SKIRMISH RECEIPT', 105, 50, { align: 'center' })
    
    doc.setTextColor(255, 255, 255)
    doc.setFontSize(20)
    doc.text(`${config?.difficulty || 'Standard'} ${config?.mode || 'Battle'}`.toUpperCase(), 105, 75, { align: 'center' })
    
    doc.setTextColor(251, 191, 36)
    doc.setFontSize(28)
    doc.text(winner?.userName?.toUpperCase() || 'PEER', 105, 120, { align: 'center' })
    
    doc.setTextColor(255, 255, 255)
    doc.setFontSize(14)
    doc.text(`VICTORY SCORE: ${winner?.points || 0}`, 105, 140, { align: 'center' })
    doc.text(`CHALLENGES CLEARED: ${questions?.length || 0}`, 105, 150, { align: 'center' })
    
    doc.save(`skirmish_receipt_${winner?.userName || 'winner'}.pdf`)
  }

   
  useEffect(() => {
    const timer = setTimeout(() => setShowIntro(false), 2500)
    return () => clearTimeout(timer)
  }, [])

  if (quizStatus === null) {
    return (
      <div style={{ height: 'calc(var(--vh-dynamic) - 6rem)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '1rem', color: 'var(--text-sub)' }}>
         <Loader2 className="animate-spin" size={32} />
         <div style={{ fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.2em', fontSize: '0.8rem' }}>Calibrating Storage...</div>
      </div>
    )
  }

  if (showIntro) {
    return (
      <div style={{ height: 'var(--vh-dynamic)', background: 'var(--bg-main)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center' }}>
         <motion.div initial={{ scale: 0.5, rotate: -45 }} animate={{ scale: 1, rotate: 0 }} transition={{ type: 'spring' }}>
            <Zap size={120} className="text-brand" fill="var(--brand)" style={{ filter: 'drop-shadow(0 0 30px rgba(var(--brand-rgb), 0.5))' }} />
         </motion.div>
         <h1 style={{ fontSize: '3.5rem', fontWeight: 950, letterSpacing: '-0.06em', marginTop: '2rem' }}>SKIRMISH <span style={{ color: 'var(--brand)' }}>ACTIVE</span></h1>
         <p style={{ color: 'var(--text-sub)', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.4em' }}>Assembling Virtual Shards...</p>
      </div>
    )
  }

  return (
    <div className="page-fade" style={{ display: 'grid', gridTemplateColumns: '1fr 320px', gap: '2rem', height: 'calc(var(--vh-dynamic) - 6rem)', overflow: 'hidden' }}>
      
      {/* ── MAIN SKYRMISH AREA ────────────────────────────────────────── */}
      <div style={{ background: 'var(--surface)', borderRadius: '32px', border: '1px solid var(--border)', display: 'flex', flexDirection: 'column', position: 'relative', overflow: 'hidden', boxShadow: 'var(--shadow-xl)' }}>
        
        {quizStatus === 'setup' && (
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '2rem' }}>
             <Crown size={80} className="text-brand" style={{ marginBottom: '2rem', opacity: 0.2 }} />
             <h2 style={{ fontSize: '2rem', fontWeight: 950, marginBottom: '1rem' }}>Initiating Protocol</h2>
             <p style={{ color: 'var(--text-sub)', marginBottom: '2.5rem', maxWidth: '450px', fontWeight: 600 }}>
                {hasSetupData 
                  ? "The Master Librarian awaits your signal. Deploy the academic shards whenever you feel adequately prepared." 
                  : "Synchronizing with the Central Archive. Waiting for the Host to initiate the knowledge extraction."}
             </p>
             
             {hasSetupData ? (
                <button 
                  onClick={handleStartSkirmish}
                  className="btn btn-primary"
                  style={{ padding: '1.25rem 3.5rem', borderRadius: '20px', fontWeight: 950, fontSize: '1.1rem', boxShadow: '0 10px 30px rgba(var(--brand-rgb), 0.3)' }}
                >
                  COMMENCE THE EXTRACTION
                </button>
             ) : (
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>
                   <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', color: 'var(--brand)', fontWeight: 900 }}>
                      <Loader2 className="animate-spin" size={24} /> 
                      <span className="animate-pulse">AWAITING HOST COMMAND...</span>
                   </div>
                   <div style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-sub)' }}>{others.length + 1} Scholars Connected</div>
                </div>
             )}
          </div>
        )}

        {quizStatus === 'playing' && currentQ && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ flex: 1, display: 'flex', flexDirection: 'column', padding: '3rem' }}>
             {/* Header */}
             <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '3rem' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                   <div style={{ width: '48px', height: '48px', borderRadius: '14px', background: 'rgba(var(--brand-rgb), 0.1)', color: 'var(--brand)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 950, fontSize: '1.25rem' }}>{currentIdx + 1}</div>
                   <div>
                      <div style={{ fontSize: '0.65rem', fontWeight: 950, textTransform: 'uppercase', color: 'var(--text-sub)', letterSpacing: '0.15em' }}>Round Progress</div>
                      <div style={{ fontWeight: 850 }}>{config?.mode || 'Battle'} <span style={{ color: 'var(--text-sub)' }}>({config?.difficulty || 'Standard'})</span></div>
                   </div>
                </div>
                
                {/* SMART TIMER (Isolated for performance) */}
                <SkirmishTimer 
                  roundStartTime={roundStartTime || 0} 
                  timerDuration={timerDuration || 20}
                  activeTurnId={activeTurnId ?? null}
                  currentProfileId={profile?.id ?? null}
                  onTimeOut={handleSkipRound}
                />
             </div>

             {/* Question Area */}
             <div style={{ textAlign: 'center', marginBottom: '3rem', minHeight: '120px' }}>
                <AnimatePresence mode="wait">
                   <motion.h2 
                     key={currentIdx}
                     initial={{ y: 20, opacity: 0 }}
                     animate={{ y: 0, opacity: 1 }}
                     style={{ fontSize: '2.25rem', fontWeight: 950, color: 'var(--text-main)', letterSpacing: '-0.04em', lineHeight: 1.1, marginBottom: '1.5rem' }}
                   >
                     {currentQ.question}
                   </motion.h2>
                </AnimatePresence>
                <div style={{ display: 'flex', justifyContent: 'center', gap: '0.75rem', alignItems: 'center' }}>
                   <motion.div 
                     animate={isMyTurn ? { scale: [1, 1.05, 1], boxShadow: ['0 0 0px var(--brand)', '0 0 20px var(--brand)', '0 0 0px var(--brand)'] } : {}}
                     transition={{ repeat: Infinity, duration: 1.5 }}
                     style={{ padding: '6px 16px', background: isMyTurn ? 'var(--brand)' : 'var(--bg-sub)', color: isMyTurn ? 'white' : 'var(--text-sub)', borderRadius: '10px', fontSize: '0.75rem', fontWeight: 950, textTransform: 'uppercase', letterSpacing: '0.05em' }}
                   >
                      {isMyTurn ? '⚡ IT IS YOUR TURN TO SYNTHESIZE' : `🔍 ${others.find(o => o.userId === activeTurnId)?.name || 'A Peer'} is currently being evaluated...`}
                   </motion.div>
                </div>
             </div>

             {/* Dynamic Mode Controller */}
             <div style={{ flex: 1 }}>
                {/* 1. Multiple Choice Mode */}
                {currentQ?.type === 'multiple_choice' && (
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                        {currentQ.options?.map((opt: string, i: number) => {
                            const isCorrect = hasAnswered && i === currentQ.correctAnswer
                            const isWrong = hasAnswered && selectedOption === i && i !== currentQ.correctAnswer
                            return (
                                <button 
                                  key={i}
                                  disabled={!isMyTurn || hasAnswered}
                                  onClick={() => handleMCSelect(i)}
                                  className="glass"
                                  style={{ 
                                    padding: '1.5rem', borderRadius: '20px', border: '2px solid',
                                    borderColor: isCorrect ? 'var(--success)' : isWrong ? 'var(--error)' : selectedOption === i ? 'var(--brand)' : 'var(--border)',
                                    background: isCorrect ? 'rgba(var(--success-rgb), 0.05)' : 'var(--surface)',
                                    textAlign: 'left', fontWeight: 800, cursor: isMyTurn ? 'pointer' : 'default', transition: '0.2s', width: '100%'
                                  }}
                                >
                                    {opt}
                                </button>
                            )
                        })}
                    </div>
                )}

                {/* 2. Speed Recall Mode */}
                {config?.mode === 'Speed Recall' && currentQ?.type === 'explanation' && (
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '2rem' }}>
                        <AnimatePresence>
                           {isRevealed ? (
                               <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ padding: '2rem', background: 'rgba(var(--brand-rgb), 0.03)', borderRadius: '24px', border: '1px dashed var(--brand)', width: '100%', textAlign: 'center' }}>
                                  <div style={{ fontSize: '0.7rem', fontWeight: 950, color: 'var(--brand)', marginBottom: '0.5rem', textTransform: 'uppercase' }}>Correct Answer</div>
                                  <div style={{ fontSize: '1.1rem', fontWeight: 800 }}>{currentQ?.correctAnswer}</div>
                               </motion.div>
                           ) : (
                               <button onClick={() => setIsRevealed(true)} className="btn btn-primary" style={{ padding: '1rem 3rem', borderRadius: '16px', fontWeight: 950 }}>REVEAL FLUX</button>
                           )}
                        </AnimatePresence>

                        {isRevealed && isMyTurn && !hasAnswered && (
                            <div style={{ display: 'flex', gap: '1rem' }}>
                                <button onClick={() => { setHasAnswered(true); submitActionResult(false); }} className="btn" style={{ background: 'var(--error)', color: 'white', padding: '1rem 2rem', borderRadius: '12px', fontWeight: 900 }}>MISSED IT</button>
                                <button onClick={() => { setHasAnswered(true); confetti(); submitActionResult(true); }} className="btn" style={{ background: 'var(--success)', color: 'white', padding: '1rem 2rem', borderRadius: '12px', fontWeight: 900 }}>GOT IT!</button>
                            </div>
                        )}
                    </div>
                )}

                {/* 3. AI Evaluated Mode */}
                {config?.mode === 'AI Evaluated' && currentQ?.type === 'explanation' && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                        <textarea 
                          value={textAnswer}
                          onChange={(e) => setTextAnswer(e.target.value)}
                          disabled={!isMyTurn || hasAnswered}
                          placeholder="Synthesize your explanation here..."
                          style={{ width: '100%', height: '140px', background: 'var(--bg-sub)', border: '2px solid var(--border)', borderRadius: '20px', padding: '1.5rem', color: 'var(--text-main)', fontSize: '1rem', outline: 'none', resize: 'none', transition: 'border-color 0.2s' }}
                        />
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                           <div style={{ color: 'var(--text-sub)', fontSize: '0.8rem', fontWeight: 600 }}>{textAnswer.length} characters used</div>
                           <button 
                             onClick={handleAIEvaluation}
                             disabled={!isMyTurn || hasAnswered || isGrading || !textAnswer.trim()}
                             className="btn btn-primary"
                             style={{ padding: '0.8rem 2.5rem', borderRadius: '14px', fontWeight: 950, display: 'flex', alignItems: 'center', gap: '0.75rem' }}
                           >
                              {isGrading ? <Loader2 className="animate-spin" size={18} /> : <Zap size={18} />}
                              DEPLOY FOR GRADING
                           </button>
                        </div>
                        {aiCritique && (
                            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} style={{ padding: '1rem 1.5rem', background: 'var(--bg-main)', borderLeft: '4px solid var(--brand)', borderRadius: '0 12px 12px 0' }}>
                               <span style={{ fontSize: '0.7rem', fontWeight: 900, color: 'var(--brand)', textTransform: 'uppercase' }}>Judge&apos;s Critique:</span>
                               <p style={{ margin: '4px 0 0', fontWeight: 700, fontStyle: 'italic' }}>&quot;{aiCritique}&quot;</p>
                            </motion.div>
                        )}
                    </div>
                )}
             </div>
          </motion.div>
        )}

        {quizStatus === 'results' && (
           <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '3rem' }}>
              <motion.div initial={{ scale: 0 }} animate={{ scale: 1, rotate: [0, 10, -10, 0] }} transition={{ duration: 0.5 }}>
                 <Trophy size={140} className="text-brand" fill="var(--brand)" style={{ filter: 'drop-shadow(0 0 40px rgba(var(--brand-rgb), 0.4))' }} />
              </motion.div>
              <h2 style={{ fontSize: '3.5rem', fontWeight: 950, marginBottom: '0.5rem', letterSpacing: '-0.04em' }}>SKIRMISH CONCLUDED</h2>
              <p style={{ color: 'var(--text-sub)', fontSize: '1.1rem', fontWeight: 600, maxWidth: '500px', marginBottom: '3rem' }}>The hierarchy has been established. XP rewards have been injected into your profile.</p>
              
              <div style={{ display: 'flex', gap: '1.5rem' }}>
                 <button onClick={downloadTrophy} className="btn btn-primary" style={{ padding: '1.25rem 3rem', borderRadius: '20px', fontWeight: 950, fontSize: '1.1rem', boxShadow: '0 10px 20px rgba(var(--brand-rgb), 0.2)' }}>Record Victory Shard (PDF)</button>
                 <button onClick={handleResetSkirmish} className="btn btn-secondary" style={{ padding: '1.25rem 3rem', borderRadius: '20px', fontWeight: 950, fontSize: '1.1rem' }}>Enter New Loop</button>
                  <button onClick={() => router.push('/chillout')} className="btn btn-ghost" style={{ padding: '1.25rem 2rem', borderRadius: '20px', fontWeight: 950, fontSize: '1rem' }}>Exit Zone</button>
              </div>
           </div>
        )}
      </div>

      {/* ── SIDEBAR / LEADERBOARD ─────────────────────────────────── */}
      <aside style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
         <div style={{ flex: 1, background: 'var(--surface)', borderRadius: '32px', border: '1px solid var(--border)', padding: '1.5rem', display: 'flex', flexDirection: 'column' }}>
            <h3 style={{ fontSize: '0.75rem', fontWeight: 950, textTransform: 'uppercase', color: 'var(--text-sub)', letterSpacing: '0.15em', marginBottom: '1.5rem' }}>Skirmish Standings</h3>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
               {scores && [...scores].sort((a,b) => b.points - a.points).map((s, idx) => (
                 <div key={s.userId} style={{ padding: '1rem', borderRadius: '16px', background: s.userId === profile?.id ? 'rgba(var(--brand-rgb), 0.05)' : 'var(--bg-sub)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                    <div style={{ width: '24px', fontWeight: 950, color: idx === 0 ? '#fbbf24' : 'var(--text-sub)', fontSize: '1.1rem' }}>{idx + 1}.</div>
                    <div style={{ flex: 1, fontWeight: 850, fontSize: '0.9rem' }}>{s.userName}</div>
                    <div style={{ fontWeight: 1000, color: 'var(--brand)', fontSize: '1.1rem' }}>{s.points}</div>
                 </div>
               ))}
               {(!scores || scores.length === 0) && (
                 <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-sub)', fontSize: '0.8rem', fontWeight: 600 }}>Initializing Standings...</div>
               )}
            </div>

            <div style={{ marginTop: 'auto', paddingTop: '1.5rem' }}>
               <div style={{ fontSize: '0.7rem', fontWeight: 950, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '1rem' }}>Room Population ({others.length + 1})</div>
               <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.6rem' }}>
                  <div style={{ width: '36px', height: '36px', borderRadius: '12px', background: 'var(--brand)', padding: '2px', border: activeTurnId === profile?.id ? '2px solid var(--success)' : 'none' }}>
                     <img src={profile?.avatar_url || ''} style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: '10px' }} />
                  </div>
                   {others.map((o) => (
                    <div key={o.userId} style={{ width: '36px', height: '36px', borderRadius: '12px', background: 'var(--bg-sub)', padding: '2px', border: activeTurnId === o.userId ? '2px solid var(--success)' : 'none' }}>
                      <img src={o.avatar || ''} style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: '10px' }} />
                    </div>
                  ))}
               </div>
            </div>
         </div>

         <button onClick={() => router.push('/chillout')} className="btn btn-secondary" style={{ width: '100%', padding: '1.25rem', borderRadius: '20px', fontWeight: 950, color: 'var(--error)', borderColor: '#ef444433' }}>
            ABANDON SKIRMISH
         </button>
      </aside>

      <style dangerouslySetInnerHTML={{ __html: `
        .animate-pulse { animation: pulse 2s infinite; }
        @keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(1.1); } }
        .page-fade { animation: fadeIn 0.6s cubic-bezier(0.4, 0, 0.2, 1); }
        @keyframes fadeIn { from { opacity: 0; transform: scale(0.98); } to { opacity: 1; transform: scale(1); } }
        
        .neural-bg {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: radial-gradient(circle at 50% 50%, rgba(var(--brand-rgb), 0.03) 0%, transparent 70%);
          z-index: -1;
          pointer-events: none;
        }

        .neural-bg::after {
          content: '';
          position: absolute;
          inset: 0;
          background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%239C92AC' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
        }
      `}} />
      <div className="neural-bg" />
    </div>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { motion, AnimatePresence } from 'framer-motion'
import { Mail, MessageSquare, Send, CheckCircle, ArrowLeft } from 'lucide-react'
import { submitContactForm } from '@/services/contact'

export default function ContactPage() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    category: 'General',
    message: ''
  })
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isSubmitted, setIsSubmitted] = useState(false)
  const [error, setError] = useState('')

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)
    setError('')

    try {
      const result = await submitContactForm(formData)

      if (result.ok) {
        setIsSubmitted(true)
      } else {
        setError(result.error || 'Something went wrong. Please try again.')
      }
    } catch {
      setError('Network error. Please try again.')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <main style={{ minHeight: '100vh', background: '#0a0a0a', color: 'white', position: 'relative', overflow: 'hidden' }}>
      {/* Background Gradients */}
      <div style={{ position: 'fixed', inset: 0, backgroundImage: 'linear-gradient(rgba(16,185,129,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(16,185,129,0.02) 1px, transparent 1px)', backgroundSize: '64px 64px', pointerEvents: 'none' }} />
      <div style={{ position: 'fixed', top: '-10%', right: '-5%', width: '50vw', height: '50vw', background: 'radial-gradient(circle, rgba(16,185,129,0.05) 0%, transparent 70%)', filter: 'blur(100px)', pointerEvents: 'none' }} />

      <div style={{ maxWidth: '800px', margin: '0 auto', padding: '6rem 1.5rem', position: 'relative', zIndex: 1 }}>
        <Link 
          href="/" 
          style={{ 
            display: 'inline-flex', 
            alignItems: 'center', 
            gap: '0.5rem', 
            color: '#9ca3af', 
            textDecoration: 'none', 
            fontSize: '0.875rem', 
            marginBottom: '3rem',
            transition: 'color 0.2s'
          }}
          onMouseEnter={(e) => (e.currentTarget.style.color = '#10b981')}
          onMouseLeave={(e) => (e.currentTarget.style.color = '#9ca3af')}
        >
          <ArrowLeft size={16} /> Back to Home
        </Link>

        <header style={{ marginBottom: '4rem' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '0.5rem', color: '#10b981', fontWeight: 800, fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.15em', marginBottom: '1rem' }}>
            <MessageSquare size={14} /> Contact & Feedback
          </div>
          <h1 style={{ fontSize: 'clamp(2.5rem, 5vw, 4rem)', fontWeight: 950, letterSpacing: '-0.04em', lineHeight: 1, marginBottom: '1.5rem' }}>
            Let&apos;s build the <br />
            <span style={{ color: '#10b981' }}>future together.</span>
          </h1>
          <p style={{ color: '#9ca3af', fontSize: '1.1rem', lineHeight: 1.6, maxWidth: '600px' }}>
            Have a suggestion, found a bug, or just want to say hello? Our team is always listening to the community.
          </p>
        </header>

        <div style={{ background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '24px', padding: '2.5rem', backdropFilter: 'blur(20px)' }}>
          <AnimatePresence mode="wait">
            {isSubmitted ? (
              <motion.div 
                key="success"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                style={{ textAlign: 'center', padding: '2rem 0' }}
              >
                <div style={{ width: '80px', height: '80px', background: 'rgba(16,185,129,0.1)', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 2rem' }}>
                  <CheckCircle size={40} color="#10b981" />
                </div>
                <h2 style={{ fontSize: '2rem', fontWeight: 900, marginBottom: '1rem' }}>Message Sent!</h2>
                <p style={{ color: '#9ca3af', marginBottom: '3rem' }}>
                  Thank you for reaching out. We&apos;ve received your message and will get back to you soon.
                </p>
                <button 
                  onClick={() => setIsSubmitted(false)}
                  style={{ background: '#10b981', color: '#0a0a0a', border: 'none', padding: '1rem 2.5rem', borderRadius: '12px', fontWeight: 800, cursor: 'pointer' }}
                >
                  Send Another Message
                </button>
              </motion.div>
            ) : (
              <motion.form 
                key="form"
                onSubmit={handleSubmit}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}
              >
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '1.5rem' }}>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                    <label style={{ fontSize: '0.75rem', fontWeight: 700, color: '#6b7280', textTransform: 'uppercase' }}>Full Name</label>
                    <input 
                      type="text" 
                      required
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      placeholder="Jane Doe"
                      style={{ background: 'rgba(0,0,0,0.3)', border: '1px solid #222', borderRadius: '10px', padding: '0.8rem 1rem', color: 'white', outline: 'none' }}
                    />
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                    <label style={{ fontSize: '0.75rem', fontWeight: 700, color: '#6b7280', textTransform: 'uppercase' }}>Email Address</label>
                    <input 
                      type="email" 
                      required
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      placeholder="jane@example.com"
                      style={{ background: 'rgba(0,0,0,0.3)', border: '1px solid #222', borderRadius: '10px', padding: '0.8rem 1rem', color: 'white', outline: 'none' }}
                    />
                  </div>
                </div>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                  <label style={{ fontSize: '0.75rem', fontWeight: 700, color: '#6b7280', textTransform: 'uppercase' }}>Category</label>
                  <select 
                    value={formData.category}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                    style={{ background: 'rgba(0,0,0,0.3)', border: '1px solid #222', borderRadius: '10px', padding: '0.8rem 1rem', color: 'white', outline: 'none', cursor: 'pointer' }}
                  >
                    <option value="General">General Inquiry</option>
                    <option value="Bug">Bug Report</option>
                    <option value="Feature">Feature Suggestion</option>
                    <option value="Business">Business Partnership</option>
                  </select>
                </div>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                  <label style={{ fontSize: '0.75rem', fontWeight: 700, color: '#6b7280', textTransform: 'uppercase' }}>Your Message</label>
                  <textarea 
                    required
                    rows={5}
                    value={formData.message}
                    onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                    placeholder="Tell us what's on your mind..."
                    style={{ background: 'rgba(0,0,0,0.3)', border: '1px solid #222', borderRadius: '10px', padding: '0.8rem 1rem', color: 'white', outline: 'none', resize: 'vertical' }}
                  />
                </div>

                {error && (
                  <div style={{ color: '#ef4444', fontSize: '0.875rem', textAlign: 'center' }}>
                    {error}
                  </div>
                )}

                <button 
                  type="submit" 
                  disabled={isSubmitting}
                  style={{ 
                    background: '#10b981', 
                    color: '#0a0a0a', 
                    border: 'none', 
                    padding: '1.2rem', 
                    borderRadius: '12px', 
                    fontWeight: 800, 
                    fontSize: '1rem',
                    cursor: isSubmitting ? 'not-allowed' : 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: '0.75rem',
                    transition: 'opacity 0.2s',
                    opacity: isSubmitting ? 0.7 : 1
                  }}
                >
                  {isSubmitting ? 'Sending...' : <><Send size={18} /> Send Message</>}
                </button>
              </motion.form>
            )}
          </AnimatePresence>
        </div>

        <div style={{ marginTop: '4rem', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '2rem' }}>
          <div>
            <h3 style={{ fontSize: '0.875rem', color: '#6b7280', textTransform: 'uppercase', marginBottom: '1rem' }}>Support</h3>
            <p style={{ color: '#f3f4f6', fontWeight: 600 }}>support@espeezy.com</p>
          </div>
          <div>
            <h3 style={{ fontSize: '0.875rem', color: '#6b7280', textTransform: 'uppercase', marginBottom: '1rem' }}>Business</h3>
            <p style={{ color: '#f3f4f6', fontWeight: 600 }}>business@espeezy.com</p>
          </div>
          <div>
            <h3 style={{ fontSize: '0.875rem', color: '#6b7280', textTransform: 'uppercase', marginBottom: '1rem' }}>Response Time</h3>
            <p style={{ color: '#f3f4f6', fontWeight: 600 }}>Within 24-48 hours</p>
          </div>
        </div>
      </div>
    </main>
  )
}

