// ─── Main Page ────────────────────────────────────────────────────────────────
export default function FundPage() {
  const [customAmount, setCustomAmount] = useState('')
  const [selectedPreset, setSelectedPreset] = useState<number | null>(null)
  const [donorName, setDonorName] = useState('')
  const [donorEmail, setDonorEmail] = useState('')
  const [message, setMessage] = useState('')
  const [featureTag, setFeatureTag] = useState('')
  const [isAnonymous, setIsAnonymous] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [submitError, setSubmitError] = useState('')
  const [expandedFeature, setExpandedFeature] = useState<number | null>(null)
  const [donationTotal, setDonationTotal] = useState({ total_cents: 0, count: 0 })

  const refreshDonationTotal = useCallback(() => {
    fetchDonationTotal()
      .then(total => {
        if (total) {
          setDonationTotal(total)
        }
      })
      .catch(() => { })
  }, [])

  useCheckoutAwarePolling(refreshDonationTotal)

  const getFinalAmount = () => {
    if (selectedPreset) return selectedPreset * 100
    const parsed = parseFloat(customAmount)
    if (!isNaN(parsed) && parsed >= 1) return Math.round(parsed * 100)
    return 0
  }

  const handleDonate = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitError('')
    const amountCents = getFinalAmount()
    if (amountCents < 100) {
      setSubmitError('Minimum donation is $1.00')
      return
    }
    setSubmitting(true)
    try {
      const url = await createDonationCheckout({ amountCents, donorName, donorEmail, message, featureTag: featureTag || 'general', isAnonymous })
      window.location.href = url
    } catch (_) {
      setSubmitError('Failed to start checkout. Please try again.')
    }
    setSubmitting(false)
  }

  const displayAmount = getFinalAmount() / 100
  const useDonationTier = (amount: number) => {
    if (PRESETS.includes(amount)) {
      setSelectedPreset(amount)
      setCustomAmount('')
    } else {
      setSelectedPreset(null)
      setCustomAmount(String(amount))
    }
    document.getElementById('donate-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

