function PostListingModal({ onClose, onSuccess }: { onClose: () => void, onSuccess: () => void }) {
  const [step, setStep] = useState(1)
  const [title, setTitle] = useState('')
  const [description, setDescription] = useState('')
  const [price, setPrice] = useState('0')
  const [category, setCategory] = useState('Electronics')
  const [quantity, setQuantity] = useState(1)
  const [condition, setCondition] = useState<'New' | 'Like New' | 'Used' | 'Refurbished'>('Used')
  const [meetupZone, setMeetupZone] = useState('Library')
  const [meetupDetails, setMeetupDetails] = useState('')
  const [duration, setDuration] = useState(7)
  const [paymentMethod, setPaymentMethod] = useState('BOTH')
  const [images, setImages] = useState<File[]>([])
  const [uploading, setUploading] = useState(false)
  const [agreed, setAgreed] = useState(false)

  const db = createBrowserSupabaseClient()
  const { addToast } = useNotifications()

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files)
      setImages(prev => [...prev, ...newFiles].slice(0, 5))
    }
  }

  const handlePost = async () => {
    if (!agreed) {
      addToast('Authorization Required', 'You must agree to the institutional policy before publishing a listing.', 'warning')
      return
    }
    setUploading(true)
    
    try {
      // 1. INDUSTRY GRADE VALIDATION
      listingSchema.parse({
        title,
        description,
        price: parseFloat(price),
        category,
        quantity,
        condition,
        images: ['placeholder'], // Storage handles actual paths
        location: meetupZone,
        meetup_zone: meetupZone,
        meetup_details: meetupDetails,
        duration_days: duration,
        payment_method: paymentMethod,
      })

      const { data: { user } } = await db.auth.getUser()
      if (!user) throw new Error('Auth required')

      const uploadedPaths: string[] = []
      for (const img of images) {
        const ext = img.name.split('.').pop()
        const path = `${user.id}/${Date.now()}-${Math.random().toString(36).substr(2, 9)}.${ext}`
        const { error: upErr } = await db.storage.from('marketplace').upload(path, img)
        if (!upErr) uploadedPaths.push(path)
      }

      const { error } = await db.from('marketplace_listings').insert({
        owner_id: user.id,
        title,
        description,
        price: parseFloat(price),
        is_free: parseFloat(price) === 0,
        category,
        quantity,
        condition,
        images: uploadedPaths,
        meetup_zone: meetupZone,
        meetup_details: meetupDetails,
        duration_days: duration,
        payment_method: paymentMethod,
        status: 'AVAILABLE'
      })

      if (error) throw error
      addToast('Listing Created', 'Your resource is now visible to the institutional graph.', 'success')
      onSuccess()
    } catch (err: unknown) {
      addToast('Upload Failed', (err instanceof Error ? err.message : 'Unknown error'), 'error')
    } finally {
      setUploading(false)
    }
  }

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 11000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '1rem' }}>
      <div style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(10px)' }} onClick={onClose} />
      
      <div className="page-fade" style={{ 
        width: '100%', 
        maxWidth: '550px', 
        background: 'var(--surface)', 
        borderRadius: '28px', 
        overflow: 'hidden', 
        position: 'relative',
        boxShadow: 'var(--shadow-2xl)',
        border: '1px solid var(--border)'
      }}>
        <div style={{ padding: '1.5rem 2rem', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ fontSize: '1.25rem', fontWeight: 950, margin: 0 }}>List New Resource</h2>
          <div style={{ fontSize: '0.7rem', fontWeight: 900, color: 'var(--brand)', background: 'rgba(var(--brand-rgb), 0.1)', padding: '4px 10px', borderRadius: '10px' }}>
            STEP {step} / 3
          </div>
        </div>

        <div style={{ padding: '2rem', maxHeight: '70vh', overflowY: 'auto' }}>
          {step === 1 && (
            <div className="page-fade" style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
              <div>
                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Resource Title</label>
                <input 
                  type="text" 
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="e.g. Psychology Textbook, Graphing Calculator..."
                  style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none' }}
                />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Category</label>
                  <select 
                    value={category}
                    onChange={(e) => setCategory(e.target.value)}
                    style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none' }}
                  >
                    {['Electronics', 'Textbooks', 'Lab Equipment', 'Stationery', 'Hardware', 'Other'].map(cat => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Condition</label>
                  <select 
                    value={condition}
                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setCondition(e.target.value as any)}
                    style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none' }}
                  >
                    <option value="New">New</option>
                    <option value="Like New">Like New</option>
                    <option value="Used">Used</option>
                    <option value="Refurbished">Refurbished</option>
                  </select>
                </div>
              </div>
              <div>
                 <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Visual Evidence ({images.length}/5)</label>
                 <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '0.5rem' }}>
                    {images.map((img, i) => (
                      <div key={i} style={{ aspectRatio: '1/1', background: 'var(--bg-sub)', borderRadius: '10px', overflow: 'hidden', position: 'relative' }}>
                        <img src={URL.createObjectURL(img)} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                      </div>
                    ))}
                    {images.length < 5 && (
                      <label style={{ aspectRatio: '1/1', background: 'var(--bg-sub)', border: '2px dashed var(--border)', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', transition: 'all 0.2s' }}>
                        <Camera size={24} className="text-sub" />
                        <input type="file" hidden multiple accept="image/*" onChange={handleImageChange} />
                      </label>
                    )}
                 </div>
              </div>
              <div>
                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Condition & Description</label>
                <textarea 
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  rows={4}
                  placeholder="Describe the condition, version, or any specific details..."
                  style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none', resize: 'none' }}
                />
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="page-fade" style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
               <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Price ($)</label>
                    <div style={{ position: 'relative' }}>
                       <DollarSign size={16} style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-sub)' }} />
                       <input 
                         type="number" 
                         value={price}
                         onChange={(e) => setPrice(e.target.value)}
                         style={{ width: '100%', padding: '0.9rem 0.9rem 0.9rem 2.5rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none' }}
                       />
                    </div>
                  </div>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Quantity / Stock</label>
                    <input 
                      type="number" 
                      value={quantity}
                      onChange={(e) => setQuantity(parseInt(e.target.value))}
                      min={1}
                      style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none' }}
                    />
                  </div>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Max Duration (Days)</label>
                    <input 
                      type="number" 
                      value={duration}
                      onChange={(e) => setDuration(parseInt(e.target.value))}
                      style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none' }}
                    />
                  </div>
               </div>

               <div>
                 <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Academic Safe Zone</label>
                 <select 
                   value={meetupZone}
                   onChange={(e) => setMeetupZone(e.target.value)}
                   style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none', appearance: 'none' }}
                 >
                   <option>Library</option>
                   <option>Student Union</option>
                   <option>Science Hub</option>
                   <option>Cafeteria</option>
                   <option>Custom Location</option>
                 </select>
               </div>
               
               <div>
                  <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Meetup Details</label>
                  <input 
                    type="text" 
                    value={meetupDetails}
                    onChange={(e) => setMeetupDetails(e.target.value)}
                    placeholder="e.g. Near the main entrance, 2nd floor study area..."
                    style={{ width: '100%', padding: '0.9rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'var(--bg-sub)', outline: 'none' }}
                  />
               </div>

               <div>
                  <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.6rem' }}>Accepted Payments</label>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem' }}>
                     {['CASH', 'STRIPE', 'BOTH'].map(m => (
                       <button 
                         key={m} 
                         onClick={() => setPaymentMethod(m)}
                         style={{ 
                           padding: '0.75rem', 
                           borderRadius: '10px', 
                           border: '1px solid var(--border)', 
                           background: paymentMethod === m ? 'var(--brand)' : 'var(--bg-sub)',
                           color: paymentMethod === m ? 'white' : 'var(--text-sub)',
                           fontSize: '0.7rem',
                           fontWeight: 800
                         }}
                       >
                         {m}
                       </button>
                     ))}
                  </div>
               </div>
            </div>
          )}

          {step === 3 && (
            <div className="page-fade" style={{ display: 'flex', flexDirection: 'column', gap: '2rem', textAlign: 'center' }}>
               <div style={{ padding: '2rem', background: 'rgba(239, 68, 68, 0.05)', borderRadius: '24px', border: '2px dashed rgba(239, 68, 68, 0.2)' }}>
                  <AlertTriangle className="text-error" size={40} style={{ margin: '0 auto', marginBottom: '1.5rem' }} />
                  <h3 style={{ fontWeight: 950, color: 'var(--error)' }}>LEGAL & POLICY ALERT</h3>
                  <p style={{ fontSize: '0.85rem', color: 'var(--text-sub)', lineHeight: 1.6, marginTop: '1rem' }}>
                    Trading prohibited substances, dangerous hardware, or copyrighted materials is an institutional violation. 
                    Your account and listing will be immediately logged for human review if reported. 
                    Illegal activities will be forwarded to student conduct boards.
                  </p>
               </div>
               
               <label style={{ display: 'flex', alignItems: 'center', gap: '1rem', cursor: 'pointer', justifyContent: 'center' }}>
                  <input 
                    type="checkbox" 
                    checked={agreed} 
                    onChange={(e) => setAgreed(e.target.checked)}
                    style={{ width: '20px', height: '20px', accentColor: 'var(--brand)' }}
                  />
                  <span style={{ fontSize: '0.9rem', fontWeight: 700 }}>I strictly adhere to these policies.</span>
               </label>
            </div>
          )}
        </div>

        <div style={{ padding: '1.5rem 2rem', borderTop: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <button 
            onClick={() => step > 1 ? setStep(s => s - 1) : onClose()}
            className="btn btn-secondary"
            style={{ padding: '0.75rem 1.5rem', borderRadius: '12px', fontWeight: 800, border: '1px solid var(--border)' }}
          >
            {step === 1 ? 'Cancel' : 'Back'}
          </button>
          
          <button 
            onClick={() => step < 3 ? setStep(s => s + 1) : handlePost()}
            className="btn btn-primary"
            disabled={uploading}
            style={{ padding: '0.75rem 2rem', borderRadius: '12px', fontWeight: 900, minWidth: '120px' }}
          >
            {uploading ? <Loader2 className="animate-spin" size={20} /> : step === 3 ? 'Finalize Post' : 'Continue'}
          </button>
        </div>
      </div>
    </div>
  )
}

function ItemDetailModal({ listing, onClose }: { listing: Listing, onClose: () => void }) {
  const db = createBrowserSupabaseClient()
  
  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 12000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '1rem' }}>
      <div style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.8)', backdropFilter: 'blur(12px)' }} onClick={onClose} />
      
      <div className="page-fade" style={{ 
        width: '100%', 
        maxWidth: '900px', 
        background: 'var(--surface)', 
        borderRadius: '40px', 
        overflow: 'hidden', 
        position: 'relative',
        boxShadow: 'var(--shadow-2xl)',
        border: '1px solid var(--border)',
        display: 'flex',
        flexDirection: 'column',
        maxHeight: '90vh'
      }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'minmax(400px, 1.2fr) 1fr', height: '100%' }}>
          
          {/* Left: Media Area */}
          <div style={{ background: 'var(--bg-sub)', position: 'relative' }}>
            {listing.images?.[0] ? (
              <Image 
                src={db.storage.from('marketplace').getPublicUrl(listing.images[0]).data.publicUrl} 
                alt={listing.title} 
                fill
                className="object-cover"
              />
            ) : (
              <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-sub)' }}>
                <Plus size={48} opacity={0.3} />
              </div>
            )}
            <button 
              onClick={onClose}
              style={{ position: 'absolute', top: '1.5rem', left: '1.5rem', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(10px)', border: 'none', color: 'white', padding: '0.75rem', borderRadius: '16px', cursor: 'pointer', fontWeight: 900 }}
            >
               BACK
            </button>
          </div>

          {/* Right: Info Area */}
          <div style={{ padding: '3rem', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '2rem' }}>
            <div>
              <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1rem' }}>
                <span style={{ padding: '6px 14px', background: 'rgba(var(--brand-rgb), 0.1)', color: 'var(--brand)', borderRadius: '100px', fontSize: '0.75rem', fontWeight: 950 }}>{listing.category}</span>
                <span style={{ padding: '6px 14px', background: 'var(--bg-sub)', color: 'var(--text-sub)', borderRadius: '100px', fontSize: '0.75rem', fontWeight: 950 }}>{listing.condition}</span>
              </div>
              <h2 style={{ fontSize: '2.5rem', fontWeight: 950, letterSpacing: '-0.04em', color: 'white', lineHeight: 1.1, marginBottom: '1rem' }}>{listing.title}</h2>
              <div style={{ fontSize: '2rem', fontWeight: 950, color: 'var(--brand)' }}>{listing.price === 0 ? 'FREE / SHARE' : `£${listing.price}`}</div>
            </div>

            <div style={{ padding: '1.5rem', background: 'rgba(255,255,255,0.02)', borderRadius: '24px', border: '1px solid var(--border)' }}>
              <div style={{ fontSize: '0.75rem', fontWeight: 950, color: 'var(--text-sub)', textTransform: 'uppercase', marginBottom: '0.75rem', letterSpacing: '2px' }}>Description</div>
              <p style={{ margin: 0, color: 'rgba(255,255,255,0.7)', lineHeight: 1.6, fontSize: '0.95rem' }}>{listing.description}</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
               <div style={{ padding: '1.25rem', background: 'var(--bg-sub)', borderRadius: '20px' }}>
                  <div style={{ color: 'var(--brand)', marginBottom: '0.5rem' }}><MapPin size={20} /></div>
                  <div style={{ fontWeight: 900, color: 'white', fontSize: '0.9rem' }}>{listing.meetup_zone}</div>
                  <div style={{ fontSize: '0.7rem', color: 'var(--text-sub)', marginTop: '0.25rem' }}>{listing.meetup_details}</div>
               </div>
               <div style={{ padding: '1.25rem', background: 'var(--bg-sub)', borderRadius: '20px' }}>
                  <div style={{ color: 'var(--brand)', marginBottom: '0.5rem' }}><Clock size={20} /></div>
                  <div style={{ fontWeight: 900, color: 'white', fontSize: '0.9rem' }}>{listing.duration_days} Days Max</div>
                  <div style={{ fontSize: '0.7rem', color: 'var(--text-sub)', marginTop: '0.25rem' }}>Default Loan Agreement</div>
               </div>
            </div>

            <div style={{ marginTop: 'auto', paddingTop: '2rem', borderTop: '1px solid var(--border)' }}>
              <div style={{ fontSize: '0.75rem', fontWeight: 950, color: 'var(--text-sub)', textTransform: 'uppercase', marginBottom: '1.25rem' }}>Listed By</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '1.25rem' }}>
                <div style={{ width: '56px', height: '56px', borderRadius: '20px', background: 'var(--brand)', overflow: 'hidden' }}>
                  {listing.profiles?.avatar_url && <Image src={listing.profiles.avatar_url} width={56} height={56} alt="Seller" />}
                </div>
                <div>
                   <div style={{ fontWeight: 950, color: 'white', fontSize: '1.1rem' }}>{listing.profiles?.full_name}</div>
                   <div style={{ fontSize: '0.8rem', color: 'var(--brand)', fontWeight: 800 }}>Institutional Specialist / {listing.profiles?.role}</div>
                </div>
              </div>
              <button 
                className="btn btn-primary"
                style={{ width: '100%', marginTop: '2rem', padding: '1.25rem', borderRadius: '20px', fontWeight: 950, fontSize: '1rem' }}
              >
                Request Access via Node
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { db, createBrowserSupabaseClient } from '@/lib/db-client'
import Image from 'next/image'
import { 
  Search, 
  User, 
  MessageSquare, 
  ExternalLink, 
  Users, 
  GraduationCap, 
  Sparkles, 
  Fingerprint, 
  Compass,
  ChevronRight,
  Info
} from 'lucide-react'
import { usePresence } from '@/components/PresenceProvider'
import { Profile } from '@/types/database'
import { useSmartLoading } from '@/components/GlobalLoadingProvider'

export default function NetworkPage() {
  const [teamMembers, setTeamMembers] = useState<Profile[]>([])
  const [personalNetwork, setPersonalNetwork] = useState<Profile[]>([])
  const [suggestedUsers, setSuggestedUsers] = useState<Profile[]>([])
  const [globalCount, setGlobalCount] = useState(0)
  const [search, setSearch] = useState('')
  const [loading, setLoading] = useState(true)
  
  const router = useRouter()
  const { withLoading } = useSmartLoading()
  const db = useMemo(() => createBrowserSupabaseClient(), [])
  const { onlineUsers } = usePresence()

  const fetchMetrics = useCallback(async () => {
    // 1. Fetch Global User Count
    const { count } = await db.from('profiles').select('*', { count: 'exact', head: true })
    setGlobalCount(count || 0)

    const { data: { user } } = await db.auth.getUser()
    if (!user) return

    // 2. Fetch Team Members
    const { data: me } = await db.from('profiles').select('group_id').eq('id', user.id).single()
    if (me?.group_id) {
      const { data: team } = await db.from('profiles').select('*').eq('group_id', me.group_id).neq('id', user.id)
      setTeamMembers(team || [])
    }

    // 3. Fetch Personal Network (Connections)
    const { data: conn } = await db
      .from('user_connections')
      .select('user_id, target_id')
      .or(`user_id.eq.${user.id},target_id.eq.${user.id}`)
      .eq('status', 'connected')
    
    let connectionIds: string[] = []
    if (conn) {
      connectionIds = conn.map((c: { user_id: string; target_id: string }) => c.user_id === user.id ? c.target_id : c.user_id)
      if (connectionIds.length > 0) {
        const { data: net } = await db.from('profiles').select('*').in('id', connectionIds)
        setPersonalNetwork(net || [])
      }
    }

    // 4. Fetch Suggestions (Scholars you may know)
    // EXCLUDE: Self, Team Members, and already connected Peers
    const excludeIds = [user.id, ...(teamMembers.map(m => m.id)), ...connectionIds]
    
    const { data: sugg } = await db
      .from('profiles')
      .select('*')
      .not('id', 'in', `(${excludeIds.join(',')})`)
      .limit(10)
    
    setSuggestedUsers(sugg || [])
    
    setLoading(false)
  }, [db, teamMembers])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void fetchMetrics()
  }, [fetchMetrics])

  const filterList = (list: Profile[]) => {
    return list.filter(u => 
      u.full_name?.toLowerCase().includes(search.toLowerCase()) || 
      u.course_name?.toLowerCase().includes(search.toLowerCase())
    )
  }

  return (
    <div className="page-fade" style={{ maxWidth: '1000px', margin: '0 auto', paddingBottom: '6rem' }}>
      
      {/* ── NETWORK HUD ────────────────────────────────────────────────── */}
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '3rem', flexWrap: 'wrap', gap: '2rem' }}>
        <div>
          <h1 style={{ fontSize: 'clamp(2rem, 5vw, 3rem)', fontWeight: 950, letterSpacing: '-0.06em', margin: 0, lineHeight: 0.9 }}>
            Peer Network
          </h1>
          <div style={{ display: 'flex', gap: '1.5rem', marginTop: '1.5rem' }}>
             <div style={{ display: 'flex', flexDirection: 'column' }}>
                <span style={{ fontSize: '0.65rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', letterSpacing: '0.1em' }}>Global Community</span>
                <span style={{ fontSize: '1.5rem', fontWeight: 950, color: 'var(--brand)' }}>{globalCount.toLocaleString()} <span style={{ fontSize: '0.8rem', opacity: 0.5 }}>Peers</span></span>
             </div>
             <div style={{ display: 'flex', flexDirection: 'column' }}>
                <span style={{ fontSize: '0.65rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', letterSpacing: '0.1em' }}>My Network</span>
                <span style={{ fontSize: '1.5rem', fontWeight: 950, color: 'var(--success)' }}>{personalNetwork.length} <span style={{ fontSize: '0.8rem', opacity: 0.5 }}>Connections</span></span>
             </div>
          </div>
        </div>

        <div style={{ width: '100%', maxWidth: '400px', position: 'relative' }}>
          <Search size={20} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-sub)' }} />
          <input 
            type="text" 
            placeholder="Search scholars by name or course..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ 
              width: '100%', 
              padding: '1rem 1rem 1rem 3.5rem', 
              borderRadius: '16px', 
              border: '1px solid var(--border)', 
              background: 'var(--surface)', 
              fontSize: '1rem',
              fontWeight: 600,
              boxShadow: 'var(--shadow-sm)',
              outline: 'none'
            }}
          />
        </div>
      </header>

      {/* ── NETWORK SECTIONS ───────────────────────────────────────────── */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '3rem' }}>
        
        {/* 1. Global Discovery */}
        <NetworkSection 
          title="Scholars you may know" 
          icon={<Compass size={18} />} 
          users={filterList(suggestedUsers)} 
          loading={loading}
          router={router}
          onlineUsers={onlineUsers}
        />

        {/* 2. My Peer Network */}
        <NetworkSection 
          title="My Peer Network" 
          icon={<Fingerprint size={18} />} 
          users={filterList(personalNetwork)} 
          loading={loading}
          router={router}
          onlineUsers={onlineUsers}
        />

        {/* 3. Team Members */}
        <NetworkSection 
          title="Team Roster" 
          icon={<Users size={18} />} 
          users={filterList(teamMembers)} 
          loading={loading}
          router={router}
          onlineUsers={onlineUsers}
        />

      </div>

      <style jsx>{`
        @keyframes fadeInHeader { from { opacity: 0; transform: translateY(-10px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
    </div>
  )
}

function NetworkSection({ title, icon, users, loading, router, onlineUsers }: { 
  title: string, 
  icon: React.ReactNode, 
  users: Profile[], 
  loading: boolean,
  router: { push: (url: string) => void },
  onlineUsers: Set<string>
}) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column' }}>
       <div style={{ 
         display: 'flex', 
         alignItems: 'center', 
         padding: '0.5rem 0.75rem', 
         borderBottom: '1px solid var(--border)',
         marginBottom: '0.75rem',
         gap: '0.75rem',
         background: 'rgba(var(--brand-rgb), 0.02)',
         borderRadius: '8px',
         color: 'var(--text-sub)'
       }}>
          <Search size={14} style={{ opacity: 0.5 }} />
          <h2 style={{ fontSize: '0.7rem', fontWeight: 900, textTransform: 'uppercase', letterSpacing: '0.1em', margin: 0, flex: 1 }}>
            {title} <span style={{ opacity: 0.5, fontWeight: 700 }}>({users.length})</span>
          </h2>
          <div style={{ opacity: 0.6 }}>{icon}</div>
       </div>

       {loading ? (
         <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
            {[1, 2, 3].map(i => <div key={i} className="skeleton" style={{ height: '60px', borderRadius: '12px' }} />)}
         </div>
       ) : users.length === 0 ? (
          <div style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-sub)', fontSize: '0.85rem', background: 'var(--bg-sub)', borderRadius: '16px', border: '1px dashed var(--border)' }}>
             No peers identified in this sector.
          </div>
       ) : (
         <div style={{ display: 'flex', flexDirection: 'column' }}>
            {users.map(u => (
              <NetworkRow key={u.id} user={u} router={router} isOnline={onlineUsers.has(u.id)} />
            ))}
         </div>
       )}
    </div>
  )
}

function NetworkRow({ user, router, isOnline }: { user: Profile, router: { push: (url: string) => void }, isOnline: boolean }) {
  return (
    <div 
      className="network-row"
      style={{ 
        display: 'flex', 
        alignItems: 'center', 
        padding: '0.75rem 0', 
        borderBottom: '1px solid rgba(var(--text-main-rgb), 0.05)',
        transition: 'all 0.2s',
        gap: '1rem'
      }}
    >
      <div style={{ position: 'relative' }}>
        <div style={{ 
          width: '44px', 
          height: '44px', 
          borderRadius: '12px', 
          background: 'var(--bg-sub)', 
          border: '1px solid var(--border)', 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center',
          overflow: 'hidden',
          fontSize: '0.9rem',
          fontWeight: 900,
          color: 'var(--brand)'
        }}>
          {user.avatar_url ? (
            <Image 
              src={user.avatar_url} 
              alt={user.full_name || 'Profile'} 
              width={44} 
              height={44} 
              style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
            />
          ) : user.full_name?.[0]}
        </div>
        {isOnline && (
           <div style={{ 
             position: 'absolute', 
             bottom: '-2px', 
             right: '-2px', 
             width: '12px', 
             height: '12px', 
             borderRadius: '50%', 
             background: 'var(--success)', 
             border: '2px solid var(--surface)',
             boxShadow: '0 0 10px var(--success)' 
           }} />
        )}
      </div>

      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: '1rem', fontWeight: 850, color: 'var(--text-main)', lineHeight: 1.2 }}>{user.full_name}</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', color: 'var(--text-sub)', fontSize: '0.75rem', marginTop: '0.25rem' }}>
           <GraduationCap size={12} />
           <span style={{ fontWeight: 600, textOverflow: 'ellipsis', overflow: 'hidden', whiteSpace: 'nowrap' }}>{user.course_name || user.tagline || 'Academic Collaborator'}</span>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '0.5rem' }}>
        <button 
          onClick={() => router.push(`/network/profile/${user.id}`)}
          className="btn-phonebook"
          style={{ 
            padding: '0.5rem 1rem', 
            borderRadius: '10px', 
            background: 'var(--bg-sub)', 
            border: '1px solid var(--border)', 
            fontSize: '0.75rem', 
            fontWeight: 800, 
            display: 'flex', 
            alignItems: 'center', 
            gap: '0.5rem',
            color: 'var(--text-main)' 
          }}
        >
          <User size={14} />
          <span className="desktop-only">Profile</span>
        </button>
        <button 
          onClick={() => router.push(`/network/chat/${user.id}`)}
          className="btn-phonebook"
          style={{ 
            padding: '0.5rem 1rem', 
            borderRadius: '10px', 
            background: 'var(--brand)', 
            border: 'none', 
            fontSize: '0.75rem', 
            fontWeight: 900, 
            display: 'flex', 
            alignItems: 'center', 
            gap: '0.5rem',
            color: 'white',
            boxShadow: '0 4px 10px rgba(var(--brand-rgb), 0.2)' 
          }}
        >
          <MessageSquare size={14} />
          <span className="desktop-only">Message</span>
        </button>
      </div>

      <style jsx>{`
        .network-row:hover {
           background: rgba(var(--brand-rgb), 0.02);
           padding-left: 0.5rem;
           padding-right: 0.5rem;
           border-radius: 12px;
        }
        @media (max-width: 600px) {
           .desktop-only { display: none; }
        }
      `}</style>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { 
  X, UserCircle, ShieldCheck, Mail, Target, Award, Hash, 
  GraduationCap, Calendar, UserPlus, Check, MessageSquare, 
  Video, Info, Clock, ChevronLeft, ExternalLink, Activity, Terminal
} from 'lucide-react'
import Link from 'next/link'
import { Profile } from '@/types/database'
import { useSmartLoading } from '@/components/GlobalLoadingProvider'
import {
  createNotification,
  fetchConnectionRecords,
  fetchGroupById,
  fetchProfileById,
  getAuthUser,
  upsertPendingConnectionRequest,
} from '@/services/dashboard'

export default function StudentProfilePage() {
  const params = useParams()
  const router = useRouter()
  const studentId = params.id as string

  const [member, setMember] = useState<(Profile & { groups?: any }) | null>(null)
  const [me, setMe] = useState<Profile | null>(null)
  const [loading, setLoading] = useState(true)
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'pending' | 'connected'>('idle')
  const [activeTab, setActiveTab] = useState<'info' | 'accomplishments'>('info')
  const { withLoading, showConfirmation } = useSmartLoading()

  const formatRelativeTime = (date: string | number | Date | null) => {
    if (!date) return 'Unknown'
    const now = new Date()
    const targetDate = date.seconds ? new Date(date.seconds * 1000) : new Date(date)
    const diff = now.getTime() - targetDate.getTime()
    const mins = Math.floor(diff / 60000)
    if (mins < 1) return 'Just now'
    if (mins < 60) return `${mins}m ago`
    const hours = Math.floor(mins / 60)
    if (hours < 24) return `${hours}h ago`
    return targetDate.toLocaleDateString()
  }

  useEffect(() => {
    fetchProfileData()
  }, [studentId])

  const fetchProfileData = async () => {
    setLoading(true)
    const currentUser = await getAuthUser()
    setMe(currentUser)

    try {
      const profileData = await fetchProfileById(studentId)
      if (profileData) {
        
        // Fetch group details if group_id exists
        let groupData = null
        if (profileData.group_id) {
          groupData = await fetchGroupById(profileData.group_id)
        }

        setMember({ ...profileData, groups: groupData })

        if (currentUser) {
          const conns = await fetchConnectionRecords(currentUser.id, studentId)
          
          const connection = conns.find((c) => c.status === 'connected' || c.status === 'accepted')
          const pendingSentByMe = conns.find((c) => c.user_id === currentUser.id && c.status === 'pending')

          if (connection) {
            setConnectionStatus('connected')
          } else if (pendingSentByMe) {
            setConnectionStatus('pending')
          } else {
            setConnectionStatus('idle')
          }
        }
      }
    } catch (err: unknown) {
      console.error('Profile fetch error:', err instanceof Error ? err.message : 'unknown error')
    }

    setLoading(false)
  }

  const handleConnect = async () => {
    if (!me || !member || connectionStatus !== 'idle') return

    await withLoading(async () => {
      try {
        await upsertPendingConnectionRequest(me.id, member.id)

        await createNotification({
          user_id: member.id,
          type: 'connection_request',
          title: 'New Connection Request',
          message: `${me.email || 'A peer'} wants to connect with you.`,
          metadata: { sender_id: me.id },
        })

        setConnectionStatus('pending')
        
        showConfirmation({
          title: 'Request Sent',
          message: `Your connection request has been sent to ${member.full_name?.split(' ')[0]}.`,
          type: 'success',
          onConfirm: () => {}
        })
      } catch (err: unknown) {
        throw err
      }
    }, 'Authenticating Request...')
  }

  if (loading) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '60vh' }}>
        <div className="spinner-mini" style={{ width: '32px', height: '32px', borderTopColor: 'var(--brand)' }} />
      </div>
    )
  }

  if (!member) {
    return (
      <div style={{ textAlign: 'center', padding: '4rem 2rem' }}>
        <h2 style={{ fontWeight: 800 }}>Scholar Not Identified</h2>
        <Link href="/network" className="btn btn-secondary btn-inline" style={{ marginTop: '1rem' }}>Back to Network</Link>
      </div>
    )
  }

  return (
    <div style={{ maxWidth: '1000px', margin: '0 auto', padding: '0 var(--p-safe) 5rem', animation: 'fadeIn 0.5s ease-out' }}>
      
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.25rem', marginTop: '1rem' }}>
        <button 
          onClick={() => router.back()}
          style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: '10px', padding: '0.5rem', cursor: 'pointer', color: 'var(--text-main)' }}
        >
          <ChevronLeft size={20} />
        </button>
        <h1 style={{ fontSize: '1.25rem', fontWeight: 900, margin: 0 }}>Scholar Transcript</h1>
      </div>

      <div className="profile-main-layout" style={{ display: 'grid', gridTemplateColumns: 'minmax(280px, 320px) 1fr', gap: '1.5rem' }}>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          <div style={{ background: 'var(--surface)', borderRadius: '16px', border: '1px solid var(--border)', padding: '1.5rem', textAlign: 'center', boxShadow: 'var(--shadow-sm)' }}>
            <div style={{ position: 'relative', width: '90px', height: '90px', margin: '0 auto 1rem' }}>
              <div style={{ width: '100%', height: '100%', borderRadius: '50%', background: 'var(--bg-sub)', border: '3px solid var(--surface)', boxShadow: 'var(--shadow-md)', overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {member.avatar_url ? (
                  <img src={member.avatar_url} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                ) : (
                  <UserCircle size={60} color="var(--text-sub)" />
                )}
              </div>
              <div style={{ position: 'absolute', bottom: '2px', right: '2px', width: '14px', height: '14px', borderRadius: '50%', background: 'var(--success)', border: '2px solid var(--surface)' }} />
            </div>

            <h2 style={{ fontSize: '1.5rem', fontWeight: 950, marginBottom: '0.25rem' }}>{member.full_name}</h2>
            {member.tagline && (
              <p style={{ fontSize: '0.85rem', color: 'var(--brand)', fontWeight: 800, fontStyle: 'italic', marginBottom: '1rem' }}>
                &quot;{member.tagline}&quot;
              </p>
            )}

            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.3rem', marginBottom: '1.25rem' }}>
               <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem', color: 'var(--text-sub)', fontSize: '0.75rem', fontWeight: 700 }}>
                  <ShieldCheck size={14} color="var(--brand)" /> 
                  {member.rank || 'Scholar'}
               </div>
               <div style={{ color: 'var(--text-sub)', fontSize: '0.7rem', fontWeight: 600 }}>
                 Last active {formatRelativeTime(member.last_seen || null)}
               </div>
            </div>

            <button 
              onClick={handleConnect}
              disabled={connectionStatus !== 'idle'}
              className="btn btn-primary"
              style={{ fontSize: '0.9rem', padding: '0.75rem' }}
            >
              {connectionStatus === 'connected' ? <Check size={18} /> : connectionStatus === 'pending' ? <Clock size={18} /> : <UserPlus size={18} />}
              {connectionStatus === 'connected' ? 'Connected' : connectionStatus === 'pending' ? 'Pending' : 'Connect'}
            </button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem' }}>
             {[
               { id: 'info', icon: Info, label: 'Stats' },
               { id: 'chat', icon: MessageSquare, label: 'Chat', disabled: connectionStatus !== 'connected' },
               { id: 'accomplishments', icon: Award, label: 'Badges' }
             ].map((item) => (
               <button
                 key={item.id}
                 onClick={() => {
                   if (item.disabled) return;
                   if (item.id === 'chat') router.push(`/network/chat/${studentId}`);
                   else setActiveTab(item.id as 'info' | 'accomplishments');
                 }}
                 style={{ 
                   borderRadius: '12px', border: activeTab === item.id ? '2px solid var(--brand)' : '1px solid var(--border)',
                   background: activeTab === item.id ? 'var(--bg-sub)' : 'var(--surface)',
                   color: activeTab === item.id ? 'var(--brand)' : 'var(--text-sub)',
                   display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.4rem',
                   padding: '0.75rem 0', fontSize: '0.7rem', fontWeight: 800, cursor: item.disabled ? 'not-allowed' : 'pointer',
                   opacity: item.disabled ? 0.4 : 1, transition: 'all 0.2s'
                 }}
               >
                 <item.icon size={16} />
                 {item.label}
               </button>
             ))}
          </div>
        </div>

        <div style={{ background: 'var(--surface)', borderRadius: '16px', border: '1px solid var(--border)', padding: '1.5rem', boxShadow: 'var(--shadow-sm)' }}>
           {activeTab === 'info' && (
              <div className="page-fade">
                 <div style={{ marginBottom: '1.5rem' }}>
                    <h3 style={{ fontSize: '1rem', fontWeight: 900, marginBottom: '0.75rem' }}>Scholar Overview</h3>
                    <div style={{ padding: '1rem', background: 'var(--bg-sub)', borderRadius: '12px', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                       <GraduationCap size={18} color="var(--brand)" />
                       <div>
                          <div style={{ fontSize: '0.6rem', fontWeight: 800, color: 'var(--text-sub)', textTransform: 'uppercase' }}>Current Track</div>
                          <div style={{ fontSize: '0.9rem', fontWeight: 800 }}>{member.course_name || 'Independent Scholar'}</div>
                       </div>
                    </div>
                 </div>

                 <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1.5rem' }}>
                    <div style={{ background: 'var(--bg-sub)', padding: '1rem', borderRadius: '12px', border: '1px solid var(--border)' }}>
                       <div style={{ fontSize: '0.6rem', fontWeight: 800, color: 'var(--text-sub)', textTransform: 'uppercase' }}>Score</div>
                       <div style={{ fontSize: '1.5rem', fontWeight: 950, color: 'var(--brand)' }}>{member.total_score}</div>
                    </div>
                    <div style={{ background: 'var(--bg-sub)', padding: '1rem', borderRadius: '12px', border: '1px solid var(--border)' }}>
                       <div style={{ fontSize: '0.6rem', fontWeight: 800, color: 'var(--text-sub)', textTransform: 'uppercase' }}>Grad Year</div>
                       <div style={{ fontSize: '0.9rem', fontWeight: 800, marginTop: '0.4rem' }}>{member.completion_year || 'N/A'}</div>
                    </div>
                 </div>

                  {member.stack && (
                    <div style={{ marginBottom: '1.5rem' }}>
                       <h4 style={{ fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.5rem' }}>
                          <Terminal size={14} style={{ verticalAlign: 'middle', marginRight: '4px' }} /> Technical Arsenal
                       </h4>
                       <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.4rem' }}>
                          {member.stack.split(',').map((tech: string, idx: number) => (
                             <span key={idx} style={{ padding: '0.3rem 0.6rem', background: 'var(--bg-sub)', border: '1px solid var(--border)', borderRadius: '6px', fontSize: '0.75rem', fontWeight: 800, color: 'var(--brand)' }}>
                                {tech.trim()}
                             </span>
                          ))}
                       </div>
                    </div>
                  )}

                 <div style={{ marginBottom: '1.5rem' }}>
                    <h4 style={{ fontSize: '0.75rem', fontWeight: 900, textTransform: 'uppercase', color: 'var(--text-sub)', marginBottom: '0.5rem' }}>Scholar Identity</h4>
                    <p style={{ fontSize: '0.9rem', lineHeight: 1.6, color: 'var(--text-main)', opacity: 0.85 }}>
                      {member.biography || `An active scholar in the Espeezy network, specializing in ${member.course_name || 'their academic field'}.`}
                    </p>
                 </div>
              </div>
           )}

           {activeTab === 'accomplishments' && (
              <div className="page-fade">
                 <h3 style={{ fontSize: '1rem', fontWeight: 900, marginBottom: '1.25rem' }}>Verified Credentials</h3>
                 <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(130px, 1fr))', gap: '0.75rem' }}>
                    {member.badges_count && member.badges_count > 0 ? (
                      [...Array(member.badges_count)].map((_, i) => (
                         <div key={i} style={{ background: 'var(--bg-sub)', padding: '1rem', borderRadius: '12px', border: '1px solid var(--border)', textAlign: 'center' }}>
                            <Award size={24} color="#f59e0b" style={{ marginBottom: '0.5rem' }} />
                            <div style={{ fontWeight: 800, fontSize: '0.75rem' }}>Verified</div>
                         </div>
                      ))
                    ) : (
                      <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '3rem 1rem', background: 'var(--bg-sub)', borderRadius: '12px', opacity: 0.5 }}>
                         <Award size={40} style={{ marginBottom: '0.5rem' }} />
                         <p style={{ fontWeight: 700, fontSize: '0.85rem' }}>No credentials earned yet.</p>
                      </div>
                    )}
                 </div>
              </div>
           )}
        </div>
      </div>

      <style jsx>{`
        @keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        @media (max-width: 800px) {
          .profile-main-layout { grid-template-columns: 1fr !important; }
        }
      `}</style>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useNotifications } from '@/components/NotificationProvider'
import type { Notification } from '@/types/ui'
import { Bell, UserPlus, Check, X, Shield, Clock, Inbox, Mail, MessageSquare } from 'lucide-react'
import { DateTime } from '@/utils/dateTime'
import {
  createNotification,
  deleteConnectionRecord,
  fetchNotificationSettings,
  getAuthUser,
  setConnectionAccepted,
  updateNotificationSetting,
} from '@/services/dashboard'

type InboxNotification = Notification & { metadata?: { sender_id?: string } }

export default function NotificationsPage() {
  const { notifications, markAsRead, markAllAsRead, addToast, refreshNotifications } = useNotifications()
  const [loading, setLoading] = useState(false)
  const [view, setView] = useState<'inbox' | 'settings'>('inbox')

  // Settings state
  const [settings, setSettings] = useState({
    email_notifications: true,
    push_notifications: true,
    marketing_emails: false
  })

  useEffect(() => {
    async function fetchSettings() {
      const user = await getAuthUser()
      if (!user) return
      const data = await fetchNotificationSettings(user.id)
      setSettings(data)
    }
    void fetchSettings()
  }, [])

  const updateSetting = async (key: keyof typeof settings, value: boolean) => {
    const newSettings = { ...settings, [key]: value }
    setSettings(newSettings)
    const user = await getAuthUser()
    if (!user) return
    try {
      await updateNotificationSetting(user.id, key, value)
      addToast('Success', 'Preferences updated', 'success')
    } catch (err: unknown) {
      console.error('Update settings error:', err instanceof Error ? err.message : 'unknown error')
    }
  }

  const handleAcceptConnection = async (notification: InboxNotification) => {
    setLoading(true)
    const { sender_id } = notification.metadata || {}
    if (!sender_id) return

    const user = await getAuthUser()
    if (!user) return

    try {
      await setConnectionAccepted(user.id, sender_id)

      // 2. Mark notification as read
      await markAsRead(notification.id)
      
      // 3. Send reciprocal notification to sender
      await createNotification({
        user_id: sender_id,
        type: 'connection_accepted',
        title: 'Connection Accepted',
        message: 'Your connection request was accepted. You can now chat real-time.',
        metadata: { acceptor_id: user.id },
      })

      addToast('Success', 'Connection established!', 'success')
    } catch (err: unknown) {
      addToast('Error', err instanceof Error ? err.message : 'Failed to accept connection', 'error')
    }
    setLoading(false)
  }

  const handleDeclineConnection = async (notification: InboxNotification) => {
    const senderId = notification.metadata?.sender_id
    if (senderId) {
      const user = await getAuthUser()
      if (user) {
        await deleteConnectionRecord(user.id, senderId)
      }
    }
    await markAsRead(notification.id)
    addToast('Success', 'Request ignored', 'info')
  }

  return (
    <div className="page-fade" style={{ maxWidth: '800px', margin: '0 auto', padding: '0 var(--p-safe) 4rem' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <div style={{ padding: '8px', background: 'var(--brand)', borderRadius: '10px', boxShadow: '0 4px 8px rgba(var(--brand-rgb), 0.15)' }}>
            <Bell size={20} color="white" />
          </div>
          <h1 className="fluid-h1" style={{ margin: 0, fontWeight: 900, fontSize: '1.5rem' }}>Inbox</h1>
        </div>
      </div>

      {/* Tab Switcher */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem', borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>
         <button 
           onClick={() => setView('inbox')}
           style={{ background: 'none', border: 'none', padding: '0.4rem 0.8rem', borderRadius: '6px', cursor: 'pointer', fontWeight: 800, fontSize: '0.85rem', color: view === 'inbox' ? 'var(--brand)' : 'var(--text-sub)', borderBottom: view === 'inbox' ? '2px solid var(--brand)' : 'none' }}
         >
           Inbox ({notifications.filter((n: Notification) => !n.read).length})
         </button>
         <button 
           onClick={() => setView('settings')}
           style={{ background: 'none', border: 'none', padding: '0.4rem 0.8rem', borderRadius: '6px', cursor: 'pointer', fontWeight: 800, fontSize: '0.85rem', color: view === 'settings' ? 'var(--brand)' : 'var(--text-sub)', borderBottom: view === 'settings' ? '2px solid var(--brand)' : 'none' }}
         >
           Settings
         </button>
      </div>

      {view === 'inbox' ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
          {notifications.length === 0 ? (
            <div style={{ 
              textAlign: 'center', padding: '5rem 2rem', background: 'var(--surface)', 
              borderRadius: '24px', border: '1px solid var(--border)', opacity: 0.8 
            }}>
              <Bell size={48} color="var(--text-sub)" style={{ opacity: 0.2, marginBottom: '1.5rem' }} />
              <h3 style={{ margin: 0, color: 'var(--text-main)', fontSize: '1.25rem' }}>Your inbox is clean</h3>
              <p style={{ color: 'var(--text-sub)', marginTop: '0.5rem' }}>New connection requests and project updates will appear here.</p>
            </div>
          ) : (
            <>
              <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '0.5rem' }}>
                 <button onClick={markAllAsRead} style={{ background: 'none', border: 'none', fontSize: '0.75rem', color: 'var(--brand)', cursor: 'pointer', fontWeight: 700 }}>Mark all as read</button>
              </div>
              {notifications.map((n: InboxNotification) => (
                <div 
                  key={n.id}
                  onClick={() => !n.read && markAsRead(n.id)}
                  style={{ 
                    padding: '0.6rem 0.75rem', borderRadius: '8px', border: '1px solid var(--border)', 
                    background: n.read ? 'var(--surface)' : 'rgba(var(--brand-rgb), 0.04)',
                    transition: 'all 0.2s ease',
                    position: 'relative',
                    display: 'flex',
                    gap: '0.75rem',
                    alignItems: 'center',
                    cursor: n.read ? 'default' : 'pointer'
                  }}
                >
                  {!n.read && <div style={{ position: 'absolute', top: '0.5rem', right: '0.5rem', width: '6px', height: '6px', borderRadius: '50%', background: 'var(--brand)' }} />}
                  
                  <div style={{ 
                    width: '32px', height: '32px', borderRadius: '8px', flexShrink: 0,
                    background: n.type === 'connection_request' ? 'rgba(var(--brand-rgb), 0.1)' : 'var(--bg-sub)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', color: n.type === 'connection_request' ? 'var(--brand)' : 'var(--text-sub)'
                  }}>
                    {n.type === 'connection_request' ? <UserPlus size={16} /> : n.type === 'message' ? <MessageSquare size={16} /> : <Mail size={16} />}
                  </div>

                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '1rem' }}>
                      <h4 style={{ margin: 0, fontSize: '0.85rem', fontWeight: 800, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{n.title}</h4>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <span style={{ fontSize: '0.65rem', color: 'var(--text-sub)', fontWeight: 600 }}>{DateTime.format(n.created_at, 'relative')}</span>
                        {n.type === 'connection_request' && !n.read && (
                          <div style={{ display: 'flex', gap: '0.35rem' }}>
                            <button 
                              onClick={(e) => { e.stopPropagation(); handleAcceptConnection(n); }}
                              disabled={loading}
                              style={{ padding: '0.25rem 0.5rem', borderRadius: '4px', background: 'var(--brand)', color: 'white', border: 'none', fontWeight: 800, cursor: 'pointer', fontSize: '0.7rem' }}
                            >
                              {loading ? '...' : 'Accept'}
                            </button>
                            <button 
                              onClick={(e) => { e.stopPropagation(); handleDeclineConnection(n); }}
                              style={{ padding: '0.25rem 0.5rem', borderRadius: '4px', background: 'var(--bg-sub)', color: 'var(--text-sub)', border: 'none', fontWeight: 800, cursor: 'pointer', fontSize: '0.7rem' }}
                            >
                              Ignore
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                    <p style={{ margin: 0, fontSize: '0.8rem', color: 'var(--text-sub)', lineHeight: 1.3, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{n.message}</p>
                  </div>
                </div>
              ))}
            </>
          )}
        </div>
      ) : (
        <div style={{ background: 'var(--surface)', borderRadius: '12px', border: '1px solid var(--border)', padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
           <h3 style={{ margin: 0, fontSize: '1rem', fontWeight: 900 }}>Alert Preferences</h3>
           
           {[
             { key: 'email_notifications', label: 'Email Alerts', desc: 'Receive project updates and connection requests via email.' },
             { key: 'push_notifications', label: 'Push Notifications', desc: 'Real-time browser notifications for chat and system signals.' },
             { key: 'marketing_emails', label: 'Academic Insights', desc: 'Periodic summaries of your project progress and network growth.' }
           ].map((item) => (
              <div key={item.key} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '1rem' }}>
                 <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 800, fontSize: '0.9rem', marginBottom: '0.15rem' }}>{item.label}</div>
                    <div style={{ fontSize: '0.8rem', color: 'var(--text-sub)', lineHeight: 1.3 }}>{item.desc}</div>
                 </div>
                <button 
                  onClick={() => updateSetting(item.key as keyof typeof settings, !settings[item.key as keyof typeof settings])}
                  style={{ 
                    width: '50px', height: '26px', borderRadius: '13px', border: 'none', position: 'relative', cursor: 'pointer',
                    background: settings[item.key as keyof typeof settings] ? 'var(--brand)' : 'var(--bg-sub)',
                    transition: 'background 0.3s ease'
                  }}
                >
                   <div style={{ 
                     position: 'absolute', top: '3px', left: settings[item.key as keyof typeof settings] ? '27px' : '3px',
                     width: '20px', height: '20px', borderRadius: '50%', background: 'white', boxShadow: '0 2px 4px rgba(0,0,0,0.2)', transition: 'left 0.3s ease' 
                   }} />
                </button>
             </div>
           ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useEffect, useState, useCallback, useMemo } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'
import { Suspense } from 'react'
import { createClient as createBrowserSupabaseClient } from '@/lib/supabase/client'
import type { User } from '@supabase/supabase-js'
import { ShieldCheck, AlertCircle, CheckCircle2, XCircle, ExternalLink } from 'lucide-react'

// ─── Scope metadata ───────────────────────────────────────────────────────────
const SCOPE_LABELS: Record<string, { label: string; description: string }> = {
  'profile:read':   { label: 'View your profile',       description: 'Read your name, avatar, and public profile info' },
  'tasks:read':     { label: 'Read your tasks',         description: 'View tasks assigned to or created by you' },
  'tasks:write':    { label: 'Manage your tasks',       description: 'Create, update, and complete tasks on your behalf' },
  'projects:read':  { label: 'View your projects',      description: 'Read your group project data and memberships' },
  'feed:read':      { label: 'Read your activity feed', description: 'Access your public posts and activity feed' },
}

interface ClientInfo {
  client_id: string
  client_name: string
  logo_url: string | null
  allowed_scopes: string[]
}

// ─── Inner component (needs useSearchParams) ──────────────────────────────────
function ConsentContent() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const db = useMemo(() => createBrowserSupabaseClient(), [])

  const clientId     = searchParams.get('client_id') ?? ''
  const redirectUri  = searchParams.get('redirect_uri') ?? ''
  const scopeParam   = searchParams.get('scope') ?? ''
  const state        = searchParams.get('state') ?? ''
  const responseType = searchParams.get('response_type') ?? ''

  const [user, setUser]           = useState<User | null>(null)
  const [authLoading, setAuthLoading] = useState(true)
  const [clientInfo, setClientInfo]   = useState<ClientInfo | null>(null)
  const [clientError, setClientError] = useState<string | null>(null)
  const [processing, setProcessing]   = useState(false)
  const [paramError, setParamError]   = useState<string | null>(null)

  // Validate required query params
  useEffect(() => {
    if (!clientId) return setParamError('Missing client_id parameter.')
    if (!redirectUri) return setParamError('Missing redirect_uri parameter.')
    if (responseType !== 'code') return setParamError('Only response_type=code is supported.')
    if (!scopeParam) return setParamError('Missing scope parameter.')
  }, [clientId, redirectUri, responseType, scopeParam])

  // Watch Supabase auth state
  useEffect(() => {
    const { data: { subscription } } = db.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null)
      setAuthLoading(false)
    })
    return () => subscription?.unsubscribe()
  }, [db.auth])

  // Redirect unauthenticated users to login
  useEffect(() => {
    if (!authLoading && !user && !paramError) {
      const returnTo = encodeURIComponent(`/oauth/consent?${searchParams.toString()}`)
      router.replace(`/login?redirect=${returnTo}`)
    }
  }, [authLoading, user, paramError, router, searchParams])

  // Fetch and validate the OAuth client
  useEffect(() => {
    if (paramError || !clientId || !redirectUri) return
    const params = new URLSearchParams({ client_id: clientId, redirect_uri: redirectUri })
    fetch(`/api/oauth/validate-client?${params}`)
      .then(res => res.json())
      .then((data) => {
        if (data.error) setClientError(data.error_description ?? data.error)
        else setClientInfo(data as ClientInfo)
      })
      .catch(() => setClientError('Failed to load application details. Please try again.'))
  }, [clientId, redirectUri, paramError])

  const requestedScopes = scopeParam.split(/[\s,]+/).filter(Boolean)

  const handleDecision = useCallback(async (approved: boolean) => {
    if (!user) return
    setProcessing(true)

    try {
      // Get current session to access token
      const { data: { session }, error: sessionError } = await db.auth.getSession()
      if (sessionError || !session?.access_token) {
        setClientError('Failed to get authentication token. Please try again.')
        setProcessing(false)
        return
      }

      const res = await fetch('/api/oauth/authorize', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify({ client_id: clientId, redirect_uri: redirectUri, scope: scopeParam, state, approved }),
      })
      const data = await res.json()
      if (data.redirect) {
        window.location.href = data.redirect
      } else {
        setClientError(data.error ?? 'Authorization failed. Please try again.')
        setProcessing(false)
      }
    } catch {
      setClientError('Network error. Please check your connection.')
      setProcessing(false)
    }
  }, [user, clientId, redirectUri, scopeParam, state, db.auth])

  // ── Error states ────────────────────────────────────────────────────────────
  if (paramError || clientError) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: 'var(--bg-main)', padding: '2rem' }}>
        <div style={{ maxWidth: '440px', width: '100%', background: 'var(--surface)', border: '1px solid rgba(239,68,68,0.3)', borderRadius: '20px', padding: '2rem', textAlign: 'center' }}>
          <AlertCircle size={40} color="var(--error)" style={{ marginBottom: '1rem' }} />
          <h2 style={{ color: 'var(--text-main)', fontWeight: 800, marginBottom: '0.5rem' }}>Authorization Error</h2>
          <p style={{ color: 'var(--text-sub)', fontSize: '0.9rem', lineHeight: 1.6 }}>{paramError ?? clientError}</p>
        </div>
      </div>
    )
  }

  // ── Loading ─────────────────────────────────────────────────────────────────
  if (authLoading || !clientInfo) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: 'var(--bg-main)' }}>
        <div style={{ width: 36, height: 36, borderRadius: '50%', border: '3px solid var(--brand)', borderTopColor: 'transparent', animation: 'spin 0.8s linear infinite' }} />
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    )
  }

  // ── Consent screen ──────────────────────────────────────────────────────────
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: 'var(--bg-main)', padding: '1.5rem' }}>
      <div style={{ maxWidth: '460px', width: '100%', background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: '24px', overflow: 'hidden', boxShadow: '0 24px 64px rgba(0,0,0,0.4)' }}>

        {/* Header */}
        <div style={{ padding: '2rem 2rem 1.5rem', borderBottom: '1px solid var(--border)', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem', textAlign: 'center' }}>
          {clientInfo.logo_url ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={clientInfo.logo_url}
              alt={`${clientInfo.client_name} logo`}
              width={56}
              height={56}
              style={{ borderRadius: '14px', border: '1px solid var(--border)', objectFit: 'contain' }}
            />
          ) : (
            <div style={{ width: 56, height: 56, borderRadius: '14px', background: 'rgba(16,185,129,0.12)', border: '1px solid rgba(16,185,129,0.3)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <ExternalLink size={24} color="var(--brand)" />
            </div>
          )}

          <div>
            <p style={{ color: 'var(--text-sub)', fontSize: '0.8rem', marginBottom: '0.35rem' }}>
              <strong style={{ color: 'var(--brand)' }}>{clientInfo.client_name}</strong> wants to access your Espeezy account
            </p>
            <p style={{ color: 'rgba(255,255,255,0.3)', fontSize: '0.72rem' }}>
              Signed in as <strong style={{ color: 'var(--text-sub)' }}>{user?.email}</strong>
            </p>
          </div>
        </div>

        {/* Scopes */}
        <div style={{ padding: '1.5rem 2rem' }}>
          <p style={{ color: 'var(--text-sub)', fontSize: '0.78rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '1rem' }}>
            This app will be able to:
          </p>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            {requestedScopes.map((scope) => {
              const meta = SCOPE_LABELS[scope]
              if (!meta) return null
              return (
                <li key={scope} style={{ display: 'flex', alignItems: 'flex-start', gap: '0.75rem' }}>
                  <CheckCircle2 size={18} color="var(--brand)" style={{ flexShrink: 0, marginTop: '1px' }} />
                  <div>
                    <div style={{ color: 'var(--text-main)', fontSize: '0.88rem', fontWeight: 700 }}>{meta.label}</div>
                    <div style={{ color: 'var(--text-sub)', fontSize: '0.78rem', marginTop: '1px' }}>{meta.description}</div>
                  </div>
                </li>
              )
            })}
          </ul>
        </div>

        {/* Security note */}
        <div style={{ margin: '0 2rem', padding: '0.875rem 1rem', background: 'rgba(16,185,129,0.05)', border: '1px solid rgba(16,185,129,0.15)', borderRadius: '10px', display: 'flex', gap: '0.6rem', alignItems: 'flex-start' }}>
          <ShieldCheck size={15} color="var(--brand)" style={{ flexShrink: 0, marginTop: '1px' }} />
          <p style={{ color: 'var(--text-sub)', fontSize: '0.75rem', margin: 0, lineHeight: 1.5 }}>
            Espeezy will not share your password. You can revoke this access anytime from your account settings.
          </p>
        </div>

        {/* Actions */}
        <div style={{ padding: '1.5rem 2rem 2rem', display: 'flex', gap: '0.75rem' }}>
          <button
            onClick={() => handleDecision(false)}
            disabled={processing}
            style={{
              flex: 1,
              height: '3rem',
              border: '1px solid var(--border)',
              borderRadius: '12px',
              background: 'transparent',
              color: 'var(--text-sub)',
              fontWeight: 700,
              fontSize: '0.9rem',
              cursor: processing ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '0.4rem',
              transition: 'border-color 0.15s, color 0.15s',
            }}
          >
            <XCircle size={16} />
            Deny
          </button>
          <button
            onClick={() => handleDecision(true)}
            disabled={processing}
            style={{
              flex: 2,
              height: '3rem',
              border: 'none',
              borderRadius: '12px',
              background: processing ? 'rgba(16,185,129,0.5)' : 'var(--brand)',
              color: '#000',
              fontWeight: 800,
              fontSize: '0.9rem',
              cursor: processing ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '0.4rem',
              transition: 'background 0.15s',
            }}
          >
            <ShieldCheck size={16} />
            {processing ? 'Authorizing…' : `Authorize ${clientInfo.client_name}`}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── Page ─────────────────────────────────────────────────────────────────────
export default function OAuthConsentPage() {
  return (
    <Suspense
      fallback={
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: 'var(--bg-main)' }}>
          <div style={{ width: 36, height: 36, borderRadius: '50%', border: '3px solid var(--brand)', borderTopColor: 'transparent', animation: 'spin 0.8s linear infinite' }} />
          <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
      }
    >
      <ConsentContent />
    </Suspense>
  )
}

import { getAuthUser, getUserProfile } from '@/utils/auth-server'
import Link from 'next/link'
import { redirect } from 'next/navigation'
import DashboardHome from '@/components/DashboardHome'
import WelcomeOnboarding from '@/components/WelcomeOnboarding'
import type { Profile } from '@/types/auth'

export const dynamic = 'force-dynamic'

export default async function DashboardPage() {
  const user = await getAuthUser()
  if (!user) redirect('/login')

  const profile: Profile | null = await getUserProfile(user.uid)

  if (!profile?.group_id) {
    return <WelcomeOnboarding profile={profile as Profile} />
  }

  return <DashboardHome groupId={profile.group_id} />
}

