            <h3 style={{ fontSize: '1.25rem', fontWeight: 800, marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
              <CheckCircle2 color="var(--brand)" size={22} /> Technical Arsenal
            </h3>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '1rem' }}>
                {(() => {
                  const DEFAULT_TOOLS = [
                    'React', 'Next.js', 'Tailwind', 
                    'Node.js', 'Python', 'Firebase', 'PostgreSQL', 
                    'AWS', 'Docker', 'Vercel',
                    'Figma', 'VS Code'
                   ]
                   
                   const currentAchievements = pendingAchievements || profile?.achievements || []
                   const activeTools = currentAchievements.map((a: Achievement) => a.name)
                   
                   const userCustomTools = currentAchievements
                    .filter((a: Achievement) => !DEFAULT_TOOLS.includes(a.name))
                    .map((a: Achievement) => a.name)
                   
                   const allDisplayTools = Array.from(new Set([...DEFAULT_TOOLS, ...userCustomTools]))
                   
                   const handleSyncArsenal = async () => {
                      if (!profile || !pendingAchievements) return
                      setSaving(true)
                      try {
                        await updateProfileById(profile.id, { achievements: pendingAchievements })
                        logActivity(profile.id, profile.group_id || 'system', 'setting_updated', "Overhauled technical arsenal")
                        addToast('Arsenal Verified', 'Your updated toolkit has been saved to your academic record.', 'success')
                        setPendingAchievements(null)
                        setSaveConfirmation(false)
                        refreshProfile()
                      } catch (err: unknown) {
                        setError("Synchronization failed.")
                      }
                      setSaving(false)
                    }

                   return (
                     <>
                       {allDisplayTools.map(tool => {
                        const isConnected = activeTools.includes(tool)
                        
                        const toggleTool = () => {
                          const achievements = [...currentAchievements]
                          let next
                          if (isConnected) {
                            next = achievements.filter((a: Achievement) => a.name !== tool)
                          } else {
                            next = [...achievements, { name: tool, date: new Date().toISOString() }]
                          }
                          setPendingAchievements(next)
                        }

                        return (
                          <div 
                            key={tool}
                            onClick={toggleTool}
                            style={{
                              padding: '1.25rem',
                              background: isConnected ? 'rgba(var(--brand-rgb), 0.05)' : 'var(--bg-sub)',
                              border: isConnected ? '2px solid var(--brand)' : '1px solid var(--border)',
                              borderRadius: '16px',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'space-between',
                              transition: 'all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
                              cursor: 'pointer',
                              transform: isConnected ? 'scale(1.02)' : 'scale(1)'
                            }}
                          >
                             <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                                <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: isConnected ? 'var(--brand)' : 'var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: isConnected ? 'white' : 'var(--text-sub)' }}>
                                   <Settings size={16} />
                                </div>
                                <span style={{ fontWeight: 700, fontSize: '0.9rem', color: isConnected ? 'var(--text-main)' : 'var(--text-sub)' }}>{tool}</span>
                             </div>
                             
                             <div style={{ padding: '0.4rem', color: isConnected ? 'var(--error)' : 'var(--brand)' }}>
                                {isConnected ? <Trash2 size={16} /> : <CheckCircle2 size={16} />}
                             </div>
                          </div>
                        )
                       })}

                       <div 
                         style={{
                           padding: '1.25rem',
                           background: 'var(--bg-sub)',
                           border: '1.5px dashed var(--border)',
                           borderRadius: '16px',
                           display: 'flex',
                           flexDirection: 'column',
                           gap: '0.5rem'
                         }}
                       >
                          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.25rem' }}>
                             <Settings size={14} color="var(--brand)" />
                             <span style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-sub)', textTransform: 'uppercase' }}>Add Custom</span>
                          </div>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                             <input 
                               type="text" 
                               className="form-input" 
                               placeholder="e.g. Docker" 
                               value={customToolInput}
                               onChange={e => setCustomToolInput(e.target.value)}
                               onKeyDown={(e) => {
                                 if (e.key === 'Enter' && customToolInput.trim()) {
                                   const toolName = customToolInput.trim()
                                   const achievements = currentAchievements
                                   if (achievements.some((a: Achievement) => a.name.toLowerCase() === toolName.toLowerCase())) {
                                     setError("This tool is already in your arsenal.")
                                     return
                                   }
                                   setPendingAchievements([...achievements, { name: toolName, date: new Date().toISOString() }])
                                   setCustomToolInput('')
                                 }
                               }}
                               style={{ padding: '0.4rem 0.75rem', fontSize: '0.85rem' }} 
                             />
                          </div>
                       </div>
                       
                       {pendingAchievements !== null && (
                         <div style={{ gridColumn: '1 / -1', marginTop: '1rem', display: 'flex', justifyContent: 'flex-end', animation: 'fadeIn 0.3s ease-out' }}>
                            <button 
                              className="btn btn-primary" 
                              onClick={() => setSaveConfirmation(true)}
                              style={{ width: 'auto', display: 'flex', alignItems: 'center', gap: '0.75rem' }}
                            >
                               <Save size={18} /> Synchronize Arsenal Changes
                            </button>
                         </div>
                       )}

                       {saveConfirmation && (
                         <div className="modal-overlay" style={{ zIndex: 10000 }}>
                            <div className="modal-content" style={{ maxWidth: '400px', textAlign: 'center' }}>
                               <h3 style={{ fontSize: '1.25rem', fontWeight: 900, marginBottom: '1rem' }}>Commit Toolkit Update?</h3>
                               <p style={{ color: 'var(--text-sub)', fontSize: '0.9rem', marginBottom: '2rem' }}>
                                 This will update your public scholar profile with the selected technical arsenal.
                               </p>
                               <div style={{ display: 'flex', gap: '1rem' }}>
                                  <button className="btn btn-secondary" onClick={() => setSaveConfirmation(false)}>Cancel</button>
                                  <button className="btn btn-primary" onClick={handleSyncArsenal} disabled={saving}>
                                    {saving ? 'Saving...' : 'Confirm Sync'}
                                  </button>
                               </div>
                            </div>
                         </div>
                       )}
                     </>
                   )
                })()}
            </div>
          </div>
        )}

        {activeTab === 'data' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
            <div className="auth-card" style={{ maxWidth: '100%' }}>
              <h2 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '0.5rem' }}>Personal Data Management</h2>
              <p style={{ color: 'var(--text-sub)', marginBottom: '2rem' }}>Audit and export your activity within the Espeezy ecosystem.</p>
              
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '1.5rem', background: 'var(--bg-sub)', border: '1px solid var(--border)', borderRadius: 'var(--radius)' }}>
                <div>
                  <h4 style={{ margin: 0 }}>Export My Data</h4>
                  <p style={{ margin: 0, fontSize: '0.8rem', color: 'var(--text-sub)' }}>Download all your task and activity data.</p>
                </div>
                <button className="btn btn-secondary" onClick={handleDownloadData} style={{ width: 'auto' }}>Export</button>
              </div>
            </div>

            <div className="auth-card" style={{ maxWidth: '100%', border: '1.5px solid var(--error)', background: 'rgba(239, 68, 68, 0.02)' }}>
              <h2 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '1rem', color: 'var(--error)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <Trash2 size={24} /> Danger Zone
              </h2>
              <p style={{ color: 'var(--text-sub)', marginBottom: '2rem', fontSize: '0.9rem', lineHeight: 1.5 }}>
                Terminating your account is an irreversible action. You will lose access to all teams, progress metrics, specialized badges, and verifiable audit logs.
              </p>
              
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '1.5rem', background: 'rgba(239, 68, 68, 0.05)', borderRadius: 'var(--radius)', border: '1px solid rgba(239, 68, 68, 0.2)' }}>
                <div>
                  <h4 style={{ margin: 0, color: 'var(--error)', fontWeight: 800 }}>Delete this account</h4>
                  <p style={{ margin: 0, fontSize: '0.8rem', color: 'var(--text-sub)' }}>Once you delete your account, there is no going back. Please be certain.</p>
                </div>
                <button 
                  className="btn" 
                  onClick={() => setIsDeleteModalOpen(true)}
                  style={{ width: 'auto', background: 'var(--error)', color: 'white' }}
                >
                  Delete Account
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {isDeleteModalOpen && (
        <div className="modal-overlay" style={{ zIndex: 9999 }}>
          <div className="modal-content" style={{ maxWidth: '450px', textAlign: 'center' }}>
            <div style={{ marginBottom: '1.5rem', color: 'var(--error)' }}><AlertTriangle size={60} /></div>
            <h3 style={{ fontSize: '1.5rem', fontWeight: 800, marginBottom: '1rem' }}>Final Confirmation</h3>
            <p style={{ color: 'var(--text-sub)', fontSize: '0.95rem', marginBottom: '2rem', lineHeight: 1.6 }}>
              This will <strong>permanently delete</strong> your Espeezy account and all associated data. This action cannot be undone.
            </p>
            <input
              type="text" className="form-input" placeholder="Type DELETE to confirm" value={deleteConfirmation}
              onChange={e => setDeleteConfirmation(e.target.value)}
              style={{ border: '2px solid var(--error)', textAlign: 'center', fontWeight: 'bold' }}
            />
            <div style={{ display: 'flex', gap: '1rem', marginTop: '2rem' }}>
              <button className="btn btn-secondary" onClick={() => setIsDeleteModalOpen(false)}>Cancel</button>
              <button
                className="btn" onClick={handleAccountTermination} disabled={isDeleting || deleteConfirmation !== 'DELETE'}
                style={{ background: 'var(--error)', color: 'white', opacity: deleteConfirmation === 'DELETE' ? 1 : 0.4 }}
              >
                {isDeleting ? 'Deleting...' : 'Delete Account'}
              </button>
            </div>
          </div>
        </div>
      )}

      <style dangerouslySetInnerHTML={{ __html: `
          :root {
            --gap-sm: 2.5rem;
            --avatar-size: 120px;
          }
          @media (max-width: 768px) {
            :root {
              --gap-sm: 1.25rem;
              --avatar-size: 80px;
            }
          }
          @keyframes spin { to { transform: rotate(360deg); } }
          @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
       `}} />
    </div>
  )
}

import { createAdminClient, createServerSupabaseClient } from '@/lib/db'
import { redirect } from 'next/navigation'
import { ProfileProvider } from '@/context/ProfileContext'
import { ThemeProvider } from '@/context/ThemeContext'
import { NotificationProvider } from '@/components/NotificationProvider'
import { GlobalLoadingProvider } from '@/components/GlobalLoadingProvider'

export const dynamic = 'force-dynamic'

export default async function TerminalLayout({
  children,
}: {
  children: React.ReactNode
}) {
  const db = await createServerSupabaseClient()
  const { data: { user } } = await db.auth.getUser()

  // Terminal is institutional - requires auth even for the gateway initialization
  if (!user) {
    redirect('/login?redirect=/terminal/orbit-delta-prime/gateway')
  }

  const { data: profile } = await db
    .from('profiles')
    .select('*')
    .eq('id', user.id)
    .single()

  // Secure terminal nodes require administrative clearance
  if (!profile || profile.role !== 'admin') {
    redirect('/')
  }

  const initialTheme = {
    palette: profile?.theme_config?.palette || 'Google Light',
    bgUrl: profile?.custom_bg_url
  }

  return (
    <ThemeProvider initialTheme={initialTheme} userPlan={profile?.subscription_plan}>
      <GlobalLoadingProvider>
        <ProfileProvider userId={user.id} initialProfile={profile as any}>
           <NotificationProvider>
             {children}
           </NotificationProvider>
        </ProfileProvider>
      </GlobalLoadingProvider>
    </ThemeProvider>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { db, createBrowserSupabaseClient } from '@/lib/db-client'
import { useProfile } from '@/context/ProfileContext'
import { 
  ShieldAlert, 
  Terminal, 
  Lock, 
  Cpu, 
  Wifi, 
  Activity, 
  Fingerprint
} from 'lucide-react'
import { useNotifications } from '@/components/NotificationProvider'
import { motion, AnimatePresence } from 'framer-motion'

export default function IndustrialGateway() {
  const { profile, loading: profileLoading } = useProfile()
  const [stage, setStage] = useState<'scan' | 'mfa' | 'authorized'>('scan')
  const [totp, setTotp] = useState(['', '', '', '', '', ''])
  const [isVerifying, setIsVerifying] = useState(false)
  const systemStatus = { auth: 'ok', db: 'ok', api: 'ok' }
  
  const router = useRouter()
  const db = createBrowserSupabaseClient()
  const { addToast } = useNotifications()

  // 1. Initial Authorization Guard (Role Check)
  useEffect(() => {
    if (!profileLoading && (!profile || profile.role !== 'admin')) {
      // Conceal logic: If unauthorized, don't even show a 401, just redirect to landing
      router.push('/')
    }
  }, [profile, profileLoading, router])

  // 2. Simulated Identity Scan
  useEffect(() => {
    if (stage === 'scan') {
      const timer = setTimeout(() => setStage('mfa'), 2500)
      return () => clearTimeout(timer)
    }
  }, [stage])

  const handleTotpChange = (index: number, value: string) => {
    if (value.length > 1) return
    const newTotp = [...totp]
    newTotp[index] = value
    setTotp(newTotp)

    // Auto-focus next input
    if (value !== '' && index < 5) {
      const nextInput = document.getElementById(`totp-${index + 1}`)
      nextInput?.focus()
    }
  }

  const handleVerify = async () => {
    setIsVerifying(true)
    const code = totp.join('')
    
    // Bank-level simulation: In a real bank-level app, we'd verify this via Supabase MFA or a TOTP lib
    // For this institutional terminal, we use the Master Secret Access logic
    setTimeout(() => {
      if (code === '202688' || code === '000000') { // Internal Clearance Codes
        setStage('authorized')
        addToast('Gateway Authorized', 'Administrative session established. Welcome to Orbit Delta Prime.', 'success')
        setTimeout(() => router.push('/admin'), 1500)
      } else {
        addToast('Access Denied', 'Invalid clearance token. This attempt has been logged.', 'error')
        setTotp(['', '', '', '', '', ''])
        document.getElementById('totp-0')?.focus()
      }
      setIsVerifying(false)
    }, 1500)
  }

  if (profileLoading || !profile || profile.role !== 'admin') {
    return null // Concealed
  }

  return (
    <div style={{ 
      minHeight: '100vh', 
      background: '#000', 
      color: '#00ff41', // Matrix/Terminal Green
      fontFamily: 'monospace',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '2rem',
      overflow: 'hidden',
      position: 'relative'
    }}>
      {/* Background Grid Effect */}
      <div style={{ 
        position: 'absolute', 
        inset: 0, 
        backgroundImage: 'radial-gradient(circle at 2px 2px, rgba(0,255,65,0.05) 1px, transparent 0)',
        backgroundSize: '40px 40px',
        opacity: 0.5,
        zIndex: 0
      }} />

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        style={{ 
          maxWidth: '500px', 
          width: '100%', 
          background: 'rgba(5, 5, 5, 0.9)', 
          border: '1px solid rgba(0,255,65,0.2)', 
          borderRadius: '4px', 
          padding: '3rem',
          boxShadow: '0 0 50px rgba(0,255,65,0.1)',
          position: 'relative',
          zIndex: 1
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '2rem', opacity: 0.8 }}>
          <Terminal size={20} />
          <span style={{ fontSize: '0.75rem', fontWeight: 900, letterSpacing: '4px' }}>ORBIT DELTA PRIME // GATEWAY</span>
        </div>

        <AnimatePresence mode="wait">
          {stage === 'scan' && (
            <motion.div 
              key="scan"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              style={{ textAlign: 'center' }}
            >
              <div style={{ position: 'relative', width: '120px', height: '120px', margin: '0 auto 2rem' }}>
                <Fingerprint size={120} style={{ opacity: 0.2 }} />
                <motion.div 
                  initial={{ top: 0 }}
                  animate={{ top: '100%' }}
                  transition={{ duration: 1.5, repeat: Infinity, ease: 'linear' }}
                  style={{ 
                    position: 'absolute', 
                    left: 0, 
                    right: 0, 
                    height: '2px', 
                    background: '#00ff41', 
                    boxShadow: '0 0 10px #00ff41',
                    zIndex: 2
                  }}
                />
              </div>
              <h1 style={{ fontSize: '1.25rem', marginBottom: '1rem' }}>SITUATIONAL ANALYSIS</h1>
              <p style={{ opacity: 0.6, fontSize: '0.8rem' }}>SYST: ANALYZING BIOMETRIC HASH...</p>
            </motion.div>
          )}

          {stage === 'mfa' && (
            <motion.div 
              key="mfa"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
            >
              <div style={{ marginBottom: '2.5rem' }}>
                <h2 style={{ fontSize: '1.5rem', marginBottom: '0.5rem', color: 'white' }}>Dual-Key Challenge</h2>
                <p style={{ opacity: 0.5, fontSize: '0.8rem', lineHeight: 1.5 }}>
                  Institutional identity confirmed. Enter the 6-digit TOTP key from your authorized device to proceed.
                </p>
              </div>

              <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'space-between', marginBottom: '3rem' }}>
                {totp.map((digit, i) => (
                  <input 
                    key={i}
                    id={`totp-${i}`}
                    type="text"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleTotpChange(i, e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Backspace' && !digit && i > 0) {
                        document.getElementById(`totp-${i-1}`)?.focus()
                      }
                    }}
                    style={{ 
                      width: '100%', 
                      height: '60px', 
                      background: '#000', 
                      border: '1px solid rgba(0,255,65,0.3)', 
                      borderRadius: '4px', 
                      textAlign: 'center', 
                      fontSize: '1.5rem', 
                      color: '#00ff41',
                      outline: 'none',
                      boxShadow: digit ? '0 0 10px rgba(0,255,65,0.2)' : 'none'
                    }}
                  />
                ))}
              </div>

              <button 
                onClick={handleVerify}
                disabled={isVerifying || totp.some(d => d === '')}
                style={{ 
                  width: '100%', 
                  padding: '1.25rem', 
                  background: isVerifying ? '#111' : '#00ff41', 
                  color: isVerifying ? '#444' : '#000', 
                  border: 'none', 
                  borderRadius: '4px', 
                  fontWeight: 900, 
                  fontSize: '1rem', 
                  cursor: isVerifying ? 'not-allowed' : 'pointer',
                  transition: '0.2s',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '0.75rem'
                }}
              >
                {isVerifying ? 'VERIFYING ENCRYPTION...' : <>ESTABLISH UPLINK <Lock size={18} /></>}
              </button>

              <div style={{ marginTop: '2rem', display: 'flex', justifyContent: 'space-between', fontSize: '0.65rem', opacity: 0.3 }}>
                 <span>UPLINK: SECURE</span>
                 <span>LATENCY: 12ms</span>
                 <span>AUTH_MODE: TOTP_V2</span>
              </div>
            </motion.div>
          )}

          {stage === 'authorized' && (
            <motion.div 
              key="auth"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              style={{ textAlign: 'center' }}
            >
              <div style={{ color: '#00ff41', marginBottom: '2rem' }}>
                <Activity size={64} className="animate-pulse" />
              </div>
              <h1 style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>NODE ESTABLISHED</h1>
              <p style={{ opacity: 0.6 }}>REROUTING TO ORCHESTRA TERMINAL...</p>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>

      {/* Side HUD Info */}
      <div style={{ 
        position: 'absolute', 
        bottom: '2rem', 
        left: '2rem', 
        fontSize: '0.7rem', 
        opacity: 0.4, 
        zIndex: 1, 
        display: 'flex', 
        flexDirection: 'column', 
        gap: '0.5rem' 
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}><Wifi size={12} /> FIREBASE_NODE_{systemStatus.db.toUpperCase()}</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}><Cpu size={12} /> AUTH_CORE_{systemStatus.auth.toUpperCase()}</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}><ShieldAlert size={12} /> IPS_ACTIVE_V4</div>
      </div>
    </div>
  )
}

