          .mobile-hide { display: none !important; }
        }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { AlertCircle, X, Shield, Activity, Globe } from 'lucide-react'
import { db, createBrowserSupabaseClient } from '@/lib/db-client'

interface AnnouncementConfig {
  id: string
  config_key: string
  config_value: {
    title: string
    message: string
    style: 'elite' | 'alert'
  }
  is_active: boolean
}

export default function GlobalAnnouncement() {
  const [config, setConfig] = useState<AnnouncementConfig | null>(null)
  const [isVisible, setIsVisible] = useState(true)
  // Use a ref to prevent React StrictMode double-subscription errors:
  // StrictMode mounts→unmounts→mounts in dev; the cleanup removes the channel
  // before the second mount, so using a unique channel name per effect avoids
  // "cannot add postgres_changes callbacks after subscribe()" errors.
  const mountIdRef = useRef(0)
  const [isClient, setIsClient] = useState(false)

  useEffect(() => {
    mountIdRef.current += 1
    const mountId = mountIdRef.current

    const db = createBrowserSupabaseClient()

    // 1. Initial Fetch
    const fetchConfig = async () => {
      const { data } = await db
        .from('platform_config')
        .select('*')
        .eq('config_key', 'global_announcement')
        .single()
      
      if (data) setConfig(data as AnnouncementConfig)
    }
    fetchConfig()

    setIsClient(true)
  }, [])

  if (!isClient || !isVisible || !config?.is_active) return null

  const { title, message, style } = config.config_value || { title: 'Institutional Update', message: '', style: 'elite' }

  return (
    <AnimatePresence>
      <motion.div 
        initial={{ opacity: 0, y: 50, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, scale: 0.9 }}
        style={{
          position: 'fixed',
          bottom: '2rem',
          right: '2rem',
          zIndex: 100000,
          maxWidth: '400px',
          width: 'calc(100% - 4rem)',
          background: 'rgba(10, 10, 10, 0.8)',
          backdropFilter: 'blur(32px)',
          borderRadius: '24px',
          border: '1px solid rgba(255,255,255,0.1)',
          padding: '1.5rem',
          boxShadow: '0 30px 60px rgba(0,0,0,0.5)',
          overflow: 'hidden'
        }}
      >
        {/* Elite Ambient Glow */}
        <div style={{ 
          position: 'absolute', 
          top: '-50%', 
          right: '-50%', 
          width: '100%', 
          height: '100%', 
          background: style === 'elite' ? 'radial-gradient(circle, rgba(16, 185, 129, 0.1) 0%, transparent 70%)' : 'radial-gradient(circle, rgba(236, 72, 153, 0.1) 0%, transparent 70%)',
          pointerEvents: 'none' 
        }} />

        <div style={{ display: 'flex', gap: '1rem', position: 'relative', zIndex: 1 }}>
          <div style={{ 
            width: '48px', 
            height: '48px', 
            borderRadius: '14px', 
            background: style === 'elite' ? 'rgba(16, 185, 129, 0.1)' : 'rgba(236, 72, 153, 0.1)', 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center', 
            color: style === 'elite' ? '#10b981' : '#ec4899',
            flexShrink: 0
          }}>
            {style === 'elite' ? <Shield size={24} /> : <AlertCircle size={24} />}
          </div>

          <div style={{ flex: 1 }}>
            <h4 style={{ margin: '0 0 0.25rem 0', fontSize: '1.1rem', fontWeight: 950, color: 'white', letterSpacing: '-0.02em' }}>{title}</h4>
            <p style={{ margin: 0, fontSize: '0.85rem', color: 'rgba(255,255,255,0.6)', lineHeight: 1.5 }}>{message}</p>
          </div>

          <button 
            onClick={() => setIsVisible(false)}
            style={{ 
              background: 'rgba(255,255,255,0.05)', 
              border: 'none', 
              width: '28px', 
              height: '28px', 
              borderRadius: '8px', 
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'rgba(255,255,255,0.3)',
              transition: '0.2s'
            }}
          >
            <X size={16} />
          </button>
        </div>

        <div style={{ marginTop: '1.25rem', display: 'flex', alignItems: 'center', gap: '1rem', fontSize: '0.65rem', fontWeight: 900, textTransform: 'uppercase', letterSpacing: '1px', opacity: 0.3 }}>
           <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}><Activity size={10} /> ORCHESTRA_UPLINK</div>
           <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}><Globe size={10} /> BROADCAST_LIVE</div>
        </div>

        <style jsx>{`
          div:hover button { color: white; opacity: 1; }
        `}</style>
      </motion.div>
    </AnimatePresence>
  )
}

'use client'

import React, { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react'
import { Check, X, Info, AlertTriangle, Loader2, ShieldCheck, Lock, WifiOff } from 'lucide-react'
import { useConnectivity } from '@/context/ConnectivityContext'

interface LoadingState {
  isLoading: boolean
  progress: number
  message: string
}

interface ConfirmationState {
  isOpen: boolean
  title: string
  message: string
  onConfirm: () => void
  onCancel?: () => void
  type: 'success' | 'info' | 'warning'
}

interface GlobalLoadingContextType {
  startLoading: (message: string) => void
  finishLoading: () => void
  showConfirmation: (config: Omit<ConfirmationState, 'isOpen'>) => void
  withLoading: <T>(task: () => Promise<T>, message: string) => Promise<T>
}

const GlobalLoadingContext = createContext<GlobalLoadingContextType | undefined>(undefined)

export const useSmartLoading = () => {
  const context = useContext(GlobalLoadingContext)
  if (!context) throw new Error('useSmartLoading must be used within GlobalLoadingProvider')
  return context
}

export function GlobalLoadingProvider({ children }: { children: React.ReactNode }) {
  const [loading, setLoading] = useState<LoadingState>({ isLoading: false, progress: 0, message: '' })
  const [confirm, setConfirm] = useState<ConfirmationState>({ 
    isOpen: false, title: '', message: '', type: 'info', onConfirm: () => {} 
  })
  
  const { isOnline, isSlow } = useConnectivity()
  const progressInterval = useRef<NodeJS.Timeout | null>(null)
  const appearanceTimeout = useRef<NodeJS.Timeout | null>(null)

  const startLoading = useCallback((message: string) => {
    // Clear any existing timeouts or intervals
    if (appearanceTimeout.current) clearTimeout(appearanceTimeout.current)
    if (progressInterval.current) clearInterval(progressInterval.current)

    // Wait 250ms before showing the loader to prevent flashes for fast tasks
    appearanceTimeout.current = setTimeout(() => {
      setLoading({ isLoading: true, progress: 0, message })

      progressInterval.current = setInterval(() => {
        setLoading(prev => {
          if (!prev.isLoading) return prev
          
          let next = prev.progress
          if (next < 40) next += Math.random() * 15 // Rapid start
          else if (next < 85) next += Math.random() * 2 // Steady crawl
          else if (next < 98) next += 0.1 // Precision hold
          
          return { ...prev, progress: Math.min(next, 98) }
        })
      }, 150)
    }, 250)
  }, [])

  const finishLoading = useCallback(() => {
    if (appearanceTimeout.current) clearTimeout(appearanceTimeout.current)
    if (progressInterval.current) clearInterval(progressInterval.current)
    
    // Snap to 100% and close
    setLoading(prev => {
      if (!prev.isLoading) return { isLoading: false, progress: 0, message: '' }
      return { ...prev, progress: 100 }
    })

    // Reduce delay for a more responsive exit
    setTimeout(() => {
      setLoading({ isLoading: false, progress: 0, message: '' })
    }, 200)
  }, [])

  const withLoading = useCallback(async <T,>(task: () => Promise<T>, message: string): Promise<T> => {
    startLoading(message)
    try {
      const result = await task()
      return result
    } finally {
      finishLoading()
    }
  }, [startLoading, finishLoading])

  const showConfirmation = useCallback((config: Omit<ConfirmationState, 'isOpen'>) => {
    setConfirm({ ...config, isOpen: true })
  }, [])

  return (
    <GlobalLoadingContext.Provider value={{ startLoading, finishLoading, showConfirmation, withLoading }}>
      {children}
      
      {/* Smart Central Loader Overlay */}
      {loading.isLoading && (
        <div style={{ 
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
          zIndex: 99999, display: 'flex', alignItems: 'center', justifyContent: 'center',
          background: 'rgba(var(--bg-rgb), 0.7)', backdropFilter: 'blur(20px)',
          animation: 'fadeIn 0.3s ease-out'
        }}>
          <div style={{ textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '2rem' }}>
            <div style={{ position: 'relative', width: '120px', height: '120px' }} className="vault-sync-hex">
              {/* Vault Shield Metaphor */}
              <div style={{ 
                position: 'absolute', inset: 0, borderRadius: '24px', 
                border: '4px solid var(--border)', borderTopColor: 'var(--brand)',
                transform: 'rotate(45deg)',
                animation: 'spin 2s cubic-bezier(0.68, -0.55, 0.265, 1.55) infinite'
              }} />
              {/* Progress Text */}
              <div style={{ 
                position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: '1.75rem', fontWeight: 950, color: 'var(--text-main)', letterSpacing: '-0.05em'
              }}>
                {Math.round(loading.progress)}%
              </div>
            </div>
            <div>
              <div style={{ fontSize: '1.2rem', fontWeight: 950, color: 'var(--text-main)', marginBottom: '0.4rem', letterSpacing: '-0.04em', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}>
                <Lock size={18} className="text-brand" />
                {loading.message}
              </div>
              <div style={{ fontSize: '0.7rem', fontWeight: 800, color: 'var(--brand)', textTransform: 'uppercase', letterSpacing: '0.2em' }}>
                {isSlow ? 'Low Bandwidth Optimization Active' : 'Establishing Encrypted Node...'}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Offline Barrier */}
      {!isOnline && (
        <div style={{ 
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
          zIndex: 100000, display: 'flex', alignItems: 'center', justifyContent: 'center',
          background: 'rgba(0,0,0,0.85)', backdropFilter: 'blur(60px)',
          animation: 'fadeIn 0.5s ease-out', padding: '2rem'
        }}>
          <div style={{ textAlign: 'center', maxWidth: '400px' }}>
            <div style={{ width: '80px', height: '80px', background: 'rgba(239, 68, 68, 0.1)', borderRadius: '30px', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 2rem', color: 'var(--error)' }}>
              <WifiOff size={40} />
            </div>
            <h2 style={{ fontSize: '2rem', fontWeight: 950, color: 'white', marginBottom: '1rem', letterSpacing: '-0.04em' }}>Vault Locked</h2>
            <p style={{ color: 'rgba(255,255,255,0.6)', fontWeight: 600, marginBottom: '2rem', lineHeight: 1.6 }}>Your connection has been interrupted. Access is paused to ensure data integrity.</p>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', color: 'var(--brand)', fontWeight: 800, fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
              <span className="pulse-pill" style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'currentColor' }} />
              Monitoring Recovery...
            </div>
          </div>
        </div>
      )}

      {/* Global Feedback Popup */}
      {confirm.isOpen && (
        <div style={{ 
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
          zIndex: 99999, display: 'flex', alignItems: 'center', justifyContent: 'center',
          background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)',
          padding: '2rem', animation: 'fadeIn 0.2s ease-out'
        }}>
          <div style={{ 
            background: 'var(--surface)', borderRadius: '28px', border: '1px solid var(--border)', 
            padding: '2.5rem', maxWidth: '440px', width: '100%', textAlign: 'center',
            boxShadow: 'var(--shadow-xl)', animation: 'slideUp 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
          }}>
            <div style={{ 
              width: '64px', height: '64px', borderRadius: '22px', margin: '0 auto 1.5rem',
              background: confirm.type === 'success' ? 'rgba(30, 142, 62, 0.1)' : 'rgba(var(--brand-rgb), 0.1)',
              color: confirm.type === 'success' ? 'var(--success)' : 'var(--brand)',
              display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}>
              {confirm.type === 'success' ? <Check size={32} /> : <Info size={32} />}
            </div>
            <h3 style={{ fontSize: '1.5rem', fontWeight: 950, marginBottom: '0.75rem', letterSpacing: '-0.03em' }}>{confirm.title}</h3>
            <p style={{ color: 'var(--text-sub)', marginBottom: '2rem', lineHeight: 1.5, fontWeight: 600 }}>{confirm.message}</p>
            <div style={{ display: 'flex', gap: '1rem' }}>
              {confirm.onCancel && (
                <button 
                  onClick={() => { setConfirm(prev => ({ ...prev, isOpen: false })); confirm.onCancel?.(); }}
                  className="btn btn-secondary" style={{ flex: 1 }}
                >Cancel</button>
              )}
              <button 
                onClick={() => { setConfirm(prev => ({ ...prev, isOpen: false })); confirm.onConfirm(); }}
                className="btn btn-primary" style={{ flex: 1 }}
              >OK</button>
            </div>
          </div>
        </div>
      )}

      <style jsx>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { opacity: 0; transform: translateY(40px) scale(0.95); } to { opacity: 1; transform: translateY(0) scale(1); } }
      `}</style>
    </GlobalLoadingContext.Provider>
  )
}

'use client'
import Image from 'next/image'

import React, { useState, useEffect, useRef } from 'react'
import { Search, User, CheckSquare, Users, X, ArrowRight, Loader2 } from 'lucide-react'
import { createBrowserSupabaseClient } from '@/lib/db-client'
import { useRouter } from 'next/navigation'
import { useSmartLoading } from '@/components/GlobalLoadingProvider'
import { getFlagComponent } from '@/utils/geo'

interface SearchResult {
  id: string
  type: 'profile' | 'task' | 'group'
  title: string
  subtitle: string
  image_url?: string
  country_code?: string
}

interface ProfileSearchRow {
  id: string
  full_name: string | null
  avatar_url: string | null
  course_name: string | null
  country_code: string | null
}

interface TaskSearchRow {
  id: string
  title: string
  status: string
}

interface GroupSearchRow {
  id: string
  name: string
  module_code: string
}

interface GlobalSearchProps {
  collapsed?: boolean
}

export default function GlobalSearch({ collapsed }: GlobalSearchProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<SearchResult[]>([])
  const [loading, setLoading] = useState(false)
  const searchRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const db = createBrowserSupabaseClient()
  const router = useRouter()
  const { withLoading } = useSmartLoading()

  // Shortcut Listener (CMD+K / CTRL+K)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setIsOpen(true)
      }
      if (e.key === 'Escape') {
        setIsOpen(false)
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [])

  useEffect(() => {
    if (isOpen) {
      inputRef.current?.focus()
    }
  }, [isOpen])

  // Smart Search Logic
  useEffect(() => {
    if (query.length < 2) {
      queueMicrotask(() => {
        setResults([])
        setLoading(false)
      })
      return
    }

    const performSearch = async () => {
      setLoading(true)
      try {
        // Try calling the smart_search RPC function
        const { data, error } = await db.rpc('smart_search', { search_term: query })

        if (!error && data) {
          setResults(data)
        } else {
          // Fallback to manual queries if RPC fails (e.g. migration not applied)
          const [profiles, tasks, groups] = await Promise.all([
            db.from('profiles').select('id, full_name, avatar_url, course_name, country_code').ilike('full_name', `%${query}%`).limit(3),
            db.from('tasks').select('id, title, status').ilike('title', `%${query}%`).limit(3),
            db.from('groups').select('id, name, module_code').ilike('name', `%${query}%`).limit(3)
          ])

          const profileRows = (profiles.data || []) as ProfileSearchRow[]
          const taskRows = (tasks.data || []) as TaskSearchRow[]
          const groupRows = (groups.data || []) as GroupSearchRow[]

          const combined: SearchResult[] = [
            ...profileRows.map(p => ({
              id: p.id,
              type: 'profile' as const, 
              title: p.full_name || 'Unknown',
              subtitle: p.course_name || 'No course',
              image_url: p.avatar_url || undefined,
              country_code: p.country_code || undefined
            })),
            ...taskRows.map(t => ({ id: t.id, type: 'task' as const, title: t.title, subtitle: t.status })),
            ...groupRows.map(g => ({ id: g.id, type: 'group' as const, title: g.name, subtitle: g.module_code }))
          ]
          setResults(combined)
        }
      } catch (err) {
        console.error('Search error:', err)
      } finally {
        setLoading(false)
      }
    }

    const timer = setTimeout(performSearch, 300)
    return () => clearTimeout(timer)
  }, [query, db])

  const handleSelect = (result: SearchResult) => {
    setIsOpen(false)
    setQuery('')
    
    let path = '/'
    let label = 'Navigating...'

    if (result.type === 'profile') {
      path = `/network/profile/${result.id}`
      label = `Opening ${result.title}...`
    } else if (result.type === 'task') {
      path = `/?taskId=${result.id}`
      label = `Opening Task: ${result.title}...`
    } else if (result.type === 'group') {
      path = `/network` 
      label = `Finding Team: ${result.title}...`
    }

    withLoading(async () => {
      router.push(path)
    }, label)
  }

  if (!isOpen) {
    return (
      <button 
        onClick={() => setIsOpen(true)}
        style={{
          width: '100%', 
          padding: collapsed ? '0.75rem' : '0.75rem 1rem', 
          borderRadius: '14px', 
          background: 'var(--bg-main)',
          border: '1px solid var(--border)', 
          display: 'flex', 
          alignItems: 'center', 
          gap: collapsed ? '0' : '0.75rem',
          justifyContent: collapsed ? 'center' : 'flex-start',
          color: 'var(--text-sub)', 
          cursor: 'pointer', 
          transition: 'all 0.2s', 
          marginBottom: '1rem',
          minHeight: '44px'
        }}
        title="Search workspace (âŒ˜K)"
        className="search-trigger"
      >
        <Search size={18} />
        {!collapsed && (
          <>
            <span style={{ fontSize: '0.85rem', flex: 1, textAlign: 'left' }}>Search workspace...</span>
            <span style={{ fontSize: '0.7rem', opacity: 0.5, border: '1px solid var(--border)', padding: '2px 6px', borderRadius: '6px' }}>âŒ˜K</span>
          </>
        )}
      </button>
    )
  }

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 9999, display: 'flex', alignItems: 'flex-start', justifyContent: 'center', paddingTop: '10vh', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)' }} onClick={() => setIsOpen(false)}>
      <div 
        ref={searchRef}
        onClick={(e) => e.stopPropagation()}
        style={{ 
          width: '90%', maxWidth: '600px', background: 'var(--surface)', borderRadius: '24px', 
          border: '1px solid var(--border)', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.5)', 
          overflow: 'hidden', animation: 'searchSlideIn 0.3s cubic-bezier(0.4, 0, 0.2, 1)' 
        }}
      >
        {/* Input Header */}
        <div style={{ padding: '1.25rem', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: '1rem' }}>
          {loading ? <Loader2 size={24} className="spin" color="var(--brand)" /> : <Search size={24} color="var(--brand)" />}
          <input 
            ref={inputRef}
            type="text" 
            placeholder="Search students, tasks, or teams..." 
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            style={{ flex: 1, background: 'none', border: 'none', color: 'var(--text-main)', fontSize: '1.25rem', fontWeight: 600, outline: 'none' }}
          />
          <button onClick={() => setIsOpen(false)} style={{ background: 'none', border: 'none', color: 'var(--text-sub)', cursor: 'pointer' }}><X size={20} /></button>
        </div>

        {/* Results Area */}
        <div style={{ maxHeight: '60vh', overflowY: 'auto', padding: '0.75rem' }}>
          {query.length < 2 ? (
            <div style={{ padding: '3rem 2rem', textAlign: 'center', color: 'var(--text-sub)' }}>
               <Search size={40} style={{ opacity: 0.1, marginBottom: '1rem' }} />
               <p style={{ margin: 0 }}>Find students, tasks, or teams across the network.</p>
               <div style={{ marginTop: '1.5rem', display: 'flex', justifyContent: 'center', gap: '1rem' }}>
                  <div className="search-pill">âŒ˜K to search</div>
                  <div className="search-pill">ESC to close</div>
               </div>
            </div>
          ) : results.length === 0 && !loading ? (
            <div style={{ padding: '3rem 2rem', textAlign: 'center' }}>
              <p style={{ color: 'var(--text-sub)' }}>No exact matches for &quot;<span style={{ color: 'var(--text-main)' }}>{query}</span>&quot;</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
               {results.map((r, i) => (
                 <div 
                   key={`${r.type}-${r.id}`}
                   onClick={() => handleSelect(r)}
                   style={{ 
                     display: 'flex', alignItems: 'center', gap: '1.25rem', padding: '1rem', 
                     borderRadius: '16px', cursor: 'pointer', transition: 'all 0.2s' 
                   }}
                   className="search-item"
                 >
                   <div style={{ width: '42px', height: '42px', borderRadius: '12px', background: 'var(--bg-sub)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      {r.type === 'profile' && (
                        r.image_url ? (
                          <Image src={r.image_url} alt={r.title || 'result'} width={40} height={40} style={{ width: '100%', height: '100%', borderRadius: '12px', objectFit: 'cover' }} />
                        ) : (
                          <User size={20} color="var(--brand)" />
                        )
                      )}
                      {r.type === 'task' && <CheckSquare size={20} color="#10b981" />}
                      {r.type === 'group' && <Users size={20} color="#8b5cf6" />}
                   </div>
                   <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 800, color: 'var(--text-main)', fontSize: '1rem' }}>{r.title}</div>
                      <div style={{ color: 'var(--text-sub)', fontSize: '0.8rem', textTransform: 'capitalize' }}>
                        {r.type === 'profile' ? 'Teammate' : r.type === 'group' ? 'Group' : 'Task'} â€¢ {r.subtitle}
                      </div>
                   </div>
                   <ArrowRight size={16} color="var(--text-sub)" className="search-arrow" />
                 </div>
               ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div style={{ padding: '0.75rem 1.25rem', borderTop: '1px solid var(--border)', backgroundColor: 'var(--bg-sub)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.75rem', color: 'var(--text-sub)' }}>
          <div style={{ display: 'flex', gap: '1rem' }}>
             <span><strong>ENTER</strong> to select</span>
             <span><strong>â†‘â†“</strong> to navigate</span>
          </div>
          <div>Smart Search v1.0</div>
        </div>

        <style jsx>{`
          .search-item:hover { background: rgba(var(--brand-rgb), 0.08); }
          .search-item:hover .search-arrow { transform: translateX(4px); color: var(--brand); }
          .search-pill { font-size: 0.7rem; font-weight: 800; background: var(--bg-sub); padding: 4px 10px; borderRadius: 20px; border: 1px solid var(--border); }
          @keyframes searchSlideIn { from { transform: translateY(-30px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
          .spin { animation: spin 1s linear infinite; }
          @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        `}</style>
      </div>
    </div>
  )
}

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { useConnectivity } from '@/context/ConnectivityContext';
import { Task, TaskStatus, Profile } from '@/types/database';
import { KanbanBoardProps } from '@/types/ui';
import TaskModal from './TaskModal';
import TeamChat from './TeamChat';
import KanbanOnboardingModal from './KanbanOnboardingModal';
import { AlertCircle, RefreshCw, CloudOff, Plus } from 'lucide-react';
import { fetchGroupMembers, createTask as createTaskApi } from '@/services/dashboard';
import { handleTaskStatusUpdate } from '@/app/actions';
import { db } from '@/lib/db-client';

const COLUMNS: TaskStatus[] = ['To Do', 'In Progress', 'In Review', 'Done'];



export default function KanbanBoard({ groupId, profile, newTaskSignal }: KanbanBoardProps) {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [groupMembers, setGroupMembers] = useState<Profile[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isOnboardingOpen, setIsOnboardingOpen] = useState(false);
  const [activeColumn, setActiveColumn] = useState<TaskStatus | undefined>();
  const isOnline = useConnectivity();

  // Fetch tasks and members

  // Contextual Help Button
  const openKanbanHelp = () => {
    setIsOnboardingOpen(true);
  };

  // Handle "New Task" signal from DashboardHome
  const lastSignalRef = useRef(newTaskSignal);
  useEffect(() => {
    if (newTaskSignal !== undefined && newTaskSignal > (lastSignalRef.current || 0)) {
      setSelectedTask(null);
      setActiveColumn('To Do');
      setIsModalOpen(true);
    }
    lastSignalRef.current = newTaskSignal;
  }, [newTaskSignal]);

  useEffect(() => {
    setLoading(true);
    fetchGroupMembers(groupId).then(setGroupMembers).catch(console.error);

    // REALTIME TASK LOOP & PRESENCE
    const channel = db.channel(`kanban-tasks-${groupId}`)
      .on(
        'postgres_changes',
        { 
          event: '*', 
          schema: 'public', 
          table: 'tasks', 
          filter: `group_id=eq.${groupId}` 
        },
        (payload) => {
          console.log('Realtime task update:', payload);
          if (payload.eventType === 'INSERT') {
            setTasks(prev => [...prev, payload.new as Task]);
          } else if (payload.eventType === 'UPDATE') {
            setTasks(prev => prev.map(t => t.id === payload.new.id ? payload.new as Task : t));
          } else if (payload.eventType === 'DELETE' && payload.old) {
            const oldId = (payload.old as { id: string }).id;
            setTasks(prev => prev.filter(t => t.id === oldId));
          }
        }
      )
      .on('presence', { event: 'sync' }, () => {
        const state = channel.presenceState();
        console.log('Presence state synced:', state);
        // We can use this to update online status in parent or local state
        window.dispatchEvent(new CustomEvent('presence-sync', { detail: state }));
      })
      .on('presence', { event: 'join' }, ({ newPresences }) => {
        console.log('Joined:', newPresences);
      })
      .on('presence', { event: 'leave' }, ({ leftPresences }) => {
        console.log('Left:', leftPresences);
      })
      .subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          setLoading(false);
          await channel.track({
            user_id: profile.id,
            online_at: new Date().toISOString(),
          });
        }
      });

    // Initial fetch
    db.from('tasks').select('*').eq('group_id', groupId).then(({ data }) => {
      if (data) setTasks(data as Task[]);
    });

    return () => {
      db.removeChannel(channel);
    };
  }, [groupId]);

  useEffect(() => {
    const handler = () => setIsOnboardingOpen(true);
    window.addEventListener('open-kanban-onboarding', handler);
    return () => window.removeEventListener('open-kanban-onboarding', handler);
  }, []);

  // CRUD
  const createTask = async (task: Partial<Task>) => {
    setLoading(true);
    setError(null);
    try {
      const newTask = await createTaskApi(task);
      setTasks(prev => [...prev, newTask]);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to create task.');
    } finally {
      setLoading(false);
    }
  };

  const updateTaskStatus = async (taskId: string, newStatus: TaskStatus) => {
    // Optimistic UI update
    const oldTasks = [...tasks];
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: newStatus } : t));
    
    try {
      await handleTaskStatusUpdate(taskId, newStatus, groupId, profile.id);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to update task.');
      setTasks(oldTasks); // Rollback
    }
  };

  // Accessibility: ARIA roles, keyboard nav, error/empty/loading states
  if (loading) {
    return (
      <div role="status" aria-busy="true" style={{ padding: '2rem', textAlign: 'center' }}>
        <RefreshCw className="animate-spin" style={{ margin: '0 auto', color: '#10b981' }} />
        <div>Loading board…</div>
      </div>
    );
  }
  if (error) {
    return (
      <div role="alert" style={{ color: '#ef4444', padding: '2rem', textAlign: 'center' }}>
        <AlertCircle style={{ marginBottom: 8 }} />
        {error}
        <button onClick={() => window.location.reload()} style={{ marginLeft: 16, background: '#10b981', color: 'white', border: 'none', borderRadius: 8, padding: '0.5rem 1rem', cursor: 'pointer' }}>Retry</button>
      </div>
    );
  }


  // Main Kanban UI (simplified, modularize as needed)
  return (
    <div style={{ position: 'relative' }}>
      {/* Contextual Help Button */}
      <button
        aria-label="How to use Kanban Board"
        title="How to use Kanban Board"
        onClick={openKanbanHelp}
        style={{
          position: 'absolute',
          top: 8,
          right: 8,
          zIndex: 20,
          background: 'rgba(59,130,246,0.09)',
          border: '1px solid rgba(59,130,246,0.18)',
          borderRadius: 12,
          padding: '0.5rem 0.8rem',
          color: '#2563eb',
          fontWeight: 900,
          fontSize: '1rem',
          boxShadow: 'var(--shadow-xs)',
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem',
          cursor: 'pointer'
        }}
      >
        <svg width="18" height="18" fill="none" stroke="#2563eb" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 1 1 5.83 1c0 2-3 3-3 3"/><path d="M12 17h.01"/></svg>
        <span style={{ fontWeight: 700, fontSize: '0.97rem' }}>How to use Kanban</span>
      </button>
      <div role="region" aria-label="Kanban Board" style={{ display: 'flex', gap: 24, padding: 24, overflowX: 'auto' }}>
      {COLUMNS.map(col => (
        <div key={col} role="list" aria-label={col} style={{ minWidth: 300, flex: 1, background: 'rgba(24, 24, 27, 0.4)', backdropFilter: 'blur(10px)', border: '1px solid rgba(255,255,255,0.05)', borderRadius: 20, padding: 20, display: 'flex', flexDirection: 'column' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
            <h3 style={{ color: '#ffffff', fontWeight: 800, fontSize: 16, margin: 0, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              {col}
              <span style={{ fontSize: '0.75rem', background: 'rgba(255,255,255,0.1)', padding: '0.1rem 0.5rem', borderRadius: '999px', color: '#888' }}>
                {tasks.filter(t => t.status === col).length}
              </span>
            </h3>
            <button 
              onClick={() => { setSelectedTask(null); setActiveColumn(col); setIsModalOpen(true); }}
              style={{ background: 'rgba(16, 185, 129, 0.1)', color: '#10b981', border: 'none', borderRadius: '8px', width: '28px', height: '28px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer' }}
              title={`Add task to ${col}`}
              aria-label={`Add task to ${col} column`}
            >
              <Plus size={16} />
            </button>
          </div>

          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '1rem', minHeight: '100px' }}>
            {tasks.filter(t => t.status === col).length === 0 ? (
              <div style={{ 
                flex: 1, 
                display: 'flex', 
                flexDirection: 'column', 
                alignItems: 'center', 
                justifyContent: 'center', 
                padding: '2rem 1rem', 
                color: 'var(--text-sub)', 
                fontSize: '0.8rem', 
                border: '1px dashed var(--border)', 
                borderRadius: '14px',
                opacity: 0.6,
                gap: '0.5rem'
              }}>
                <CloudOff size={20} />
                <span>No tasks in {col}</span>
              </div>
            ) : (
              tasks.filter(t => t.status === col).map(task => (
                <div 
                  key={task.id} 
                  tabIndex={0} 
                  role="button" 
                  aria-label={`Task: ${task.title}. ${task.description || ''}`} 
                  onClick={() => { setSelectedTask(task); setIsModalOpen(true); }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      setSelectedTask(task);
                      setIsModalOpen(true);
                    }
                  }}
                  style={{ 
                    background: 'rgba(255,255,255,0.03)', 
                    border: '1px solid rgba(255,255,255,0.05)',
                    borderRadius: '14px', 
                    padding: '1rem', 
                    cursor: 'pointer',
                    transition: 'all 0.2s ease',
                    outline: 'none'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = 'rgba(255,255,255,0.05)';
                    e.currentTarget.style.transform = 'translateY(-2px)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = 'rgba(255,255,255,0.03)';
                    e.currentTarget.style.transform = 'translateY(0)';
                  }}
                >
                  <div style={{ fontWeight: 700, fontSize: '0.9rem', marginBottom: '0.4rem', color: '#f4f4f5' }}>{task.title}</div>
                  {task.description && (
                    <div style={{ fontSize: '0.75rem', color: '#a1a1aa', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
                      {task.description}
                    </div>
                  )}
                  
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '-0.4rem' }}>
                      {(task.assignees || []).slice(0, 3).map((uid) => {
                        const m = groupMembers.find(gm => gm.id === uid);
                        return (
                          <div key={uid} style={{ width: 22, height: 22, borderRadius: '50%', border: '2px solid #18181b', background: '#333', overflow: 'hidden' }} title={`Assigned to ${m?.full_name || 'Team Member'}`}>
                             {m?.avatar_url ? <img src={m.avatar_url} style={{ width: '100%', height: '100%', objectFit: 'cover' }} alt={m.full_name || 'Avatar'} /> : <div style={{ fontSize: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%' }} aria-label={m?.full_name || 'Team Member'}>{(m?.full_name || '?')[0]}</div>}
                          </div>
                        )
                      })}
                    </div>
                    {task.due_date && (
                      <div style={{ fontSize: '0.65rem', color: '#71717a', background: 'rgba(0,0,0,0.2)', padding: '0.1rem 0.4rem', borderRadius: '4px' }}>
                        {new Date(task.due_date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>

        </div>
      ))}
      {isModalOpen && (
        <TaskModal
          task={selectedTask || undefined}
          groupId={groupId}
          initialStatus={activeColumn}
          onClose={() => setIsModalOpen(false)}
          onRefresh={async () => {
             // Realtime handles this, but we can force fetch if needed
             const { data } = await db.from('tasks').select('*').eq('group_id', groupId);
             if (data) setTasks(data as Task[]);
          }}
          onTaskSaved={() => setIsModalOpen(false)}
          onlineUserIds={new Set(groupMembers.map(m => m.id))}
        />
      )}

      {isOnboardingOpen && (
        <KanbanOnboardingModal onClose={() => setIsOnboardingOpen(false)} />
      )}
      </div>
    </div>
  );
}

function KanbanBoardSkeleton() {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', width: '100%', marginTop: '1rem' }}>
      <div className="skeleton" style={{ height: '110px', borderRadius: '16px' }} />
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div className="skeleton skeleton-title" style={{ width: '30%' }} />
        <div className="skeleton" style={{ width: '100px', height: '38px', borderRadius: '14px' }} />
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '1.5rem' }}>
        {[1, 2, 3, 4].map(i => (
          <div key={i} style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            <div className="skeleton skeleton-title" style={{ width: '40%', height: '1.2rem' }} />
            <div className="skeleton skeleton-card" style={{ height: '120px' }} />
          </div>
        ))}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { Globe, Check, ChevronDown } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import { locales, detectBrowserLocale, isValidLocale, type LocaleCode } from '@/i18n/config'

// Only show locales that have compiled message files
const SUPPORTED_LOCALE_CODES = new Set([
  'en','es','zh','ar','hi','fr','pt','de','ja','ko',
  'it','tr','vi','pl','nl','id','th','sv','no','da',
])
const SUPPORTED_LOCALES = locales.filter((l) => SUPPORTED_LOCALE_CODES.has(l.code))

function readCookieLocale(): LocaleCode | null {
  if (typeof document === 'undefined') return null
  const match = document.cookie.match(/(?:^|;\s*)NEXT_LOCALE=([^;]+)/)
  const val = match ? decodeURIComponent(match[1]) : undefined
  return val && isValidLocale(val) ? val : null
}

export default function LanguageSelector() {
  const [open, setOpen] = useState(false)
  const [current, setCurrent] = useState<LocaleCode>(() => readCookieLocale() || detectBrowserLocale())
  const containerRef = useRef<HTMLDivElement>(null)

  // Close on outside click
  useEffect(() => {
    if (!open) return
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [open])

  const setLocale = (code: LocaleCode) => {
    // eslint-disable-next-line react-hooks/immutability
    document.cookie = `NEXT_LOCALE=${encodeURIComponent(code)}; path=/; max-age=31536000; SameSite=Lax`
    setOpen(false)
    window.location.reload()
  }

  const currentInfo = SUPPORTED_LOCALES.find((l) => l.code === current) ?? SUPPORTED_LOCALES[0]

  return (
    <div ref={containerRef} style={{ position: 'relative' }}>
      <button
        aria-label={`Current language: ${currentInfo.name}, click to change`}
        aria-expanded={open}
        aria-haspopup="listbox"
        onClick={() => setOpen((o) => !o)}
        style={{
          background: 'rgba(255,255,255,0.03)',
          border: '1px solid #222222',
          borderRadius: '6px',
          padding: '0.4rem 0.6rem',
          color: '#9ca3af',
          display: 'flex',
          alignItems: 'center',
          gap: '0.4rem',
          cursor: 'pointer',
          fontSize: '0.75rem',
          fontWeight: 600,
          transition: 'all 0.2s ease',
          whiteSpace: 'nowrap',
        }}
        onMouseEnter={(e) => { e.currentTarget.style.borderColor = '#10b981'; e.currentTarget.style.color = '#f3f4f6' }}
        onMouseLeave={(e) => { e.currentTarget.style.borderColor = '#222222'; e.currentTarget.style.color = '#9ca3af' }}
      >
        <Globe size={14} aria-hidden="true" />
        <span aria-hidden="true">{currentInfo.flag}</span>
        <ChevronDown
          size={10}
          aria-hidden="true"
          style={{ transform: open ? 'rotate(180deg)' : 'rotate(0deg)', transition: 'transform 0.2s ease' }}
        />
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            role="listbox"
            aria-label="Select language"
            initial={{ opacity: 0, y: -8, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -8, scale: 0.97 }}
            transition={{ duration: 0.15, ease: [0.16, 1, 0.3, 1] }}
            style={{
              position: 'absolute',
              right: 0,
              top: 'calc(100% + 0.5rem)',
              background: '#111111',
              border: '1px solid #222222',
              borderRadius: '10px',
              boxShadow: '0 20px 50px rgba(0,0,0,0.6)',
              width: '220px',
              maxHeight: '320px',
              overflowY: 'auto',
              zIndex: 2000,
              padding: '0.4rem',
            }}
          >
            {SUPPORTED_LOCALES.map((locale) => (
              <button
                key={locale.code}
                role="option"
                aria-selected={current === locale.code}
                onClick={() => setLocale(locale.code)}
                style={{
                  width: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.65rem',
                  padding: '0.55rem 0.7rem',
                  background: current === locale.code ? 'rgba(16,185,129,0.1)' : 'transparent',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  textAlign: 'left',
                  transition: 'background 0.15s ease',
                }}
                onMouseEnter={(e) => {
                  if (current !== locale.code) (e.currentTarget as HTMLElement).style.background = 'rgba(255,255,255,0.04)'
                }}
                onMouseLeave={(e) => {
                  if (current !== locale.code) (e.currentTarget as HTMLElement).style.background = 'transparent'
                }}
              >
                <span style={{ fontSize: '1rem', lineHeight: 1 }}>{locale.flag}</span>
                <div style={{ flex: 1, overflow: 'hidden' }}>
                  <div style={{ color: '#f3f4f6', fontSize: '0.8rem', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {locale.nativeName}
                  </div>
                  <div style={{ color: '#6b7280', fontSize: '0.7rem' }}>{locale.name}</div>
                </div>
                {current === locale.code && <Check size={12} color="#10b981" aria-hidden="true" />}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

'use client'

import { useEffect, useMemo, useRef, useState } from 'react'
import { fetchChatMessages, postChatPresence, sendChatMessage } from '../services/chat'

type ChatMessage = {
  id: string
  username: string
  message: string
  created_at: string
  status: string
}

type ChatEvent = {
  id: string
  event_type: string
  username?: string
  created_at: string
}

const CHAT_USER_KEY = 'espeezy_chat_user'

function getOrCreateClientUser() {
  const existing = typeof window !== 'undefined' ? window.localStorage.getItem(CHAT_USER_KEY) : null
  if (existing) {
    try {
      const parsed = JSON.parse(existing) as { userId: string; username: string; created: string }
      if (parsed.userId && parsed.username) return parsed
    } catch {
      // no-op
    }
  }

  const generated = {
    userId: `guest_${Math.random().toString(36).slice(2, 10)}`,
    username: `student_${Math.random().toString(36).slice(2, 8)}`,
    created: new Date().toISOString(),
  }

  if (typeof window !== 'undefined') {
    window.localStorage.setItem(CHAT_USER_KEY, JSON.stringify(generated))
  }

  return generated
}

function isChatEvent(value: unknown): value is ChatEvent {
  if (!value || typeof value !== 'object') return false
  const event = value as Record<string, unknown>
  return typeof event.id === 'string' && typeof event.event_type === 'string' && typeof event.created_at === 'string'
}

export default function LiveChatWidget({ appScope }: { appScope: 'prereg' | 'games' | 'kanban' }) {
  const initialUser = getOrCreateClientUser()
  const [open, setOpen] = useState(false)
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [newUserEvent, setNewUserEvent] = useState<ChatEvent | null>(null)
  const [text, setText] = useState('')
  const [username, setUsername] = useState(initialUser.username)
  const [userId] = useState(initialUser.userId)
  const [loading, setLoading] = useState(false)
  const lastSeenEventIdRef = useRef('')
  const clearEventTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    postChatPresence({ app_scope: appScope, event_type: 'new_user', user_id: userId, username }).catch(() => undefined)
  }, [appScope, userId, username])

  async function loadMessages() {
    const data = await fetchChatMessages(appScope, 30)
    if (Array.isArray(data.messages)) {
      setMessages(data.messages)
    }
    if (isChatEvent(data.new_user_event) && data.new_user_event.id !== lastSeenEventIdRef.current) {
      lastSeenEventIdRef.current = data.new_user_event.id
      setNewUserEvent(data.new_user_event)
      if (clearEventTimeoutRef.current) {
        clearTimeout(clearEventTimeoutRef.current)
      }
      clearEventTimeoutRef.current = setTimeout(() => setNewUserEvent(null), 5000)
    }
  }

  useEffect(() => {
    void loadMessages()
    const poll = setInterval(() => {
      void loadMessages()
      postChatPresence({ app_scope: appScope, event_type: 'active', user_id: userId || 'guest', username: username || 'guest' }).catch(() => undefined)
    }, 5000)

    return () => clearInterval(poll)
  }, [appScope, userId, username])

  useEffect(() => {
    return () => {
      if (clearEventTimeoutRef.current) {
        clearTimeout(clearEventTimeoutRef.current)
      }
    }
  }, [])

  const orderedMessages = useMemo(() => messages.slice(-20), [messages])

  async function sendMessage(e: React.FormEvent) {
    e.preventDefault()
    if (!text.trim() || !username.trim()) return

    setLoading(true)
    try {
      const res = await sendChatMessage({
        app_scope: appScope,
        user_id: userId,
        username,
        message: text.trim(),
      })

      if (res.ok) {
        setText('')
        void loadMessages()
      }
    } finally {
      setLoading(false)
    }
  }

  return (
    <>
      {newUserEvent && newUserEvent.username && (
        <div style={{ position: 'fixed', right: '1.5rem', bottom: '6rem', zIndex: 1200, background: 'white', color: '#0f172a', border: '1px solid rgba(15,23,42,0.1)', borderRadius: '12px', padding: '0.75rem 1rem', fontSize: '0.85rem', fontWeight: 600, boxShadow: '0 10px 40px rgba(15,23,42,0.12)', borderLeft: '4px solid #6366f1' }}>
          {newUserEvent.username} joined live chat
        </div>
      )}

      {open && (
        <div style={{ position: 'fixed', right: '1.5rem', bottom: '5.5rem', width: '340px', maxHeight: '500px', zIndex: 1200, background: 'white', color: '#0f172a', border: '1px solid rgba(15,23,42,0.12)', borderRadius: '20px', display: 'flex', flexDirection: 'column', overflow: 'hidden', boxShadow: '0 20px 50px rgba(15,23,42,0.15)' }}>
          <div style={{ padding: '1rem 1.25rem', borderBottom: '1px solid rgba(15,23,42,0.06)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#f8fafc' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
              <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#10b981', boxShadow: '0 0 8px #10b981' }} />
              <strong style={{ fontSize: '0.9rem', fontWeight: 800, letterSpacing: '-0.02em' }}>Community Support</strong>
            </div>
            <button type='button' onClick={() => setOpen(false)} aria-label="Close chat" style={{ background: 'rgba(15,23,42,0.05)', color: '#64748b', border: 'none', borderRadius: '50%', width: '28px', height: '28px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', fontSize: '0.7rem', fontWeight: 900 }}>✕</button>
          </div>

          <div style={{ padding: '0.75rem 1rem', borderBottom: '1px solid rgba(15,23,42,0.06)' }}>
            <input
              value={username}
              onChange={(e) => {
                const clean = e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, '').slice(0, 24)
                setUsername(clean)
                if (clean.length >= 3) {
                  window.localStorage.setItem(CHAT_USER_KEY, JSON.stringify({ userId, username: clean, created: new Date().toISOString() }))
                }
              }}
              placeholder='Set your username'
              style={{ width: '100%', borderRadius: '10px', border: '1px solid rgba(15,23,42,0.1)', background: '#f1f5f9', color: '#0f172a', padding: '0.55rem 0.75rem', fontSize: '0.85rem', outline: 'none' }}
            />
          </div>

          <div style={{ flex: 1, overflowY: 'auto', padding: '1rem', display: 'flex', flexDirection: 'column', gap: '0.75rem', background: '#ffffff' }}>
            {orderedMessages.map((m) => (
              <div key={m.id} style={{ alignSelf: m.username === username ? 'flex-end' : 'flex-start', maxWidth: '85%' }}>
                <div style={{ fontSize: '0.65rem', color: '#64748b', fontWeight: 700, marginBottom: '0.2rem', textAlign: m.username === username ? 'right' : 'left', padding: '0 0.4rem' }}>{m.username}</div>
                <div style={{ background: m.username === username ? '#6366f1' : '#f1f5f9', color: m.username === username ? 'white' : '#0f172a', borderRadius: '14px', borderTopRightRadius: m.username === username ? '2px' : '14px', borderTopLeftRadius: m.username === username ? '14px' : '2px', padding: '0.6rem 0.8rem', fontSize: '0.85rem', lineHeight: 1.4, boxShadow: m.username === username ? '0 4px 12px rgba(99,102,241,0.2)' : 'none' }}>
                  {m.message}
                </div>
              </div>
            ))}
            {orderedMessages.length === 0 && (
              <div style={{ color: '#94a3b8', fontSize: '0.85rem', textAlign: 'center', marginTop: '2rem' }}>
                <p>No messages yet.</p>
                <p style={{ fontSize: '0.75rem' }}>Be the first to say hello!</p>
              </div>
            )}
          </div>

          <form onSubmit={sendMessage} style={{ borderTop: '1px solid rgba(15,23,42,0.06)', padding: '0.85rem 1rem', display: 'flex', gap: '0.5rem', background: 'white' }}>
            <input
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder='Type a message...'
              maxLength={1000}
              style={{ flex: 1, borderRadius: '12px', border: '1px solid rgba(15,23,42,0.1)', background: '#ffffff', color: '#0f172a', padding: '0.6rem 0.8rem', fontSize: '0.85rem', outline: 'none' }}
            />
            <button type='submit' disabled={loading || username.trim().length < 3} style={{ borderRadius: '12px', border: 'none', background: '#6366f1', color: 'white', padding: '0.6rem 1rem', fontSize: '0.85rem', fontWeight: 700, cursor: 'pointer', transition: 'transform 0.1s ease', opacity: (loading || username.trim().length < 3) ? 0.5 : 1 }}>
              Send
            </button>
          </form>
        </div>
      )}

      <button
        type='button'
        onClick={() => setOpen((v) => !v)}
        style={{ position: 'fixed', right: '1.5rem', bottom: '1.5rem', zIndex: 1200, border: 'none', borderRadius: '18px', padding: '0 1.5rem', height: '48px', background: '#0f172a', color: 'white', fontWeight: 800, cursor: 'pointer', boxShadow: '0 8px 25px rgba(15,23,42,0.25)', display: 'flex', alignItems: 'center', gap: '0.6rem', transition: 'all 0.2s ease' }}
        onMouseEnter={(e) => {
          e.currentTarget.style.transform = 'translateY(-2px)'
          e.currentTarget.style.boxShadow = '0 12px 30px rgba(15,23,42,0.3)'
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.transform = 'translateY(0)'
          e.currentTarget.style.boxShadow = '0 8px 25px rgba(15,23,42,0.25)'
        }}
        aria-label='Toggle live chat'
      >
        <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#10b981' }} />
        Live Support
      </button>
    </>
  )
}

'use client'

import { useState } from 'react'
import { AssetSchema, createMarketplaceAsset } from '@/services/marketplace'
import { z } from 'zod'

const CATEGORIES = [
  'Graphics', 'Logos', 'Templates', 'Icons', 'UI Kits', 'Mockups', '3D', 'Fonts', 'Other'
]

export default function MarketplaceAssetUploader({ onUpload }: { onUpload?: () => void }) {
  const [form, setForm] = useState({
    title: '',
    description: '',
    category: '',
    asset_url: '',
    preview_url: '',
    tags: '',
    price: '',
  })
  const [error, setError] = useState('')
  const [submitting, setSubmitting] = useState(false)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setError('')
    setSubmitting(true)
    const parsed = AssetSchema.omit({ id: true, user_id: true, created_at: true, updated_at: true, is_featured: true }).safeParse({
      ...form,
      tags: form.tags.split(',').map(t => t.trim()).filter(Boolean),
      price: form.price ? Number(form.price) : undefined,
    })
    if (!parsed.success) {
      setError(parsed.error.issues?.[0]?.message || 'Invalid input')
      setSubmitting(false)
      return
    }
    try {
      await createMarketplaceAsset(parsed.data)
      setForm({ title: '', description: '', category: '', asset_url: '', preview_url: '', tags: '', price: '' })
      if (onUpload) onUpload()
    } catch (err) {
      setError('Failed to upload asset')
    }
    setSubmitting(false)
  }

  return (
    <form onSubmit={handleSubmit} style={{ background: 'rgba(20,20,30,0.95)', borderRadius: 16, padding: 32, maxWidth: 480, margin: '0 auto', boxShadow: '0 8px 32px rgba(0,0,0,0.18)' }}>
      <h2 style={{ fontWeight: 900, fontSize: '1.5rem', marginBottom: 16 }}>Upload Digital Asset</h2>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <input required placeholder='Title' value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} style={{ padding: 12, borderRadius: 8, border: '1px solid #222', background: '#181828', color: 'white', fontWeight: 700 }} />
        <textarea placeholder='Description' value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} style={{ padding: 12, borderRadius: 8, border: '1px solid #222', background: '#181828', color: 'white', fontWeight: 500, minHeight: 60 }} />
        <select required value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))} style={{ padding: 12, borderRadius: 8, border: '1px solid #222', background: '#181828', color: 'white', fontWeight: 700 }}>
          <option value=''>Select Category</option>
          {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <input required placeholder='Asset File URL' value={form.asset_url} onChange={e => setForm(f => ({ ...f, asset_url: e.target.value }))} style={{ padding: 12, borderRadius: 8, border: '1px solid #222', background: '#181828', color: 'white', fontWeight: 700 }} />
        <input placeholder='Preview Image URL' value={form.preview_url} onChange={e => setForm(f => ({ ...f, preview_url: e.target.value }))} style={{ padding: 12, borderRadius: 8, border: '1px solid #222', background: '#181828', color: 'white', fontWeight: 700 }} />
        <input placeholder='Tags (comma separated)' value={form.tags} onChange={e => setForm(f => ({ ...f, tags: e.target.value }))} style={{ padding: 12, borderRadius: 8, border: '1px solid #222', background: '#181828', color: 'white', fontWeight: 700 }} />
        <input placeholder='Price (leave blank for free)' type='number' min='0' value={form.price} onChange={e => setForm(f => ({ ...f, price: e.target.value }))} style={{ padding: 12, borderRadius: 8, border: '1px solid #222', background: '#181828', color: 'white', fontWeight: 700 }} />
        {error && <div style={{ color: '#ff4d4f', fontWeight: 700 }}>{error}</div>}
        <button type='submit' disabled={submitting} style={{ padding: 14, borderRadius: 8, background: 'linear-gradient(90deg, #10b981 0%, #6366f1 100%)', color: 'white', fontWeight: 900, fontSize: '1rem', border: 'none', marginTop: 8, cursor: 'pointer', opacity: submitting ? 0.7 : 1 }}>Upload Asset</button>
      </div>
    </form>
  )
}

