            )}
          </div>

          {showChat && isConnected && (
            <div style={{ marginTop: '2rem', height: '350px', animation: 'fadeIn 0.3s ease' }}>
              <ChatRoom
                roomId={`chat_${[me?.id, member.id].sort().join('_')}`}
