          borderRadius: '50%', width: '32px', height: '32px', flexShrink: 0,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          cursor: newMessage.trim() ? 'pointer' : 'default'
        }}
        aria-label="Send message"
      >
        <Send size={15} />
      </button>
    </div>
  )
}

export default function TeamChat({ groupId, user }: TeamChatProps) {
  const db = useMemo(() => createBrowserSupabaseClient(), [])
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [newMessage, setNewMessage] = useState('')
  const [isOpen, setIsOpen] = useState(false)
  const [loading, setLoading] = useState(true)
  const [uploading, setUploading] = useState(false)
  const [showLobby, setShowLobby] = useState(false)
  const [groupMembers, setGroupMembers] = useState<Profile[]>([])
  const [isSearching, setIsSearching] = useState(false)
  const [chatSearch, setChatSearch] = useState('')
  const typingTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  
  const router = useRouter()
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const { isOnline } = useConnectivity()
  const { onlineUsers, typingUsers, setTypingStatus } = usePresence()

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    messagesEndRef.current?.scrollIntoView({ behavior })
  }

  // Request Notification Permission
  useEffect(() => {
    if (typeof window !== 'undefined' && 'Notification' in window) {
      if (Notification.permission === 'default') {
        Notification.requestPermission()
      }
    }
  }, [])

  // Real-time Subscription
  useEffect(() => {
    let active = true

    const loadMessages = async () => {
      const { data, error } = await db
        .from('messages')
        .select('id, group_id, user_id, content, payload, is_deleted, created_at, profiles:profiles!messages_user_id_fkey(full_name, avatar_url, role)')
        .eq('group_id', groupId)
        .order('created_at', { ascending: true })
        .limit(50)

      if (!active) return
      if (error) {
        console.error('Messages load error:', error.message)
        setLoading(false)
        return
      }

      const normalized = (data ?? []).map((row: Record<string, unknown>) => ({
        ...row,
        profiles: Array.isArray(row.profiles) ? row.profiles[0] : row.profiles,
      }))
      setMessages(normalized as ChatMessage[])
      setLoading(false)
      setTimeout(() => scrollToBottom('smooth'), 100)
    }

    loadMessages()

    const channel = db
      .channel(`team-messages:${groupId}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'messages', filter: `group_id=eq.${groupId}` },
        (payload) => {
          if (payload.eventType === 'INSERT') {
            const incoming = payload.new as ChatMessage
            if (incoming.user_id !== user.id && (!isOpen || document.hidden)) {
              if ('Notification' in window && Notification.permission === 'granted') {
                new Notification('New Team Message', {
                  body: incoming.content || 'Sent an attachment',
                  icon: '/brand-logo-black-gold.png'
                })
              }
            }
          }

          loadMessages()
        }
      )
      .subscribe()

    return () => {
      active = false
      db.removeChannel(channel)
    }
  }, [db, groupId, isOpen, user.id])

  useEffect(() => {
    if (!isOpen) return

    let active = true
    const loadMembers = async () => {
      const { data, error } = await db
        .from('profiles')
        .select('*')
        .eq('group_id', groupId)

      if (!active) return
      if (error) {
        console.error('Group members load error:', error.message)
        return
      }

      setGroupMembers((data ?? []) as Profile[])
    }

    loadMembers()

    const channel = db
      .channel(`team-members:${groupId}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'profiles', filter: `group_id=eq.${groupId}` },
        () => loadMembers()
      )
      .subscribe()

    return () => {
      active = false
      db.removeChannel(channel)
    }
  }, [db, isOpen, groupId])

  const handleTyping = (text: string) => {
    setNewMessage(text)
    setTypingStatus(true)
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current)
    typingTimeoutRef.current = setTimeout(() => {
       setTypingStatus(false)
    }, 2000)
  }

  const handleSendMessage = async (e: React.FormEvent | null, contentOverride?: string, payload?: ChatPayload) => {
    e?.preventDefault()
    const content = contentOverride || newMessage.trim()
    if (!content && !payload) return

    setTypingStatus(false)
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current)

    setNewMessage('')
    scrollToBottom('smooth')

    try {
      const { data, error } = await db
        .from('messages')
        .insert({
          group_id: groupId,
          user_id: user.id,
          content,
          payload: payload ?? null,
          is_deleted: false,
          created_at: new Date().toISOString(),
        })
        .select('id')
        .single()

      if (error) throw error

      // Verifiable Logging
      logActivity(
        user.id, 
        groupId, 
        'message_sent', 
        `Sent a ${payload?.type || 'text'} message`,
        { message_id: data.id }
      )
    } catch (err: unknown) {
      console.error('Send message error:', err instanceof Error ? err.message : 'Unknown error')
    }
  }

  const handleDeleteMessage = async (msgId: string) => {
     if (!confirm('Are you sure you want to delete this message for everyone?')) return
     
     try {
       const { error } = await db
         .from('messages')
         .update({
           is_deleted: true,
           content: 'This message was deleted'
         })
         .eq('id', msgId)

       if (error) throw error
       
       logActivity(
         user.id, 
         groupId, 
         'message_deleted', 
         'Deleted a message',
         { message_id: msgId }
       )
    } catch (err: unknown) {
       console.error('Delete message error:', err instanceof Error ? err.message : 'Unknown error')
     }
  }

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
     const file = e.target.files?.[0]
     if (!file) return
     
     setUploading(true)
     try {
       const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, '_')
       const filePath = `${groupId}/chat-${Date.now()}-${safeName}`

       const { error: uploadError } = await db.storage
         .from('espeezy-assets')
         .upload(filePath, file, { upsert: false })

       if (uploadError) throw uploadError

       const { data } = db.storage
         .from('espeezy-assets')
         .getPublicUrl(filePath)

       const publicUrl = data.publicUrl

       await handleSendMessage(
          null,
          '',
          {
            type: file.type.startsWith('image/') ? 'image' : 'file',
            url: publicUrl,
            name: file.name
          }
       )
    } catch (err: unknown) {
       console.error('File upload error:', err instanceof Error ? err.message : 'Unknown error')
     } finally {
       setUploading(false)
     }
  }

  const filteredMessages = useMemo(() => {
     if (!chatSearch.trim()) return messages
     const term = chatSearch.toLowerCase()
     return messages.filter(m => 
        m.content.toLowerCase().includes(term) || 
        m.profiles?.full_name?.toLowerCase().includes(term)
     )
  }, [messages, chatSearch])

    const groupedMessages = useMemo(() => {
      const groups: { date: string, msgs: ChatMessage[] }[] = []
      filteredMessages.forEach((m) => {
        const label = formatDateLabel(m.created_at)

        const lastGroup = groups[groups.length - 1]
        if (lastGroup && lastGroup.date === label) {
          lastGroup.msgs.push(m)
        } else {
          groups.push({ date: label, msgs: [m] })
        }
      })
      return groups
  }, [filteredMessages])

  const othersTyping = Array.from(typingUsers).filter(id => id !== user.id)
    const teamOnlineCount = useMemo(() => {
     return groupMembers.filter(m => onlineUsers.has(m.id)).length
    }, [groupMembers, onlineUsers])

  if (!isOpen) {
      return <ClosedChatButton onOpen={() => setIsOpen(true)} />
  }

  return (
    <div 
      style={{
        position: 'fixed', 
        bottom: 'calc(var(--h-mobile-bottom) + 1rem + env(safe-area-inset-bottom))', 
        right: 'min(2rem, 0.5rem)', 
        width: 'min(400px, calc(100vw - 1rem))', 
        maxHeight: 'calc(var(--vh-dynamic) - var(--h-mobile-bottom) - var(--h-nav) - 2rem)', 
        background: 'var(--surface)', 
        borderRadius: '24px', 
        boxShadow: '0 24px 48px rgba(0,0,0,0.2)', 
        border: '1px solid var(--border)', 
        display: 'flex', 
        flexDirection: 'column', 
        zIndex: 5000, 
        overflow: 'hidden', 
        animation: 'whatsappIn 0.4s ease-out'
      }}
      className="responsive-chat"
    >
      <TeamChatHeader
        isSearching={isSearching}
        chatSearch={chatSearch}
        onSearchChange={(value) => setChatSearch(value)}
        onCloseSearch={() => { setIsSearching(false); setChatSearch('') }}
        othersTyping={othersTyping}
        teamOnlineCount={teamOnlineCount}
        showLobby={showLobby}
        onToggleLobby={() => setShowLobby((prev) => !prev)}
        onOpenSearch={() => setIsSearching(true)}
        onClose={() => setIsOpen(false)}
      />

      <TeamLobby
        showLobby={showLobby}
        groupMembers={groupMembers}
        userId={user.id}
        onViewProfile={(memberId) => router.push(`/network/profile/${memberId}`)}
      />

      <MessageList
        loading={loading}
        messages={messages}
        groupedMessages={groupedMessages}
        user={user}
        isOnline={isOnline}
        othersTyping={othersTyping}
        onDeleteMessage={handleDeleteMessage}
        messagesEndRef={messagesEndRef}
      />

      <ChatInputBar
        newMessage={newMessage}
        isOnline={isOnline}
        uploading={uploading}
        onTyping={handleTyping}
        onUpload={handleFileUpload}
        onSend={handleSendMessage}
      />

       <style jsx>{`
          @keyframes whatsappIn { 
            from { opacity: 0; transform: translateY(40px) scale(0.9); } 
            to { opacity: 1; transform: translateY(0) scale(1); } 
          }
          @keyframes shimmer {
            0% { background-position: -200% 0; }
            100% { background-position: 200% 0; }
          }
          .msg-bubble.pending { opacity: 0.65; }
          .chat-viewport::-webkit-scrollbar { display: block; width: 4px; }
          .chat-viewport::-webkit-scrollbar-thumb { background: var(--border); border-radius: 10px; }
          .chat-viewport { scrollbar-width: thin; scrollbar-color: var(--border) transparent; }
          .typing-dots span { animation: blink 1.4s infinite; opacity: 0; font-size: 1.1rem; margin: 0 0.5px; }
          .typing-dots span:nth-child(2) { animation-delay: 0.2s; }
          .typing-dots span:nth-child(3) { animation-delay: 0.4s; }
          @keyframes blink { 0% { opacity: 0; } 50% { opacity: 1; } 100% { opacity: 0; } }
          @keyframes slideUp { 
            from { opacity: 0; transform: translateY(20px); } 
            to { opacity: 1; transform: translateY(0); } 
          }
          .msg-bubble:hover .delete-btn { opacity: 0.7 !important; }
          .icon-btn:hover { background: var(--border); }
          .chat-toggle:hover { transform: scale(1.08) translateY(-2px); box-shadow: 0 12px 24px rgba(0,0,0,0.3); }
          .lobby-card:hover { transform: translateX(5px); border-color: var(--brand) !important; background: var(--surface) !important; }

          @media (min-width: 769px) {
            .chat-toggle {
              bottom: 2rem !important;
              right: 2rem !important;
            }
            .responsive-chat {
              bottom: 2rem !important;
              right: 2rem !important;
              height: min(650px, calc(100vh - 6rem)) !important;
            }
          }
       `}</style>
    </div>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { Users } from 'lucide-react'
import { fetchPreregisterCount } from '@/services/preregister'

export default function UserCount() {
  const [count, setCount] = useState<number | null>(null)
  const [isLive, setIsLive] = useState(false)

  const fetchCount = async () => {
    try {
      const nextCount = await fetchPreregisterCount()
      if (typeof nextCount === 'number') {
        setCount(nextCount)
        setIsLive(true)
        setTimeout(() => setIsLive(false), 2000)
      }
    } catch (err) {
      console.error('Failed to fetch user count:', err)
    }
  }

  useEffect(() => {
    fetchCount()
    // Poll for updates every 30 seconds since we don't have real-time listeners for this simple count
    const interval = setInterval(fetchCount, 30000)
    return () => clearInterval(interval)
  }, [])

  if (count === null) return <span style={{ opacity: 0.5 }}>...</span>

  return (
    <div style={{ 
      display: 'inline-flex', 
      alignItems: 'center', 
      gap: '0.4rem', 
      transition: 'all 0.3s ease', 
      transform: isLive ? 'scale(1.1)' : 'scale(1)' 
    }}>
      <Users size={16} style={{ color: isLive ? '#10b981' : 'inherit' }} />
      <span style={{ fontWeight: 700 }}>
        {(count + 1200).toLocaleString()}
      </span>
      {isLive && (
        <span style={{ 
          width: '6px', 
          height: '6px', 
          background: '#10b981', 
          borderRadius: '50%', 
          boxShadow: '0 0 8px #10b981',
          animation: 'pulse 1s infinite'
        }} />
      )}
      <style jsx>{`
        @keyframes pulse {
          0% { transform: scale(1); opacity: 1; }
          50% { transform: scale(1.5); opacity: 0.5; }
          100% { transform: scale(1); opacity: 1; }
        }
      `}</style>
    </div>
  )
}

'use client'

/**
 * useAdminDashboard
 *
 * Custom hook that owns ALL state and data-fetching for the Admin Dashboard.
 * No UI code lives here  -  just data, effects, and callbacks.
 *
 * Why a hook?
 *   - Keeps page.tsx and every sub-component free of business logic.
 *   - Makes every action testable in isolation.
 *   - A single place to change the data layer later (e.g. swap direct Supabase
 *     calls for API service calls) without touching any component.
 */

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { db, collection, query, where, getDocs, getDoc, doc, updateDoc, onSnapshot, orderBy, limit, getCountFromServer, selectCols } from '@/lib/db-client'
import { useProfile } from '@/context/ProfileContext'
import { useNotifications } from '@/components/NotificationProvider'
import type {
  AdminStats,
  RecentUser,
  SystemLog,
  LaunchConfig,
  PlatformConfig,
  ConfigEntry,
} from './types'

// ── Default values defined outside the hook ────────────────────────────────────
// Keeps them stable across renders (no new object reference each call).

const DEFAULT_STATS: AdminStats = { users: 0, pro: 0, premium: 0, revenue: 0 }

const DEFAULT_LAUNCH_CONFIG: LaunchConfig = {
  launch_date: '',
  launch_message: '',
  preregister_goal: '',
  preregister_open: 'true',
  brand_name: '',
  platform_version: '',
}

const SEED_LOGS: SystemLog[] = [
  { t: '13:42:01', m: 'AUTH_GATEWAY: [200] OK' },
  { t: '13:42:05', m: 'FIREBASE_SYNC: Institutional Node Established' },
  { t: '13:42:12', m: 'STRIPE_WEBHOOK: Listening on events' },
  { t: '13:42:18', m: 'ELITE30_CHECK: 4 redemptions validated' },
]

// ── Hook ───────────────────────────────────────────────────────────────────────

export function useAdminDashboard() {
  const { profile, loading: profileLoading } = useProfile()
  const router = useRouter()
  const { addToast } = useNotifications()

  // ── Auth / verification state ──
  const [isVerified, setIsVerified] = useState(false)
  const [verificationCode, setVerificationCode] = useState('')
  const [verifying, setVerifying] = useState(false)

  // ── Dashboard data ──
  const [stats, setStats] = useState<AdminStats>(DEFAULT_STATS)
  const [recentUsers, setRecentUsers] = useState<RecentUser[]>([])
  const [loading, setLoading] = useState(true)
  const [systemLogs, setSystemLogs] = useState<SystemLog[]>([])
  const [config, setConfig] = useState<PlatformConfig>({})
  const [savingConfig, setSavingConfig] = useState(false)

  // ── Launch config ──
  const [launchConfig, setLaunchConfig] = useState<LaunchConfig>(DEFAULT_LAUNCH_CONFIG)
  const [preregCount, setPreregCount] = useState(0)
  const [savingLaunchConfig, setSavingLaunchConfig] = useState(false)

  // ── Effect: redirect non-admins ────────────────────────────────────────────
  useEffect(() => {
    if (profileLoading) return
    if (!profile || profile.role !== 'admin') {
      addToast(
        'Unauthorized Access',
        'You do not have administrative clearance for this terminal.',
        'error',
      )
      router.push('/')
    }
  }, [profile, profileLoading, router, addToast])

  // ── Effect: live terminal log heartbeat ────────────────────────────────────
  useEffect(() => {
    if (!isVerified) return

    // Show seed logs immediately on verification
    queueMicrotask(() => setSystemLogs(SEED_LOGS))

    const interval = setInterval(() => {
      const time = new Date().toLocaleTimeString('en-GB', { hour12: false })
      const nodeId = Math.floor(Math.random() * 100)
      setSystemLogs((prev) => [
        { t: time, m: `UPLINK_EVENT: Heartbeat detected from Node_${nodeId}` },
        ...prev.slice(0, 7), // keep the last 7 + the new one = 8 visible lines
      ])
    }, 5000)

    return () => clearInterval(interval)
  }, [isVerified])

  // ── fetchAdminData ─────────────────────────────────────────────────────────
  // All aggregation and list queries run in parallel.
  const fetchAdminData = useCallback(async () => {
    setLoading(true)

    try {
      const [
        totalUsersSnap,
        proUsersSnap,
        premiumUsersSnap,
        lifetimeUsersSnap,
        recentSnap,
        configSnap,
      ] = await Promise.all([
        getCountFromServer(collection(db, 'profiles')),
        getCountFromServer(query(collection(db, 'profiles'), where('subscription_plan', '==', 'pro'))),
        getCountFromServer(query(collection(db, 'profiles'), where('subscription_plan', '==', 'premium'))),
        getCountFromServer(query(collection(db, 'profiles'), where('subscription_plan', '==', 'lifetime'))),
        getDocs(query(collection(db, 'profiles'), orderBy('created_at', 'desc'), limit(8), selectCols('id, full_name, avatar_url, role, created_at'))),
        getDocs(query(collection(db, 'platform_config')))
      ])

      const totalUsers = totalUsersSnap.data().count
      const proUsers = proUsersSnap.data().count
      const premiumUsers = premiumUsersSnap.data().count
      const lifetimeUsers = lifetimeUsersSnap.data().count

      // Convert the config rows array into a key-indexed map
      const configMap = configSnap.docs.reduce(
        (acc: PlatformConfig, doc) => {
          const item = doc.data() as { key: string } & ConfigEntry
          return { ...acc, [item.key]: item }
        },
        {} as PlatformConfig,
      )

      // --- Metrics Calculation (simple demo logic, replace with real formulas as needed) ---
      const revenue = proUsers * 4.99 + premiumUsers * 14.99 + lifetimeUsers * 99
      // LTV: (ARPU * Gross Margin %) / Churn Rate (demo: ARPU = revenue/totalUsers, margin=0.8, churn=0.03)
      const arpu = totalUsers > 0 ? revenue / totalUsers : 0
      const grossMargin = 0.8
      const churnRate = 0.03
      const ltv = churnRate > 0 ? Math.round((arpu * grossMargin) / churnRate) : 0
      // CAC: demo value (replace with real acquisition cost tracking)
      const cac = 25
      // NRR: demo value (replace with real retention calculation)
      const nrr = 0.92

      setStats({
        users: totalUsers,
        pro: proUsers,
        premium: premiumUsers + lifetimeUsers,
        revenue,
        ltv,
        cac,
        nrr,
      })
      setRecentUsers(recentSnap.docs.map((d) => ({ id: d.id, ...d.data() } as unknown as RecentUser)))
      setConfig(configMap)
    } catch (err) {
      console.error('Fetch admin data error:', err instanceof Error ? err.message : err)
    } finally {
      setLoading(false)
    }
  }, [])

  // ── Effect: fetch data + real-time subscriptions once verified ─────────────
  useEffect(() => {
    if (!isVerified) return

    queueMicrotask(() => void fetchAdminData())

    // Platform Config listener
    const configUnsub = onSnapshot(query(collection(db, 'platform_config')), () => {
      addToast('Platform Real-time Sync', 'Marketing configuration updated.', 'success')
      fetchAdminData()
    })

    // New Profile listener
    const profileUnsub = onSnapshot(query(collection(db, 'profiles'), orderBy('created_at', 'desc'), limit(1)), (snap) => {
      // Assuming snapshot returns a way to see changes or we just refresh
      // For this shim, snapshot triggers on any change in the query
      addToast('Institutional Event', 'User registration detected. Refreshing terminal...', 'success')
      fetchAdminData()
    })

    return () => {
      configUnsub()
      profileUnsub()
    }
  }, [isVerified, addToast, fetchAdminData])

  // ── Effect: load launch config and pre-reg count ───────────────────────────
  useEffect(() => {
    if (!isVerified) return

    async function loadLaunchConfig() {
      try {
        const [cfgRes, countRes] = await Promise.all([
          fetch('/api/admin/launch-config'),
          fetch('/api/preregister'),
        ])
        const { config: cfg } = await cfgRes.json()
        const { count } = await countRes.json()
        if (cfg) setLaunchConfig((prev) => ({ ...prev, ...cfg }))
        setPreregCount(count ?? 0)
      } catch {
        // Non-critical  -  silently ignore; the form just shows empty defaults
      }
    }

    loadLaunchConfig()
  }, [isVerified])

  // ── Actions ────────────────────────────────────────────────────────────────

  /** Saves all launch config fields to the API and shows a toast. */
  const saveLaunchConfig = useCallback(async () => {
    setSavingLaunchConfig(true)
    try {
      const updates = Object.entries(launchConfig).map(([key, value]) => ({ key, value }))
      const res = await fetch('/api/admin/launch-config', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updates),
      })
      if (res.ok) {
        addToast('Launch Config Saved', 'Pre-registration page updated live.', 'success')
      } else {
        addToast('Save Failed', 'Could not update launch configuration.', 'error')
      }
    } catch {
      addToast('Network Error', 'Failed to save configuration.', 'error')
    }
    setSavingLaunchConfig(false)
  }, [launchConfig, addToast])

  /**
   * Performs a quick user action (ban / upgrade / unlock) from the user list.
   */
  const handleUserAction = useCallback(
    async (userId: string, action: 'unlock' | 'upgrade' | 'ban') => {
      addToast(
        'Orchestration Command Sent',
        `Executing ${action} on node ${userId.slice(0, 8)}...`,
        'success',
      )

      const updateData: Record<string, unknown> =
        action === 'upgrade'
          ? { subscription_plan: 'premium' }
          : action === 'ban'
            ? { role: 'banned' }
            : { role: 'user' }

      try {
        await updateDoc(doc(db, 'profiles', userId), updateData)
        addToast('Operation Success', 'Database synchronized.', 'success')
        fetchAdminData()
      } catch (err) {
        addToast('Command Failed', err instanceof Error ? err.message : String(err), 'error')
      }
    },
    [addToast, fetchAdminData],
  )

  /** Updates a single key in the platform_config table. */
  const updatePlatformConfig = useCallback(
    async (
      key: string,
      updates: Record<string, string | number | boolean | Record<string, string>>,
    ) => {
      setSavingConfig(true)
      try {
        // In Firestore, we use the document ID if the key is the ID, 
        // or we query for the doc with that key field.
        // Assuming 'key' is the doc ID for simplicity or querying:
        const q = query(collection(db, 'platform_config'), where('key', '==', key))
        const snap = await getDocs(q)
        if (!snap.empty) {
          await updateDoc(doc(db, 'platform_config', snap.docs[0].id), updates)
          addToast('State Persisted', `${key} re-routed successfully.`, 'success')
          fetchAdminData()
        }
      } catch (err) {
        addToast('Sync Error', err instanceof Error ? err.message : String(err), 'error')
      }
      setSavingConfig(false)
    },
    [addToast, fetchAdminData],
  )

  /**
   * Verifies the admin clearance code.
   * The code is intentionally simple  -  the real gate is the server-side
   * role check in the layout and every API route.
   */
  const handleVerify = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault()
      setVerifying(true)
      setTimeout(() => {
        if (verificationCode === '2026-ADMIN') {
          setIsVerified(true)
          addToast('Identity Verified', 'Administrative session established.', 'success')
        } else {
          addToast(
            'Verification Failed',
            'Invalid clearance code. Retry limit approaching.',
            'error',
          )
        }
        setVerifying(false)
      }, 1200)
    },
    [verificationCode, addToast],
  )

  /** Navigates to the theme studio from the UI Orchestrator card. */
  const handleLaunchStudio = useCallback(() => {
    addToast('Orchestrator Initialized', 'Rerouting terminal to design studio...', 'success')
    router.push('/settings?tab=themes')
  }, [addToast, router])

  // ── Return the full public API of this hook ────────────────────────────────
  return {
    // profile
    profile,
    profileLoading,

    // verification
    isVerified,
    verificationCode,
    setVerificationCode,
    verifying,
    handleVerify,

    // dashboard data
    stats,
    recentUsers,
    loading,
    systemLogs,
    config,
    setConfig,
    savingConfig,

    // launch config
    launchConfig,
    setLaunchConfig,
    preregCount,
    savingLaunchConfig,
    saveLaunchConfig,

    // actions
    fetchAdminData,
    handleUserAction,
    updatePlatformConfig,
    handleLaunchStudio,
  }
}

import { useCallback, useEffect, useState } from 'react'
import { Group, Profile } from '@/types/database'
import {
  fetchGroupById,
  fetchGroupMembers,
  fetchGroupTasks,
  fetchPendingJoinRequests,
  fetchPersonalPendingTaskCount,
} from '@/services/dashboard'

type AddToast = (title: string, description: string, variant: 'success' | 'error' | 'info') => void

type ViewerProfile = {
  id?: string | null
  role?: string | null
}

export interface JoinRequest {
  id: string
  group_id: string
  user_id: string
  status: string
  created_at: string
  profiles?: {
    id: string
    full_name: string | null
    avatar_url: string | null
  }
}

export function useDashboardHomeData(groupId: string, profile: ViewerProfile | null | undefined, addToast: AddToast) {
  const [personalTaskCount, setPersonalTaskCount] = useState(0)
  const [group, setGroup] = useState<Group | null>(null)
  const [newTaskSignal, setNewTaskSignal] = useState(0)
  const [syncToken, setSyncToken] = useState(0)
  const [members, setMembers] = useState<Profile[]>([])
  const [pendingRequests, setPendingRequests] = useState<JoinRequest[]>([])
  const [showMembers, setShowMembers] = useState(false)
  const [projectProgress, setProjectProgress] = useState(0)
  const [progressLabel, setProgressLabel] = useState('Starting up')
  const [totalBacklog, setTotalBacklog] = useState(0)

  useEffect(() => {
    if (!groupId) return
    try {
      const cachedGroup = localStorage.getItem(`gf_cache_group_${groupId}`)
      const cachedStats = localStorage.getItem(`gf_cache_stats_${groupId}`)

      if (cachedGroup) {
        const parsedGroup = JSON.parse(cachedGroup) as Group
        queueMicrotask(() => setGroup(parsedGroup))
      }
      if (cachedStats) {
        const stats = JSON.parse(cachedStats)
        queueMicrotask(() => {
          setPersonalTaskCount(stats.personal || 0)
          setTotalBacklog(stats.backlog || 0)
          setProjectProgress(stats.progress || 0)
          setProgressLabel(stats.label || 'Just a moment...')
        })
      }
    } catch (e) {
      console.warn('Cache hydration failed defensively:', e)
    }
  }, [groupId])

  const fetchGroupDetails = useCallback(async () => {
    try {
      const data = await fetchGroupById(groupId)
      setGroup(data)
      localStorage.setItem(`gf_cache_group_${groupId}`, JSON.stringify(data))
    } catch (err) {
      console.error('Fetch group details error:', err instanceof Error ? err.message : err)
    }
  }, [groupId])

  const fetchMembers = useCallback(async () => {
    if (!groupId) return
    try {
      const data = await fetchGroupMembers(groupId)
      setMembers(data)
    } catch (err) {
      console.error('Error fetching group members:', err instanceof Error ? err.message : err)
    }
  }, [groupId])

  const fetchPendingRequests = useCallback(async () => {
    if (!groupId || profile?.role !== 'admin') return
    try {
      const data = await fetchPendingJoinRequests(groupId)
      setPendingRequests(data.map((request) => ({ ...request, profiles: request.profiles ?? undefined })))
    } catch (err) {
      console.error('Fetch pending requests error:', err instanceof Error ? err.message : err)
    }
  }, [groupId, profile?.role])

  const handleAcceptRequest = async (id: string) => {
    const { acceptJoinRequest } = await import('@/app/join/actions')
    const res = await acceptJoinRequest(id)
    if (res.error) {
      addToast('Oops, something went wrong', "We couldn't add the member right now. Let's try again.", 'error')
      return
    }

    addToast('All set!', 'Your teammate is now in the group.', 'success')
    void fetchMembers()
    void fetchPendingRequests()
  }

  const handleDeclineRequest = async (id: string) => {
    const { declineJoinRequest } = await import('@/app/join/actions')
    const res = await declineJoinRequest(id)
    if (res.error) {
      addToast('Slight issue', "We couldn't update the request. Please try again.", 'error')
      return
    }

    addToast('Request updated', 'The join request has been removed.', 'info')
    void fetchPendingRequests()
  }

  const fetchPersonalTaskCount = useCallback(async () => {
    if (!profile?.id || !groupId) return
    try {
      const pendingCount = await fetchPersonalPendingTaskCount(groupId, profile.id)
      setPersonalTaskCount(pendingCount)
    } catch (err) {
      console.warn('Silent failure on personal task count:', err instanceof Error ? err.message : err)
    }
  }, [profile?.id, groupId])

  const fetchProjectProgress = useCallback(async () => {
    if (!groupId) return
    try {
      const tasks = await fetchGroupTasks(groupId)

      if (tasks.length === 0) {
        setProjectProgress(0)
        setProgressLabel('Empty Backlog')
        setTotalBacklog(0)
        return
      }

      type Task = { status: string }
      const pending = tasks.filter((t: Task) => t.status !== 'Done').length
      setTotalBacklog(pending)

      const completed = tasks.filter((t: Task) => t.status === 'Done').length
      const progress = Math.round((completed / tasks.length) * 100)
      setProjectProgress(progress)

      let label = 'Almost finished'
      if (progress <= 30) label = 'Just starting'
      else if (progress <= 50) label = 'Making progress'
      else if (progress <= 80) label = 'Smoothing things out'

      setProgressLabel(label)

      localStorage.setItem(`gf_cache_stats_${groupId}`, JSON.stringify({
        personal: personalTaskCount,
        backlog: pending,
        progress,
        label,
      }))
    } catch (err) {
      console.error('Fetch project progress error:', err instanceof Error ? err.message : err)
    }
  }, [groupId, personalTaskCount])

  useEffect(() => {
    if (!groupId) return

    const initializeDashboardData = async () => {
      const tasks: Promise<unknown>[] = [
        fetchGroupDetails(),
        fetchMembers(),
        fetchPendingRequests(),
      ]

      if (profile?.id) {
        tasks.push(fetchPersonalTaskCount())
        tasks.push(fetchProjectProgress())
      }

      await Promise.all(tasks)
    }

    void initializeDashboardData()

    const pollId = window.setInterval(() => {
      void initializeDashboardData()
    }, 20000)

    return () => {
      window.clearInterval(pollId)
    }
  }, [
    profile?.id,
    groupId,
    fetchGroupDetails,
    fetchMembers,
    fetchPendingRequests,
    fetchPersonalTaskCount,
    fetchProjectProgress,
  ])

  return {
    personalTaskCount,
    group,
    newTaskSignal,
    setNewTaskSignal,
    syncToken,
    setSyncToken,
    members,
    pendingRequests,
    showMembers,
    setShowMembers,
    projectProgress,
    progressLabel,
    totalBacklog,
    handleAcceptRequest,
    handleDeclineRequest,
  }
}

