const ThemeContext = createContext<ThemeContextType | undefined>(undefined)

export const useTheme = () => {
  const context = useContext(ThemeContext)
  if (!context) throw new Error('useTheme must be used within ThemeProvider')
  return context
}

export type ThemeInitialValues = {
  palette?: string
  bgUrl?: string
}

export const ThemeProvider = ({ children, initialTheme, userPlan }: { children: React.ReactNode, initialTheme?: ThemeInitialValues, userPlan?: string | null }) => {
  // Use initialTheme for initial state to prevent flash during hydration
  const [currentPalette, setCurrentPalette] = useState<Palette>(() => {
    if (initialTheme?.palette) {
      return PALETTES.find(p => p.name === initialTheme.palette) || PALETTES[0]
    }
    // Fallback to system preference if no localStorage
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('espeezy_palette')
      if (saved) {
        const found = PALETTES.find(p => p.name === saved)
        if (found) return found
      }
      
      // Automatic A11y Sync: Check system preference
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches
      return prefersDark ? PALETTES[1] : PALETTES[0] // Deep Oceanic for dark, Google Light for light
    }
    return PALETTES[0]
  })
  
  const [customBg, setCustomBg] = useState<string | null>(initialTheme?.bgUrl || null)
  const db = createBrowserSupabaseClient()

  useEffect(() => {
    let mounted = true
    const restoreTheme = async () => {
      if (!mounted) return

      if (initialTheme?.palette) {
        const palette = PALETTES.find(p => p.name === initialTheme.palette)
        if (palette) setCurrentPalette(palette)
      }
      if (initialTheme?.bgUrl) setCustomBg(initialTheme.bgUrl)
    }

    void restoreTheme()
    return () => {
      mounted = false
    }
  }, [initialTheme])



  const setPalette = async (name: string) => {
    const palette = PALETTES.find(p => p.name === name)
    if (palette) {
      // Access Control Enforcement
      const tier = palette.tier || 'free'
      const isPremium = userPlan === 'premium'
      const isPro = userPlan === 'pro' || isPremium

      if (tier === 'premium' && !isPremium) {
        throw new Error('PREMIUM_LOCKED')
      }
      if (tier === 'pro' && !isPro) {
        throw new Error('PRO_LOCKED')
      }

      setCurrentPalette(palette)
      localStorage.setItem('espeezy_palette', name) 
      const { data: { user } } = await db.auth.getUser()
        if (user) {
          await db.from('profiles').update({ 
            theme_config: { palette: name } 
          }).eq('id', user.id)

          const { data: profile } = await db.from('profiles').select('group_id').eq('id', user.id).single()
          logActivity(user.id, profile?.group_id, 'theme_changed', `Changed palette to ${name}`)
        }
    }
  }

  const handleSetCustomBg = async (url: string | null) => {
    setCustomBg(url)
    if (url) localStorage.setItem('espeezy_bg', url)
    else localStorage.removeItem('espeezy_bg')
    
    const { data: { user } } = await db.auth.getUser()
    if (user) {
      await db.from('profiles').update({ 
        custom_bg_url: url 
      }).eq('id', user.id)
    }
  }

  const activeColors = currentPalette.colors

  return (
    <ThemeContext.Provider value={{ currentPalette, setPalette, customBg, setCustomBg: handleSetCustomBg }}>
      {/* 
          Injected style tag ensures variables are present BEFORE hydration finishes, 
          eliminating the theme flash (FOUC) entirely.
      */}
      <style dangerouslySetInnerHTML={{ __html: `
        :root {
          ${Object.entries(activeColors).map(([key, val]) => `${key}: ${val};`).join('\n')}
        }
      `}} />
      
      <div 
        className={`theme-wrapper ${customBg ? 'has-custom-bg' : ''}`}
        style={customBg ? { 
          backgroundImage: `url(${customBg})`, 
          backgroundSize: 'cover', 
          backgroundPosition: 'center', 
          backgroundAttachment: 'fixed',
          minHeight: '100vh' 
        } : {}}
      >
        {children}
      </div>
    </ThemeContext.Provider>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import type { LaunchConfig, TimeLeft } from '../types/launch'
import { fetchLaunchConfig, fetchLiveMetrics } from '../services/launch'

const ZERO_TIME: TimeLeft = { days: 0, hours: 0, minutes: 0, seconds: 0 }

export function useCountdown(targetDate: string): TimeLeft {
  const calc = useCallback(() => {
    const diff = new Date(targetDate).getTime() - Date.now()
    if (diff <= 0) return ZERO_TIME
    return {
      days: Math.floor(diff / 86_400_000),
      hours: Math.floor((diff % 86_400_000) / 3_600_000),
      minutes: Math.floor((diff % 3_600_000) / 60_000),
      seconds: Math.floor((diff % 60_000) / 1000),
    }
  }, [targetDate])

  // Start with zeros so SSR and client initial render match, then hydrate on client
  const [timeLeft, setTimeLeft] = useState<TimeLeft>(ZERO_TIME)

  useEffect(() => {
    setTimeLeft(calc())
    const id = setInterval(() => setTimeLeft(calc()), 1000)
    return () => clearInterval(id)
  }, [calc])

  return timeLeft
}

// Fixed launch date - update manually when the date changes
const DEFAULT_LAUNCH_DATE = '2026-06-01T00:00:00.000Z'

const DEFAULTS: LaunchConfig = {
  launch_date: DEFAULT_LAUNCH_DATE,
  launch_message: 'Something big is coming. Join the first 5,000 students shaping the future of collaborative education.',
  preregister_goal: '5000',
  brand_name: 'Espeezy',
}

export function useLaunchData() {
  const [config, setConfig] = useState<LaunchConfig>(DEFAULTS)
  const [registeredCount, setRegisteredCount] = useState(0)
  const [authUserCount, setAuthUserCount] = useState(0)
  const [configLoaded, setConfigLoaded] = useState(false)

  const setCountAndPersist = useCallback((count: number) => {
    setRegisteredCount(count)
    if (typeof window !== 'undefined') {
      window.localStorage.setItem('espeezy_last_registered_count', String(count))
    }
  }, [])

  const refreshCount = useCallback(async () => {
    try {
      const data = await fetchLiveMetrics()
      if (!data) return
      if (typeof data.preregistration_count === 'number') {
        setCountAndPersist(data.preregistration_count)
      } else if (typeof data.registered_count === 'number') {
        setCountAndPersist(data.registered_count)
      }
      if (typeof data.auth_user_count === 'number') {
        setAuthUserCount(data.auth_user_count)
      }
    } catch {
      // Keep previous value if live refresh fails.
    }
  }, [setCountAndPersist])

  useEffect(() => {
    const load = async () => {
      if (typeof window !== 'undefined') {
        const cached = Number(window.localStorage.getItem('espeezy_last_registered_count') ?? '0')
        if (Number.isFinite(cached) && cached > 0) {
          setRegisteredCount(cached)
        }
      }

      try {
        const [cfgPayload, metrics] = await Promise.all([
          fetchLaunchConfig(),
          fetchLiveMetrics(),
        ])
        const cfg = cfgPayload?.config
        if (cfg) {
          setConfig(prev => ({
            ...prev,
            ...cfg,
            launch_date: typeof cfg.launch_date === 'string' ? cfg.launch_date : DEFAULT_LAUNCH_DATE,
            preregister_goal: '5000',
          }))
        }
        if (!metrics) {
          setConfigLoaded(true)
          return
        }
        if (typeof metrics.preregistration_count === 'number') {
          setCountAndPersist(metrics.preregistration_count)
        } else if (typeof metrics.registered_count === 'number') {
          setCountAndPersist(metrics.registered_count)
        }
        if (typeof metrics.auth_user_count === 'number') {
          setAuthUserCount(metrics.auth_user_count)
        }
      } catch {
        // Use defaults on failure
      }
      setConfigLoaded(true)
    }
    load()

    // Poll every 30s so count stays fresh
    const pollId = setInterval(refreshCount, 30_000)
    // Re-fetch when the tab regains focus (e.g. returning from Stripe)
    window.addEventListener('focus', refreshCount)
    return () => {
      clearInterval(pollId)
      window.removeEventListener('focus', refreshCount)
    }
  }, [refreshCount])

  const timeLeft = useCountdown(config.launch_date)

  return { config, registeredCount, authUserCount, configLoaded, timeLeft, setRegisteredCount, refreshCount }
}

'use client'

import { useState, useEffect, useCallback, useMemo } from 'react'
import { createClient as createBrowserSupabaseClient } from '@/lib/supabase/client'
import { useSmartLoading } from '@/components/GlobalLoadingProvider'
import { useNotifications } from '@/components/NotificationProvider'
import { Listing, MarketplaceCategory } from '@/types/marketplace'
import { Profile } from '@/types/database'

export function useMarketplace() {
  const [listings, setListings] = useState<Listing[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [activeCategory, setActiveCategory] = useState<MarketplaceCategory>('All')
  const [isPosting, setIsPosting] = useState(false)
  const [showWalkthrough, setShowWalkthrough] = useState(false)
  const [selectedListing, setSelectedListing] = useState<Listing | null>(null)
  const db = useMemo(() => createBrowserSupabaseClient(), [])
  
  const { withLoading } = useSmartLoading()
  const { addToast } = useNotifications()

  const fetchListings = useCallback(async () => {
    setLoading(true)
    
    try {
      // Fetch marketplace_listings from Supabase
      const { data: listingsData, error: listingsError } = await db
        .from('marketplace_listings')
        .select('*')
        .order('created_at', { ascending: false })
      
      if (listingsError) {
        console.error('Fetch error:', listingsError.message)
        setListings([])
        return
      }

      if (!listingsData || listingsData.length === 0) {
        setListings([])
        localStorage.setItem('gf_marketplace_cache', JSON.stringify([]))
        return
      }

      // Extract unique owner IDs
      const ownerIds = Array.from(new Set(listingsData.map(l => l.owner_id).filter(Boolean)))

      if (ownerIds.length > 0) {
        // Fetch profiles for owner enrichment
        const { data: profilesData, error: profilesError } = await db
          .from('profiles')
          .select('*')
          .in('id', ownerIds)
        
        if (profilesError) {
          console.error('Profile fetch error:', profilesError)
          setListings(listingsData as Listing[])
        } else {
          const profileMap = (profilesData || []).reduce((acc: Record<string, Profile>, p) => {
            acc[p.id] = p as Profile
            return acc
          }, {})

          const merged = listingsData.map(l => ({
            ...l,
            profiles: profileMap[l.owner_id]
          })) as Listing[]

          setListings(merged)
          localStorage.setItem('gf_marketplace_cache', JSON.stringify(merged))
        }
      } else {
        setListings(listingsData as Listing[])
        localStorage.setItem('gf_marketplace_cache', JSON.stringify(listingsData))
      }
    } catch (err: unknown) {
      console.error('Fetch error:', err instanceof Error ? err.message : 'unknown error')
      setListings([])
    } finally {
      setLoading(false)
    }
  }, [db])

  useEffect(() => {
    const hasSeen = localStorage.getItem('gf_marketplace_onboarding')
    if (!hasSeen) {
      setShowWalkthrough(true)
      localStorage.setItem('gf_marketplace_onboarding', 'true')
    }

    const cached = localStorage.getItem('gf_marketplace_cache')
    if (cached) {
      try {
        setListings(JSON.parse(cached))
        setLoading(false)
      } catch (e) {
        console.error("Marketplace cache corrupted", e)
      }
    }

    void fetchListings()
  }, [fetchListings])

  const filteredListings = useMemo(() => {
    const query = searchQuery.toLowerCase()
    return listings.filter(l => {
      const matchesSearch = l.title.toLowerCase().includes(query) ||
                          l.description?.toLowerCase().includes(query)
      const matchesCategory = activeCategory === 'All' || l.category === activeCategory
      return matchesSearch && matchesCategory
    })
  }, [listings, searchQuery, activeCategory])

  return {
    listings,
    filteredListings,
    loading,
    searchQuery,
    setSearchQuery,
    activeCategory,
    setActiveCategory,
    isPosting,
    setIsPosting,
    showWalkthrough,
    setShowWalkthrough,
    selectedListing,
    setSelectedListing,
    fetchListings
  }
}

import { createClient as createBrowserSupabaseClient } from './supabase/client'
export { createBrowserSupabaseClient }

// Export a real Supabase client only. No shims.
export const db = createBrowserSupabaseClient()

// --- AUTH ---
export const auth = {
  get currentUser() {
    // Note: This is synchronous in Firebase but asynchronous in Supabase.
    // For now, we return a partial user from the current session if available.
    return (db as { _session?: { user?: { id?: string; email?: string } } })._session?.user || null
  },
  signOut: () => db.auth.signOut(),
  onAuthStateChanged: (cb: (user: { id?: string; email?: string } | null) => void) => {
    const { data } = db.auth.onAuthStateChange((_event, session) => {
      // Store session for the synchronous currentUser getter
      ;(db as { _session?: { user?: { id?: string; email?: string } } | null })._session = session
      cb(session?.user || null)
    })
    // Trigger immediate callback if session exists
    db.auth.getSession().then(({ data: { session } }) => {
      ;(db as { _session?: { user?: { id?: string; email?: string } } | null })._session = session
      cb(session?.user || null)
    })
    return { subscription: { unsubscribe: () => data.subscription.unsubscribe() } }
  },
}

export const onAuthStateChanged = auth.onAuthStateChanged;

// --- STORAGE ---
export const storage = db.storage
export const ref = (_storage: unknown, path: string) => path
export const uploadBytes = async (path: string, file: File | Blob | ArrayBuffer) => {
  const bucket = path.split('/')[0]
  const filePath = path.split('/').slice(1).join('/')
  return db.storage.from(bucket).upload(filePath, file)
}
export const getDownloadURL = async (path: string) => {
  const bucket = path.split('/')[0]
  const filePath = path.split('/').slice(1).join('/')
  const { data } = db.storage.from(bucket).getPublicUrl(filePath)
  return data.publicUrl
}
export const storageRef = ref

// --- DATABASE ---

// --- FIRESTORE HELPERS ---
// These helpers map Firestore-like syntax to Supabase calls.
// They are kept as thin wrappers to avoid refactoring 20+ files.

type QueryConstraint = { field?: string; op?: string; value?: unknown; limit?: number; dir?: string; columns?: string }
type QueryObject = { table: string; constraints: QueryConstraint[]; columns: string }

export const collection = (_db: unknown, name: string) => name
export const doc = (_db: unknown, name: string, id: string) => ({ table: name, id })
export const query = (table: string, ...constraints: QueryConstraint[]) => {
  const q: QueryObject = { table, constraints: [] as QueryConstraint[], columns: '*' }
  constraints.forEach(c => {
    if (c.columns) q.columns = c.columns
    else q.constraints.push(c)
  })
  return q
}
export const where = (field: string, op: string, value: unknown): QueryConstraint => ({ field, op, value })
export const limit = (n: number) => ({ limit: n })
export const orderBy = (field: string, dir: string) => ({ field, dir })
export const selectCols = (cols: string) => ({ columns: cols })

export interface FirestoreLikeDoc {
  id: string;
  data: () => Record<string, unknown>;
  exists: () => boolean;
  ref: { table: string; id: string };
}

export interface FirestoreLikeSnapshot {
  docs: FirestoreLikeDoc[];
  empty: boolean;
  size: number;
  docChanges: () => never[];
}

export const getDocs = async (q: QueryObject): Promise<FirestoreLikeSnapshot> => {
  let builder = db.from(q.table).select(q.columns || '*');
  if (q.constraints) {
    q.constraints.forEach((c) => {
      if ((c.op === '==' || c.op === 'eq') && c.field) builder = builder.eq(c.field, c.value);
      if (c.limit) builder = builder.limit(c.limit);
      if (c.field && c.dir) builder = builder.order(c.field, { ascending: c.dir === 'asc' });
    });
  }
  const { data } = await builder;
  const tableName = q.table;
  const docs: FirestoreLikeDoc[] = Array.isArray(data)
    ? data.map((d) => {
        const docData = d as unknown as Record<string, unknown>;
        return {
          id: String(docData.id),
          data: () => docData,
          exists: () => true,
          ref: { table: tableName, id: String(docData.id) },
        };
      })
    : [];
  return {
    docs,
    empty: docs.length === 0,
    size: docs.length,
    docChanges: () => [],
  };
};

export const getDoc = async (docRef: { table: string, id: string }, columns: string = '*') => {
  const { data } = await db.from(docRef.table).select(columns).eq('id', docRef.id).single()
  return {
    id: docRef.id,
    data: () => data,
    exists: () => !!data
  }
}

export const getCountFromServer = async (q: QueryObject | string) => {
  let builder = db.from(typeof q === 'string' ? q : q.table).select('id', { count: 'exact', head: true })
  if (typeof q !== 'string' && q.constraints) {
    q.constraints.forEach((c) => {
      if ((c.op === '==' || c.op === 'eq') && c.field) builder = builder.eq(c.field, c.value)
    })
  }
  const { count } = await builder
  return { data: () => ({ count: count || 0 }) }
}

export const onSnapshot = (q: QueryObject, cb: (snapshot: { docs: { id: string; data: () => Record<string, unknown>; exists: () => boolean; ref: { table: string; id: string } }[]; empty: boolean; size: number; docChanges: () => never[] }) => void) => {
  const channel = db.channel(`snapshot-${q.table}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: q.table }, () => {
      getDocs(q).then(cb)
    })
    .subscribe()

  getDocs(q).then(cb)
  return () => {
    void db.removeChannel(channel)
  }
}

export const setDoc = async (docRef: { table: string, id: string }, data: Record<string, unknown>) => {
  return db.from(docRef.table).upsert({ id: docRef.id, ...data })
}
export const updateDoc = async (docRef: { table: string, id: string }, data: Record<string, unknown>) => {
  return db.from(docRef.table).update(data).eq('id', docRef.id)
}
export const deleteDoc = async (docRef: { table: string, id: string }) => {
  return db.from(docRef.table).delete().eq('id', docRef.id)
}
export const addDoc = async (table: string, data: Record<string, unknown>) => {
  return db.from(table).insert(data)
}
export const writeBatch = (_db?: unknown) => {
  const operations: (() => Promise<unknown>)[] = []
  return {
    update: (docRef: { table: string, id: string }, data: Record<string, unknown>) => {
      operations.push(() => updateDoc(docRef, data))
    },
    set: (docRef: { table: string, id: string }, data: Record<string, unknown>) => {
      operations.push(() => setDoc(docRef, data))
    },
    delete: (docRef: { table: string, id: string }) => {
      operations.push(() => deleteDoc(docRef))
    },
    commit: async () => {
      for (const op of operations) {
        await op()
      }
    }
  }
}


